    getChatHistories() {
        const cached = this.getMigratedStateCacheValue('chats');
        const parsed = cached !== undefined ? cached : this.readLegacyMigratedState('chats');
        this._pendingChatHistories = parsed && typeof parsed === 'object' ? parsed : {};
        return this._pendingChatHistories;
    },
    saveChatHistories(histories, options = {}) {
        this._pendingChatHistories = histories && typeof histories === 'object' ? histories : {};
        const immediate = !!options.immediate;
        if (immediate) {
            return this.flushChatHistories();
        }
        if (this._chatHistoriesSaveTimer) return true;
        this._chatHistoriesSaveTimer = setTimeout(() => {
            this._chatHistoriesSaveTimer = null;
            this.flushChatHistories();
        }, 120);
        return true;
    },
    flushChatHistories() {
        if (this._chatHistoriesSaveTimer) {
            clearTimeout(this._chatHistoriesSaveTimer);
            this._chatHistoriesSaveTimer = null;
        }
        const next = this._pendingChatHistories && typeof this._pendingChatHistories === 'object' ? this._pendingChatHistories : {};
        this.setMigratedStateCacheValue('chats', next);
        this.queueMigratedStateWrite('chats', next);
        return true;
    },

