    getSummaryConfig() {
        const data = localStorage.getItem('wechat_summary_config');
        let parsed = null;
        if (data) {
            try {
                parsed = JSON.parse(data);
            } catch (e) {
                parsed = null;
            }
        }
        const raw = parsed && typeof parsed === 'object' ? parsed : {};
        // 默认按长上下文模型（如 Gemini）调优：约束关系 阈值 > 可见上下文 > 保留（500 > 300 > 200）
        const defaultThreshold = 500;
        const defaultKeep = 200;
        const defaultMiniMaxChars = 360;
        const defaultMegaMaxChars = 900;
        const defaultMegaTriggerCount = 10;
        const shouldMigrate = (raw.threshold === 50 && raw.keep === 10 && !raw._migrated_v2);
        if (shouldMigrate) {
            try {
                localStorage.setItem('wechat_summary_config', JSON.stringify({ ...raw, threshold: defaultThreshold, keep: defaultKeep, _migrated_v2: true }));
            } catch (e) {
            }
        }
        const keep = Math.max(0, parseInt((shouldMigrate ? defaultKeep : raw.keep) ?? defaultKeep, 10) || defaultKeep);
        const threshold = Math.max(1, parseInt((shouldMigrate ? defaultThreshold : raw.threshold) ?? defaultThreshold, 10) || defaultThreshold);
        // 字数限制：0 或非法值 = 不限字数（留空/0 都不注入字数要求）
        const normCharLimit = (rawValue, fallback) => {
            if (rawValue == null) return fallback;
            const n = parseInt(rawValue, 10);
            return Number.isFinite(n) && n > 0 ? n : 0;
        };
        const miniMaxChars = normCharLimit(raw.miniMaxChars, defaultMiniMaxChars);
        const megaMaxChars = normCharLimit(raw.megaMaxChars, defaultMegaMaxChars);
        const megaTriggerCount = Math.max(1, parseInt(raw.megaTriggerCount ?? defaultMegaTriggerCount, 10) || defaultMegaTriggerCount);
        const customPromptMini = replaceLegacyPromptVars(typeof raw.customPromptMini === 'string'
            ? raw.customPromptMini
            : (typeof raw.customPrompt === 'string' ? raw.customPrompt : ''));
        const customPromptMega = replaceLegacyPromptVars(typeof raw.customPromptMega === 'string' ? raw.customPromptMega : '');
        const normalizedRaw = {
            ...raw,
            customPromptMini,
            customPromptMega,
            customPrompt: customPromptMini
        };
        const shouldRewritePrompts =
            customPromptMini !== String((typeof raw.customPromptMini === 'string' ? raw.customPromptMini : (typeof raw.customPrompt === 'string' ? raw.customPrompt : '')) || '') ||
            customPromptMega !== String((typeof raw.customPromptMega === 'string' ? raw.customPromptMega : '') || '');
        if (shouldRewritePrompts) {
            try {
                localStorage.setItem('wechat_summary_config', JSON.stringify(normalizedRaw));
            } catch (e) {
            }
        }
        return {
            apiUrl: typeof raw.apiUrl === 'string' ? raw.apiUrl : '',
            apiKey: typeof raw.apiKey === 'string' ? raw.apiKey : '',
            model: typeof raw.model === 'string' ? raw.model : '',
            threshold,
            keep,
            miniMaxChars,
            megaMaxChars,
            megaTriggerCount,
            enabled: !!raw.enabled,
            autoMegaEnabled: raw.autoMegaEnabled !== false,
            customPromptMini,
            customPromptMega,
            customPrompt: customPromptMini,
            useMainApi: !!raw.useMainApi,
            mainApiId: (typeof raw.mainApiId === 'string' && raw.mainApiId.trim()) ? raw.mainApiId.trim() : 'current'
        };
    },
  saveSummaryConfig(config) {
        const raw = config && typeof config === 'object' ? { ...config } : {};
        raw.customPromptMini = replaceLegacyPromptVars(String(raw.customPromptMini || raw.customPrompt || ''));
        raw.customPromptMega = replaceLegacyPromptVars(String(raw.customPromptMega || ''));
        raw.customPrompt = raw.customPromptMini;
        localStorage.setItem('wechat_summary_config', JSON.stringify(raw));
    },
