            sceneNoteStackGap: clampInt(raw.sceneNoteStackGap ?? d.sceneNoteStackGap, 0, 20, d.sceneNoteStackGap),
            sceneNoteCardWidth: clampInt(raw.sceneNoteCardWidth ?? d.sceneNoteCardWidth, 0, 560, d.sceneNoteCardWidth),
