function parseOfflineComposerInput(text) {
    const lines = String(text || '').replace(/\r\n/g, '\n').split('\n');
    const items = [];
    const noteRegex = /^(动作|描写|旁白|状态|场景)\s*[：:]\s*(.+)$/;
    const speechRegex = /^(说|台词|对白)\s*[：:]\s*(.+)$/;
    lines.forEach((line) => {
        const value = String(line || '').trim();
        if (!value) return;
        const noteMatch = value.match(noteRegex);
        if (noteMatch) {
            items.push({ type: 'scene_note', actor: 'user', content: String(noteMatch[2] || '').trim() });
            return;
        }
        const speechMatch = value.match(speechRegex);
        if (speechMatch) {
            items.push({ type: 'text', content: String(speechMatch[2] || '').trim() });
            return;
        }
        items.push({ type: 'text', content: value });
    });
    return items.filter((item) => String(item?.content || '').trim());
}

function hasOfflineComposerSyntax(text) {
    return /(^|\n)\s*(动作|描写|旁白|状态|场景|说|台词|对白)\s*[：:]\s*\S+/m.test(String(text || ''));
}

function summarizeOfflineComposerItems(items) {
    const list = Array.isArray(items) ? items : [];
    const lastText = [...list].reverse().find((item) => item?.type === 'text' && String(item?.content || '').trim());
    if (lastText) return String(lastText.content || '').trim().slice(0, 80);
    const lastNote = [...list].reverse().find((item) => item?.type === 'scene_note' && String(item?.content || '').trim());
    return lastNote ? `[动作] ${String(lastNote.content || '').trim().slice(0, 60)}` : '[线下互动]';
}

function normalizeSceneNoteActor(actor, fallback = 'assistant') {
    const raw = String(actor || '').trim().toLowerCase();
    if (raw === 'user' || raw === 'assistant') return raw;
    return String(fallback || 'assistant').trim().toLowerCase() === 'user' ? 'user' : 'assistant';
}

function normalizeSceneNotePayload(item, fallbackActor = 'assistant') {
    if (!item || typeof item !== 'object' || String(item.type || '').trim() !== 'scene_note') return item;
    const actor = normalizeSceneNoteActor(item.actor, fallbackActor);
    const content = String(item.content ?? item.text ?? '').trim();
    return {
        ...item,
        type: 'scene_note',
        actor,
        content
    };
}

function renderSceneNoteForContext(item, options = {}) {
    const normalized = normalizeSceneNotePayload(item, options.fallbackActor || 'assistant');
    const noteText = String(normalized?.content || '').trim();
    const actorLabel = normalized?.actor === 'user' ? '{user}' : '{char}';
    const mode = String(options.sceneNoteMode || 'offline').trim().toLowerCase();
    if (mode === 'history_reference') {
        return noteText ? `此前线下片段（${actorLabel}）：${noteText}` : '此前有过线下片段';
    }
    return noteText ? `[线下描写|${actorLabel}] ${noteText}` : '[线下描写]';
}

function buildOfflineModePromptAddon(contact, config = getOfflineModeConfig(contact)) {
    const normalized = normalizeOfflineModeConfig(config);
    const charName = String(getContactDisplayName(contact) || contact?.name || '对方').trim() || '对方';
    const userProfile = getUserProfileForContact(contact);
    const userName = String(userProfile?.nickname || State.user?.nickname || '用户').trim() || '用户';
    const sceneRule = normalized.sceneMode === 'together'
        ? `- 当前固定为两人在线下同场互动，围绕同一个现场往下写，不要把 ${userName} 写成远程聊天。`
        : (normalized.sceneMode === 'apart'
            ? `- 当前固定为两人不在同一地点，不要把 ${userName} 写到 ${charName} 身边；重点写 ${charName} 此刻在做什么、想什么、怎么回。`
            : `- 当前场景由你结合最近消息自动判断：如果 ${userName} 的动作描写明显在现场，就写同场互动；否则写 ${charName} 自己此刻的线下状态。`);
    const templates = State.promptScenarioTemplates || Storage.DEFAULT_PROMPT_SCENARIO_TEMPLATES;
    const template = templates.offlineChat || Storage.DEFAULT_PROMPT_SCENARIO_TEMPLATES.offlineChat || '';
    return renderPromptTemplate(template, {
        char: charName,
        role: charName,
        user: userName,
        target_length: String(normalized.targetLength),
        scene_rule: sceneRule
    }).trim();
}

function hasOfflineSceneItems(history = [], triggerText = '') {
    const list = Array.isArray(history) ? history : [];
    if (String(triggerText || '').includes('[线下描写|')) return true;
    return list.some((msg) => {
        try {
            const parsed = JSON.parse(String(msg?.content || ''));
            return !!(parsed && typeof parsed === 'object' && String(parsed.type || '').trim() === 'scene_note');
        } catch (e) {
            return false;
        }
    });
}

function buildOnlineModeResetPromptAddon(contact) {
    const charName = String(getContactDisplayName(contact) || contact?.name || '对方').trim() || '对方';
    const userProfile = getUserProfileForContact(contact);
    const userName = String(userProfile?.nickname || State.user?.nickname || '用户').trim() || '用户';
    return [
        '【当前已切回普通线上聊天】',
        `- 之前历史里如果出现“此前线下片段（{user}）”或“此前线下片段（{char}）”，那只是 ${charName} 和 ${userName} 之前线下互动留下的旧记录，不代表这轮还在线下模式。`,
        '- 从这一轮开始，按普通微信线上聊天理解和回复。',
        '- 只输出正常可见的聊天气泡，不要继续输出 scene_note，不要写动作旁白，不要把当前回复写成现场演出。',
        '- 如果需要提到刚才线下发生过的事，可以像微信里正常聊天那样一句带过，不要继续写环境、距离、肢体动作、视线变化。'
    ].join('\n');
}

function buildGroupOfflineLocationPlan(session, member, config, userProfile) {
    const normalized = normalizeGroupOfflineModeConfig(config);
    const entries = getGroupOfflineParticipantEntries(session).map((entry) => ({ ...entry }));
    const memberKey = String(member?.id || '').trim();
    if (normalized.locationMode === 'auto') {
        return {
            text: [
                '【群聊线下地点安排】',
                '- 当前没有固定地点分组；根据最近群聊明确出现的地点和动作判断谁在同一现场。',
                '- 没有证据时默认大家不在同一地点，不要让成员瞬移，也不要凭空安排肢体接触。'
            ].join('\n'),
            currentLocation: '',
            coLocatedNames: []
        };
    }

    const assigned = entries.map((entry, index) => {
        let location = '';
        if (normalized.locationMode === 'all_together') location = '同一现场';
        else if (normalized.locationMode === 'separate') location = `独立地点-${index + 1}`;
        else location = String(normalized.participantLocations[entry.key] || '').trim();
        return { ...entry, location };
    });
    const groups = [];
    const groupMap = new Map();
    assigned.forEach((entry) => {
        const normalizedLocation = entry.location ? entry.location.toLocaleLowerCase() : `__solo__${entry.key}`;
        if (!groupMap.has(normalizedLocation)) {
            const group = { location: entry.location, entries: [] };
            groupMap.set(normalizedLocation, group);
            groups.push(group);
        }
        groupMap.get(normalizedLocation).entries.push(entry);
    });
    const current = assigned.find((entry) => entry.key === memberKey);
    const currentGroup = groups.find((group) => group.entries.some((entry) => entry.key === memberKey));
    const coLocatedNames = currentGroup && currentGroup.location
        ? currentGroup.entries.filter((entry) => entry.key !== memberKey).map((entry) => entry.name)
        : [];
    const lines = [
        '【群聊线下地点安排｜固定事实】',
        ...groups.map((group) => {
            const names = group.entries.map((entry) => entry.name).join('、');
            return group.location
                ? `- 地点「${group.location}」：${names}`
                : `- ${names}：单独在未指定地点，不与其他空白项自动视为同地`;
        }),
        current?.location
            ? `- 你（${getContactDisplayName(member)}）当前在「${current.location}」。`
            : `- 你（${getContactDisplayName(member)}）当前单独在一个未指定地点。`,
        coLocatedNames.length > 0
            ? `- 你可以直接看到并在线下接触的同地点成员：${coLocatedNames.join('、')}。`
            : '- 当前没有明确与你同地点的其他人；不要写面对面动作或身体接触。',
        '- 群消息仍然能被全群看到，但动作、视线、触碰和现场环境只能发生在同一地点的人之间。',
        '- 不同地点的人只能通过群消息了解对方公开说出的内容；不要让任何人瞬移或隔空看见另一个地点的动作。'
    ];
    return {
        text: lines.join('\n'),
        currentLocation: current?.location || '',
        coLocatedNames
    };
}

function buildGroupOfflineModePromptAddon(session, member, options = {}) {
    const normalized = normalizeGroupOfflineModeConfig(options.config || getGroupOfflineModeConfig(session));
    const userProfile = options.userProfile || getUserProfileForContact(member);
    const userName = String(userProfile?.nickname || State.user?.nickname || '用户').trim() || '用户';
    const memberName = String(getContactDisplayName(member) || member?.name || '群成员').trim() || '群成员';
    const groupName = String(getSessionDisplayName(session) || '群聊').trim() || '群聊';
    const locationPlan = buildGroupOfflineLocationPlan(session, member, normalized, userProfile);
    const templates = State.promptScenarioTemplates || Storage.DEFAULT_PROMPT_SCENARIO_TEMPLATES;
    const template = templates.groupOffline || Storage.DEFAULT_PROMPT_SCENARIO_TEMPLATES.groupOffline || '';
    const memberBoundary = `- 你始终只写 ${memberName} 自己的动作和台词；即使同地点还有其他人，也不能替他们行动或说话。`;
    const sceneRule = template.includes('{location_layout}')
        ? memberBoundary
        : `${locationPlan.text}\n${memberBoundary}`;
    return renderPromptTemplate(template, {
        char: memberName,
        role: memberName,
        member_name: memberName,
        user: userName,
        group_name: groupName,
        target_length: String(normalized.targetLength),
        location_layout: locationPlan.text,
        scene_rule: sceneRule
    }).trim();
}

function buildGroupOnlineModeResetPromptAddon(session, member, options = {}) {
    const userProfile = options.userProfile || getUserProfileForContact(member);
    const userName = String(userProfile?.nickname || State.user?.nickname || '用户').trim() || '用户';
    const memberName = String(getContactDisplayName(member) || member?.name || '群成员').trim() || '群成员';
    const groupName = String(getSessionDisplayName(session) || '群聊').trim() || '群聊';
    return [
        '【当前已切回普通群聊线上聊天】',
        `- 历史里如果出现“此前线下片段（{user}）”或“此前线下片段（{char}）”，那只是 ${groupName} 之前线下互动留下的旧记录，不代表这轮还在线下模式。`,
        `- 你现在扮演群成员 ${memberName}，从这一轮开始按普通微信群聊回复。`,
        `- 不要继续输出 scene_note，不要写动作旁白，不要把 ${userName} 或其他群成员继续写成同一个现场里的线下演出。`,
        '- 如果要提到前面线下发生过的事，只能用正常群聊口吻简短接一句，不要继续扩写现场气氛、动作或肢体细节。'
    ].join('\n');
}

function renderUnrestrictedSchemeList() {
    const listEl = document.getElementById('unrestricted-scheme-list');
    const metaEl = document.getElementById('unrestricted-selected-count');
    const toggleEl = document.getElementById('unrestricted-master-toggle');
    if (!listEl || !metaEl || !toggleEl) return;

    State.unrestrictedConfig = normalizeUnrestrictedConfig(State.unrestrictedConfig);
    const summary = getUnrestrictedSelectionSummary();
    const config = summary.normalized;
    const activeSet = new Set(config.activeSchemeIds || []);

    toggleEl.classList.toggle('active', !!config.enabled);
    if (!config.schemes.length) {
        metaEl.textContent = config.enabled ? '已开启，但还没有任何方案' : '还没有方案';
        listEl.innerHTML = '<div class="unrestricted-empty">先新增一个方案吧。<br>你写进去的内容会原样放到所有模式提示词最前面。</div>';
        return;
    }

    metaEl.textContent = config.enabled
        ? (summary.enabledCount > 0 ? `已开启，当前启用 ${summary.enabledCount} 个方案` : '已开启，但还没有勾选可用方案')
        : `已保存 ${summary.totalCount} 个方案，当前总开关关闭`;

    listEl.innerHTML = config.schemes.map((scheme) => {
        const selected = activeSet.has(scheme.id);
        const trimmedContent = String(scheme.content || '').trim();
        const previewText = trimmedContent
            ? trimmedContent.replace(/\s+/g, ' ').slice(0, 120)
            : '内容为空，保存后不会注入到提示词。';
        const metaText = trimmedContent ? `${trimmedContent.length} 字` : '空内容';
        return `
            <div class="unrestricted-scheme-item ${selected ? 'active' : ''}" data-id="${encodeURIComponent(scheme.id)}">
                <label class="unrestricted-scheme-main">
                    <input type="checkbox" class="unrestricted-scheme-checkbox" ${selected ? 'checked' : ''}>
                    <div class="unrestricted-scheme-copy">
                        <div class="unrestricted-scheme-title-row">
                            <span class="unrestricted-scheme-name">${escapeHtml(scheme.name)}</span>
                            <span class="unrestricted-scheme-meta">${escapeHtml(metaText)}</span>
                        </div>
                        <div class="unrestricted-scheme-preview">${escapeHtml(previewText)}</div>
                    </div>
                </label>
                <div class="unrestricted-scheme-actions">
                    <button type="button" class="unrestricted-link-btn" data-action="edit">编辑</button>
                    <button type="button" class="unrestricted-link-btn danger" data-action="delete">删除</button>
                </div>
            </div>
        `;
    }).join('');
}

function openUnrestrictedModal() {
    const modal = document.getElementById('unrestricted-modal');
    if (!modal) return;
    renderUnrestrictedSchemeList();
    modal.classList.add('show');
}

function closeUnrestrictedModal() {
    document.getElementById('unrestricted-modal')?.classList.remove('show');
}

function openUnrestrictedEditModal(schemeId = '') {
    const modal = document.getElementById('unrestricted-edit-modal');
    const titleEl = document.getElementById('unrestricted-edit-title');
    const nameEl = document.getElementById('unrestricted-edit-name');
    const contentEl = document.getElementById('unrestricted-edit-content');
    const deleteBtn = document.getElementById('unrestricted-edit-delete-btn');
    if (!modal || !titleEl || !nameEl || !contentEl || !deleteBtn) return;

    State.unrestrictedConfig = normalizeUnrestrictedConfig(State.unrestrictedConfig);
    const scheme = State.unrestrictedConfig.schemes.find((item) => item.id === schemeId) || null;
    modal.dataset.editingId = scheme?.id || '';
    titleEl.textContent = scheme ? '编辑方案' : '新增方案';
    nameEl.value = scheme?.name || '';
    contentEl.value = scheme?.content || '';
    deleteBtn.style.display = scheme ? '' : 'none';
    modal.classList.add('show');
    setTimeout(() => {
        if (scheme && contentEl.value.trim()) contentEl.focus();
        else nameEl.focus();
    }, 30);
}

function closeUnrestrictedEditModal() {
    const modal = document.getElementById('unrestricted-edit-modal');
    if (!modal) return;
    modal.classList.remove('show');
    delete modal.dataset.editingId;
}

function renderPromptTemplate(input, vars = {}) {
    const text = replaceLegacyPromptVars(String(input ?? ''));
    return text.replace(/\{([^{}]+)\}/g, (m, keyRaw) => {
        const key = String(keyRaw || '').trim();
        if (!key) return m;
        if (Object.prototype.hasOwnProperty.call(vars, key)) return String(vars[key] ?? '');
        const lowered = key.toLowerCase();
        if (Object.prototype.hasOwnProperty.call(vars, lowered)) return String(vars[lowered] ?? '');
        return m;
    });
}

function getScenarioPromptVars(contact, extra = {}) {
    const now = extra.now instanceof Date ? extra.now : new Date();
    const roleName = String(contact?.name || '联系人').trim() || '联系人';
    const persona = String(contact?.persona || '').trim();
    const style = String(contact?.style || '').trim();
    const userProfile = typeof getUserProfileForContact === 'function'
        ? getUserProfileForContact(contact || {})
        : (State.user || {});
    const userBaseName = String(userProfile?.nickname || State.user?.nickname || '用户').trim() || '用户';
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || 'Local';
    const vars = {
        char: roleName,
        user: userBaseName,
        wxid: userProfile?.wxid || State.user?.wxid || '',
        persona: persona || '（未填写）',
        style: style || '自然、口语化',
        date: now.toLocaleDateString('zh-CN'),
        time: `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`,
        date_time: now.toLocaleString('zh-CN', { hour12: false }),
        timezone: tz,
        period_label: getRealtimePeriodLabel(now)
    };
    return { ...vars, ...(extra || {}) };
}

