function getPromptPreviewContact() {
    const pageTarget = getPageTarget('prompt-page');
    if (pageTarget?.id && !isGroupSession(pageTarget)) return pageTarget;
    const currentPrivate = getCurrentPrivateContact();
    if (currentPrivate) return currentPrivate;
    if (State.currentContactId) {
        const current = State.contacts.find(c => c.id === State.currentContactId);
        if (current) return current;
    }
    if (State.contacts.length > 0) return State.contacts[0];
    return {
        id: 'preview_contact',
        name: 'AI角色',
        persona: '你是一个AI助手',
        style: '友好、自然',
        linkedWorldbooks: []
    };
}

function resolveTargetEntityById(targetId, targetType = '') {
    const id = String(targetId || '').trim();
    const type = String(targetType || '').trim();
    if (!id) return null;
    if (type === 'group') {
        const session = typeof getSessionById === 'function' ? getSessionById(id) : null;
        return isGroupSession(session) ? session : null;
    }
    if (type === 'contact') {
        return (State.contacts || []).find((item) => String(item?.id || '') === id) || null;
    }
    const session = typeof getSessionById === 'function' ? getSessionById(id) : null;
    if (isGroupSession(session)) return session;
    return (State.contacts || []).find((item) => String(item?.id || '') === id) || null;
}

function getEntityDisplayName(target) {
    if (isGroupSession(target)) return getSessionDisplayName(target);
    return getContactDisplayName(target);
}

function updateMemoryViewTitle(target) {
    const titleEl = document.getElementById('memory-view-title');
    if (!titleEl) return;
    titleEl.textContent = target?.id
        ? `以往记忆 · ${getEntityDisplayName(target)}`
        : '以往记忆';
}

function updatePromptViewTitle(target) {
    const titleEl = document.getElementById('prompt-view-title');
    if (!titleEl) return;
    titleEl.textContent = target?.id
        ? `查看提示词 · ${getEntityDisplayName(target)}`
        : '查看提示词';
}

function setPageTarget(pageId, target, targetType = '') {
    const page = document.getElementById(pageId);
    if (!page) return;
    const id = String(target?.id || '').trim();
    page.dataset.targetId = id;
    page.dataset.targetType = targetType || (isGroupSession(target) ? 'group' : 'contact');
}

function getPageTarget(pageId) {
    const page = document.getElementById(pageId);
    if (!page) return null;
    return resolveTargetEntityById(page.dataset.targetId, page.dataset.targetType);
}

