    if (!isGroupSession(session)) return;
    const rawMode = String(document.getElementById('group-reply-mode-select')?.value || 'natural');
    session.groupReplyMode = ['natural', 'mention_only', 'all'].includes(rawMode) ? rawMode : 'natural';
