function getLatestGroupUserTriggerText(session) {
    const history = getSessionHistory(session?.id).slice().reverse();
    const lastUserMessage = history.find((msg) => msg?.role === 'user');
    return lastUserMessage ? toPlainTextFromStoredContent(lastUserMessage.content) : '';
}

function getGroupMemberMentionAliases(member) {
    const name = String(getContactDisplayName(member) || '').trim();
    const rawName = String(member?.name || '').trim();
    const remarkName = String(member?.remarkName || '').trim();
    return Array.from(new Set([
        name ? `@${name}` : '',
        name ? `＠${name}` : '',
        rawName ? `@${rawName}` : '',
        rawName ? `＠${rawName}` : '',
        remarkName ? `@${remarkName}` : '',
        remarkName ? `＠${remarkName}` : ''
    ].filter(Boolean)));
}

function getMentionedGroupMembers(session, userText = '') {
    const members = getGroupMemberContacts(session);
    const text = String(userText || '').trim();
    if (!text) return [];
    const candidates = [];
    members.forEach((member) => {
        getGroupMemberMentionAliases(member).forEach((alias) => {
            let fromIndex = 0;
            while (fromIndex < text.length) {
                const matchedIndex = text.indexOf(alias, fromIndex);
                if (matchedIndex < 0) break;
                candidates.push({ member, alias, matchedIndex, endIndex: matchedIndex + alias.length });
                fromIndex = matchedIndex + Math.max(1, alias.length);
            }
        });
    });
    const accepted = candidates.filter((candidate) => !candidates.some((other) => {
        if (other === candidate) return false;
        if (other.matchedIndex !== candidate.matchedIndex) return false;
        return other.alias.length > candidate.alias.length;
    }));
    const firstByMemberId = new Map();
    accepted.forEach((candidate) => {
        const memberId = String(candidate.member?.id || '');
        const current = firstByMemberId.get(memberId);
        if (!current || candidate.matchedIndex < current.matchedIndex) firstByMemberId.set(memberId, candidate);
    });
    return Array.from(firstByMemberId.values())
        .sort((a, b) => a.matchedIndex - b.matchedIndex || b.alias.length - a.alias.length)
        .map((item) => item.member);
}

function selectGroupReplyMembers(session, userText = '') {
    const members = getGroupMemberContacts(session);
    if (members.length === 0) return [];
    const settings = getGroupReplySettings(session);
    const cursor = Math.max(0, parseInt(session.replyCursor ?? 0, 10) || 0);
    const rotated = members.map((_, idx) => members[(cursor + idx) % members.length]);
    const mentioned = getMentionedGroupMembers(session, userText);
    const mentionedIds = new Set(mentioned.map((member) => String(member?.id || '')));
    const remaining = rotated.filter((member) => !mentionedIds.has(String(member?.id || '')));
    let selected = [];

    if (settings.mode === 'all') {
        selected = [...mentioned, ...remaining];
    } else if (mentioned.length > 0) {
        selected = mentioned.slice();
        if (settings.mode === 'natural') {
            const automaticSlots = Math.max(0, settings.maxParticipants - selected.length);
            for (let slot = 0; slot < automaticSlots && slot < remaining.length; slot++) {
                if (Math.random() * 100 < settings.bystanderChance) selected.push(remaining[slot]);
            }
        }
    } else {
        const primary = rotated[0];
        if (primary) selected.push(primary);
        if (settings.mode === 'natural') {
            const candidates = rotated.slice(1);
            const automaticSlots = Math.max(0, settings.maxParticipants - 1);
            for (let slot = 0; slot < automaticSlots && slot < candidates.length; slot++) {
                if (Math.random() * 100 < settings.bystanderChance) selected.push(candidates[slot]);
            }
        }
    }

    session.replyCursor = (cursor + 1) % Math.max(1, members.length);
    Storage.saveSessions(State.sessions);
    return selected;
}

async function runGroupAiReply(session, options = {}) {
    if (!isGroupSession(session)) return;
    const sid = String(session.id || '');
    if (!sid) return;
    if (isAiRunningForSession(sid)) {
        showToast('正在生成中...');
        return;
    }
    const controller = new AbortController();
    const triggerText = String(options.userText || '').trim() || getLatestGroupUserTriggerText(session);
    const orderedMembers = selectGroupReplyMembers(session, triggerText);
    if (orderedMembers.length === 0) {
        showToast('群里还没有可回复的成员');
        return;
    }
    const mentionedMembers = getMentionedGroupMembers(session, triggerText);
    const mentionedMemberIds = mentionedMembers.map((member) => String(member?.id || ''));
    const historyBefore = getSessionHistory(sid).length;
    setAiTaskForSession(sid, controller, { kind: 'group', nativeLabel: `${getSessionDisplayName(session)} 正在生成群聊回复` });
    try {
        delete State.aiInterrupted[sid];
        const respondedMemberIds = [];
        const traceBlocks = [];
        // 群总结属于同一个公开群聊：每轮只检索一次，所有本轮发言成员复用同一份结果。
        const groupRecallHistory = getGroupAiVisibleHistory(session, orderedMembers[0]);
        const groupRecallQueryText = buildMemoryRecallQueryText(groupRecallHistory, triggerText);
        const recalledGroupSummaryText = await recallSummaryChunks(session, groupRecallQueryText, 2);
        for (let i = 0; i < orderedMembers.length; i++) {
            const member = orderedMembers[i];
            const memberHistory = getGroupAiVisibleHistory(session, member);
            let recalledPrivateSummaryText = '';
            const privateContextLimit = getGroupPrivateContextLimit(session, member);
            if (privateContextLimit > 0) {
                // 私聊总结严格按当前发言成员检索，绝不放进其他成员的提示词。
                const privateHistory = takeLatestContextUnits(getAiVisibleHistory(member.id), privateContextLimit);
                const privateRecallQueryText = buildMemoryRecallQueryText(privateHistory, triggerText);
                recalledPrivateSummaryText = await recallSummaryChunks(member, privateRecallQueryText, 2);
            }
            const promptBundle = buildGroupReplyPromptBundle(session, member, {
                history: memberHistory,
                triggerText,
                summaryMemoryText: recalledGroupSummaryText,
                privateSummaryMemoryText: recalledPrivateSummaryText,
                mentionedMemberIds,
                respondedMemberIds: respondedMemberIds.slice(),
                participantIndex: i,
                participantTotal: orderedMembers.length
            });
            traceBlocks.push(`【群成员：${getContactDisplayName(member)}】\n${promptBundle.traceText}`);
            const result = await fetchGroupAIResponse(session, member, {
                signal: controller.signal,
                triggerText,
                mentionedMemberIds,
                respondedMemberIds: respondedMemberIds.slice(),
                participantIndex: i,
                participantTotal: orderedMembers.length,
                promptBundle
            });
            if (result?.replied) respondedMemberIds.push(String(member?.id || ''));
        }
        if (traceBlocks.length > 0) {
            rememberPromptTrace(session.id, 'chat', traceBlocks.join('\n\n'), { label: '群聊互动' });
        }
        maybeQueueAutoSummaryForTarget(session);
        const newMessages = getSessionHistory(sid).slice(historyBefore);
        const notificationPreview = getNativeReplyPreview(newMessages, { group: true, maxItems: 3 });
        if (notificationPreview) showNativeAiReplyNotification(getSessionDisplayName(session), notificationPreview);
    } catch (e) {
        const isAbort = e && (e.name === 'AbortError' || String(e.message || '').toLowerCase().includes('aborted'));
        if (isAbort) {
            State.aiInterrupted[sid] = true;
            if (String(State.currentSessionId || '') === sid) showToast('已中断');
            return;
        }
        if (!options.silent) {
            showModelErrorDialog('群聊回复失败', normalizeModelErrorText(e));
        }
        return;
    } finally {
        clearAiTaskForSession(sid, controller);
        if (String(State.currentSessionId || '') === String(session.id || '')) {
            hideTypingIndicator();
            clearAssistantTypingBubble();
        }
    }
}

async function fetchGroupAIResponse(session, member, options = {}) {
    const currentApiConfig = State.apiConfigs.find(c => c.id === State.currentApiId);
    const useProxy = !!currentApiConfig?.useProxy;
    const targetUrl = useProxy ? String(currentApiConfig?.proxyUrl || '').trim() : normalizeChatCompletionsUrl(String(currentApiConfig?.apiUrl || '').trim());
    const apiKey = String(currentApiConfig?.apiKey || '').trim();
    if (!currentApiConfig || !targetUrl || (!useProxy && !apiKey)) {
        throw new Error('API未配置');
    }
    const promptBundle = options.promptBundle || buildGroupReplyPromptBundle(session, member, options);
    const systemPrompt = promptBundle.systemPrompt;
    const userPrompt = promptBundle.userPrompt;
    State.lastSentSystemPrompt[session.id] = systemPrompt;
    if (!State.lastStickerPromptCandidates) State.lastStickerPromptCandidates = {};
    State.lastStickerPromptCandidates[String(member?.id || '')] = Array.isArray(promptBundle.stickerCandidates) ? promptBundle.stickerCandidates : [];
    const payload = {
        model: String(currentApiConfig.model || '').trim() || 'gpt-3.5-turbo',
        messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: userPrompt }
        ]
    };
    const headers = { 'Content-Type': 'application/json' };
    if (!useProxy) headers.Authorization = `Bearer ${apiKey}`;
    if (String(State.currentSessionId || '') === String(session.id || '')) {
        setTypingIndicator(`${getContactDisplayName(member)} 正在输入...`);
    }
    try {
        const response = await fetch(targetUrl, {
            method: 'POST',
            headers,
            signal: options.signal,
            body: JSON.stringify(payload)
        });
        if (!response.ok) {
            let errMsg = `HTTP ${response.status}`;
            try {
                const errText = await response.text();
                if (errText) {
                    try {
                        const errData = JSON.parse(errText);
                        errMsg = String(errData?.error?.message || errData?.error || errData?.message || errText).trim();
                    } catch (e2) {
                        errMsg = errText.trim();
                    }
                }
            } catch (e) {
            }
            throw new Error(errMsg);
        }
        const data = await response.json();
        const reply = String(
            data?.choices?.[0]?.message?.content
            || data?.choices?.[0]?.text
            || data?.message?.content
            || data?.output_text
            || data?.result
            || ''
        ).trim();
        let cleanedReply = reply.replace(/^```json\s*/, '').replace(/```\s*$/, '');
        const explicitRuntimeIntent = detectExplicitRuntimeIntentFromText(options.triggerText || '');
        const isExplicitRuntimeOwner = Math.max(0, Number(options.participantIndex || 0)) === 0;
        if (isExplicitRuntimeOwner && (explicitRuntimeIntent.callType || explicitRuntimeIntent.avatarRequested)) {
            let isJsonArrayReply = false;
            try {
                isJsonArrayReply = Array.isArray(JSON.parse(cleanedReply));
            } catch (e) {
            }
            if (!isJsonArrayReply) {
                const visibleText = isRuntimeActionRefusalText(cleanedReply)
                    ? (explicitRuntimeIntent.callType
                        ? (explicitRuntimeIntent.callType === 'video' ? '好，我现在发起视频。' : '好，我现在打过来。')
                        : '好，已经换成这张了。')
                    : (cleanedReply || (explicitRuntimeIntent.callType ? '好，我现在打过来。' : '好，已经换成这张了。'));
                const forcedItems = [{ type: 'text', content: visibleText }];
                if (explicitRuntimeIntent.callType) {
                    forcedItems.push({ type: 'action', command: 'WX_CALL_START', callType: explicitRuntimeIntent.callType });
                }
                if (explicitRuntimeIntent.avatarRequested) {
                    forcedItems.push({ type: 'action', command: 'WX_AVATAR_SET', source: 'last_user_image' });
                }
                cleanedReply = JSON.stringify(forcedItems);
            }
        }
        let output = [];
        let parsedArrayHandled = false;
        const canRetryNoReply = !options.__noReplyRetried;
        try {
            const parsed = JSON.parse(cleanedReply);
            const parsedItems = Array.isArray(parsed) ? parsed : (parsed && typeof parsed === 'object' ? [parsed] : null);
            if (parsedItems) {
                parsedArrayHandled = true;
                let parsedArr = normalizeQuoteMessagesInPayload(
                    normalizePseudoMediaMessagesInPayload(
                        normalizeStickerMessagesInPayload(parsedItems.slice(), member.id)
                    ),
                    session.id
                );
                const groupOfflineActive = getGroupOfflineModeConfig(session).enabled;
                parsedArr = normalizeGroupOfflineResponseItems(parsedArr, groupOfflineActive);
                let visibleItems = parsedArr.filter((item) => !(item && typeof item === 'object' && item.type === 'thought_state'));
                const isNoReply = visibleItems.length === 1
                    && visibleItems[0]
                    && typeof visibleItems[0] === 'object'
                    && visibleItems[0].type === 'action'
                    && String(visibleItems[0].command || '').toUpperCase() === 'NO_REPLY';
                if (isNoReply) {
                    const nowTs = Date.now();
                    const cooldownMin = Math.max(1, Math.min(120, parseInt(member?.noReplyCooldownMin ?? 10, 10) || 10));
                    const cooldownMs = cooldownMin * 60 * 1000;
                    const lastNoReplyAt = Number(member?.lastNoReplyAt || 0) || 0;
                    const inCooldown = lastNoReplyAt && (nowTs - lastNoReplyAt) < cooldownMs;
                    if (!member?.allowSeenNoReply || inCooldown) {
                        if (canRetryNoReply) {
                            const retryOptions = { ...options, __noReplyRetried: true, forceReply: true };
                            delete retryOptions.promptBundle;
                            return fetchGroupAIResponse(session, member, retryOptions);
                        }
                        member.lastActiveAt = nowTs;
                        Storage.saveContacts(State.contacts);
                        return { replied: false, noReply: true, forcedRetryFailed: true };
                    }
                    member.lastNoReplyAt = nowTs;
                    member.lastActiveAt = nowTs;
                    Storage.saveContacts(State.contacts);
                    return { replied: false, noReply: true };
                }
                const actionItems = parsedArr.filter((item) => item && typeof item === 'object' && item.type === 'action');
                let callStarted = false;
                let avatarChanged = false;
                for (const act of actionItems) {
                    const cmd = String(act.command || '').toUpperCase();
                    if (cmd === 'WX_MONEY_ACCEPT') {
                        if (options.allowMoneyActions === false) continue;
                        const kind = String(act.kind || '').toLowerCase();
                        if (kind !== 'transfer' && kind !== 'redpacket') continue;
                        const updated = markOutgoingWxMoneyAccepted(session.id, kind, {
                            actorName: getContactDisplayName(member)
                        });
                        if (!updated) continue;
                        if (!parsedArr.some((x) => x && typeof x === 'object' && (x.type === 'text' || x.type === 'text_message') && typeof x.content === 'string' && x.content.trim())) {
                            parsedArr.unshift({
                                type: 'text',
                                content: kind === 'transfer' ? '我收到了。' : '我领到啦。'
                            });
                        }
                    } else if (cmd === 'WX_PAT') {
                        if (member.aiPatEnabled === false) continue;
                        triggerPatEvent(member, 'assistant', {
                            historyId: session.id,
                            displayName: getContactDisplayName(member),
                            target: session
                        });
                    } else if (cmd === 'WX_RECALL_LAST') {
                        if (member.aiRecallEnabled === false) continue;
                        recallLatestGroupMessageBySender(session.id, member.id, {
                            actorLabel: getContactDisplayName(member)
                        });
                    } else if (cmd === 'WX_RECALL_OFFSET') {
                        if (member.aiRecallEnabled === false) continue;
                        const offset = act.offsetFromLast ?? act.offset ?? 0;
                        recallGroupMessageBySenderOffset(session.id, member.id, offset, {
                            actorLabel: getContactDisplayName(member)
                        });
                    } else if (cmd === 'WX_CALL_START') {
                        const callType = String(act.callType || '').toLowerCase();
                        if (callType === 'voice' || callType === 'video') {
                            startIncomingCallFromGroupMember(session, member, callType);
                            callStarted = true;
                            if (!parsedArr.some((x) => x && typeof x === 'object' && (x.type === 'text' || x.type === 'text_message') && typeof x.content === 'string' && x.content.trim())) {
                                parsedArr.unshift({
                                    type: 'text',
                                    content: callType === 'video' ? '我给你打个视频。' : '我给你打个语音。'
                                });
                            }
                        }
                    } else if (cmd === 'WX_REMARK_SET') {
                        applyGroupRemarkSet(session, member, act);
                    } else if (cmd === 'WX_AVATAR_SET') {
                        avatarChanged = applyGroupAvatarSet(session, member, act) || avatarChanged;
                    }
                }
                if (isExplicitRuntimeOwner && explicitRuntimeIntent.callType && !callStarted) {
                    startIncomingCallFromGroupMember(session, member, explicitRuntimeIntent.callType);
                    callStarted = true;
                }
                if (isExplicitRuntimeOwner && explicitRuntimeIntent.avatarRequested && !avatarChanged) {
                    avatarChanged = applyGroupAvatarSet(session, member, { source: 'last_user_image' });
                }
                if (isExplicitRuntimeOwner && ((explicitRuntimeIntent.callType && callStarted) || (explicitRuntimeIntent.avatarRequested && avatarChanged))) {
                    parsedArr = parsedArr.filter((item) => {
                        if (!item || typeof item !== 'object') return true;
                        if (item.type !== 'text' && item.type !== 'text_message') return true;
                        return !isRuntimeActionRefusalText(item.content);
                    });
                    const hasNaturalText = parsedArr.some((item) => item && typeof item === 'object'
                        && (item.type === 'text' || item.type === 'text_message')
                        && String(item.content || '').trim());
                    if (!hasNaturalText) {
                        parsedArr.unshift({
                            type: 'text',
                            content: explicitRuntimeIntent.callType
                                ? (explicitRuntimeIntent.callType === 'video' ? '好，我现在发起视频。' : '好，我现在打过来。')
                                : '好，已经换成这张了。'
                        });
                    }
                }
                if (!groupOfflineActive && options.allowMoneyActions !== false) {
                    const accepted = ensureLatestOutgoingWxMoneyAccepted(session.id, getContactDisplayName(member));
                    if (accepted?.result && !parsedArr.some((x) => x && typeof x === 'object' && (x.type === 'text' || x.type === 'text_message') && typeof x.content === 'string' && x.content.trim())) {
                        parsedArr.unshift({
                            type: 'text',
                            content: accepted.kind === 'transfer' ? '我收到了。' : '我领到啦。'
                        });
                    }
                }
                visibleItems = parsedArr.filter((item) => !(item && typeof item === 'object' && item.type === 'thought_state'));
                output = expandAiDisplayItems(
                    visibleItems.filter((item) => !(item && typeof item === 'object' && item.type === 'action')),
                    { maxLen: 22, maxItems: 10, maxItemsTotal: 20 }
                );
            }
        } catch (err) {
        }
        if (output.length === 0 && parsedArrayHandled) {
            return { replied: false, empty: true };
        }
        if (output.length === 0) {
            const list = splitAiTextToBubbles(cleanedReply, { maxLen: 24, maxItems: 4 }).filter(Boolean);
            output = list.length > 0 ? list.map((line) => ({ type: 'text', content: line })) : [{ type: 'text', content: '收到' }];
        }
        if (!State.chatHistories[session.id]) State.chatHistories[session.id] = [];
        const baseTs = Date.now();
        output.forEach((item, idx) => {
            const stored = (item && typeof item === 'object')
                ? JSON.stringify(item)
                : JSON.stringify({ type: 'text', content: String(item || '') });
            State.chatHistories[session.id].push({
                role: 'assistant',
                content: stored,
                time: baseTs + idx,
                senderId: member.id
            });
        });
        Storage.saveChatHistories(State.chatHistories);
        const lastItem = output[output.length - 1];
        const previewText = (() => {
            if (lastItem && typeof lastItem === 'object') {
                if (lastItem.type === 'text' || lastItem.type === 'text_message') return String(lastItem.content || '').trim() || '[消息]';
                if (lastItem.type === 'sticker_message') return '[表情]';
                if (lastItem.type === 'image') return '[图片]';
                if (lastItem.type === 'voice') return '[语音]';
                if (lastItem.type === 'quote' || lastItem.type === 'quote_reply') return '[引用]';
            }
            return typeof lastItem === 'string' ? lastItem : '[消息]';
        })();
        updateSessionPreview(session.id, `${getContactDisplayName(member)}：${previewText}`, baseTs);
        registerIncomingGroupMessages(session, output.length);
        initChatList();
        renderGroupSessionsList();
        if (String(State.currentSessionId || '') === String(session.id || '')) {
            renderChatMessages();
        }
        return { replied: output.length > 0, count: output.length };
    } finally {
        if (String(State.currentSessionId || '') === String(session.id || '')) {
            hideTypingIndicator();
            clearAssistantTypingBubble();
        }
    }
}

function renderApiConfigSelect() {
    const select = document.getElementById('api-config-select');
    if (!select) return;
    select.innerHTML = '';
    State.apiConfigs.forEach(config => {
        const option = document.createElement('option');
        option.value = config.id;
        option.textContent = config.name || '未命名方案';
        if (config.id === State.currentApiId) {
            option.selected = true;
            // 同步更新输入框
            document.getElementById('api-name-input').value = config.name || '';
            document.getElementById('api-url-input').value = config.apiUrl || '';
            document.getElementById('api-key-input').value = config.apiKey || '';
            setApiProxyUIFromConfig(config);
            applyApiModelUIFromConfig(config);
            applyApiVisionUIFromConfig(config);
            applyApiStreamUIFromConfig(config);
        }
        select.appendChild(option);
    });
}

function renderSharedMainApiSelect(selectEl, selectedId) {
    if (!selectEl) return;
    const picked = String(selectedId || '').trim() || 'current';
    selectEl.innerHTML = '';
    const followOpt = document.createElement('option');
    followOpt.value = 'current';
    followOpt.textContent = '跟随当前方案';
    selectEl.appendChild(followOpt);
    (State.apiConfigs || []).forEach((cfg) => {
        if (!cfg) return;
        const opt = document.createElement('option');
        opt.value = String(cfg.id || '');
        opt.textContent = String(cfg.name || '未命名方案');
        selectEl.appendChild(opt);
    });
    selectEl.value = picked;
    if (!selectEl.value) selectEl.value = 'current';
}

function getMainApiConfigBySharedId(sharedId) {
    const id = String(sharedId || '').trim() || 'current';
    const targetId = (id === 'current') ? State.currentApiId : id;
    return (State.apiConfigs || []).find(c => String(c?.id || '') === String(targetId || ''));
}

function resolveChatApiRuntimeFromConfigLike(cfgLike, modelOverride) {
    const useProxy = !!cfgLike?.useProxy;
    const targetUrl = useProxy ? String(cfgLike?.proxyUrl || '').trim() : normalizeChatCompletionsUrl(String(cfgLike?.apiUrl || '').trim());
    const apiKey = String(cfgLike?.apiKey || '').trim();
    const modelFromCfg = getCurrentModelForConfig(cfgLike);
    const model = String(modelOverride || '').trim() || String(modelFromCfg || '').trim() || 'gpt-3.5-turbo';
    return { useProxy, targetUrl, apiKey, model };
}

function normalizeChatCompletionsUrl(rawUrl) {
    const input = (rawUrl || '').trim();
    if (!input) return '';
    try {
        const url = new URL(input);
        const path = url.pathname.replace(/\/+$/, '');
        if (/\/chat\/completions$/i.test(path)) {
            url.pathname = path;
            return url.toString();
        }
        if (/\/v1$/i.test(path)) {
            url.pathname = `${path}/chat/completions`;
            return url.toString();
        }
        url.pathname = `${path}/v1/chat/completions`;
        return url.toString();
    } catch (e) {
        return input;
    }
}

function normalizeModelsUrlFromChatUrl(rawUrl) {
    const input = (rawUrl || '').trim();
    if (!input) return '';
    try {
        const url = new URL(input);
        let path = url.pathname.replace(/\/+$/, '');
        path = path.replace(/\/v1\/chat\/completions$/i, '');
        path = path.replace(/\/chat\/completions$/i, '');
        path = path.replace(/\/v1\/embeddings$/i, '');
        path = path.replace(/\/embeddings$/i, '');
        path = path.replace(/\/v1$/i, '');
        url.pathname = `${path}/v1/models`;
        return url.toString();
    } catch (e) {
        return input;
    }
}

function normalizeEmbeddingsUrl(rawUrl) {
    const input = (rawUrl || '').trim();
    if (!input) return '';
    try {
        const url = new URL(input);
        const path = url.pathname.replace(/\/+$/, '');
        if (/\/embeddings$/i.test(path)) {
            url.pathname = path;
            return url.toString();
        }
        if (/\/chat\/completions$/i.test(path)) {
            url.pathname = path.replace(/\/chat\/completions$/i, '/embeddings');
            return url.toString();
        }
        if (/\/v1$/i.test(path)) {
            url.pathname = `${path}/embeddings`;
            return url.toString();
        }
        url.pathname = `${path}/v1/embeddings`;
        return url.toString();
    } catch (e) {
        return input;
    }
}

function getLatestSummaryText(contactId) {
    const id = String(contactId || '').trim();
    if (!id) return '';
    const mega = getLatestMegaSummary(contactId);
    const pendingMini = getPendingMiniSummaries(contactId);
    const parts = [];
    if (mega?.content) parts.push(`【长期总记忆】\n${String(mega.content).trim()}`);
    if (pendingMini.length > 0) {
        parts.push([
            '【最近阶段记事】',
            pendingMini.map((item, index) => `第 ${index + 1} 条小总结：\n${String(item.content || '').trim()}`).join('\n\n')
        ].join('\n'));
    }
    return parts.join('\n\n').trim();
}

function getSummaryVectorId(summary) {
    if (summary?.id) return String(summary.id);
    const time = summary?.time ? String(summary.time) : '';
    const content = typeof summary?.content === 'string' ? summary.content : '';
    return `${summary?.kind || 'mini'}_${time}_${hashString32(content)}`;
}

function createSummaryItemId(kind = 'mini') {
    return `${kind}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

function ensureSummaryStore(contactId) {
    const id = String(contactId || '').trim();
    if (!id) return createEmptyContactSummaryStore();
    if (!State.summaryHistories) State.summaryHistories = {};
    State.summaryHistories[id] = normalizeContactSummaryStore(State.summaryHistories[id]);
    return State.summaryHistories[id];
}

function getMiniSummaryList(contactId) {
    return ensureSummaryStore(contactId).mini;
}

function getMegaSummaryList(contactId) {
    return ensureSummaryStore(contactId).mega;
}

function getLatestMegaSummary(contactId) {
    const list = getMegaSummaryList(contactId);
    return list.length > 0 ? list[list.length - 1] : null;
}

function getPendingMiniSummaries(contactId) {
    return getMiniSummaryList(contactId).filter((item) => !String(item?.mergedMegaId || '').trim());
}

function removeSummaryVectorsByItems(contactId, items) {
    const id = String(contactId || '').trim();
    if (!id || !Array.isArray(items) || items.length === 0) return;
    const store = State.summaryVectors?.[id];
    if (!store?.items || typeof store.items !== 'object') return;
    const removedIds = new Set(items.map(getSummaryVectorId).filter(Boolean));
    if (removedIds.size === 0) return;
    Object.keys(store.items).forEach((key) => {
        const parentId = String(store.items[key]?.parentId || '');
        if (removedIds.has(parentId) || removedIds.has(key) || Array.from(removedIds).some((sid) => key.startsWith(`${sid}#`))) {
            delete store.items[key];
        }
    });
    Storage.saveSummaryVectors(State.summaryVectors);
}

function saveMiniSummaryItem(contactId, summaryItem) {
    const id = String(contactId || '').trim();
    if (!id || !summaryItem || typeof summaryItem !== 'object') return;
    const store = ensureSummaryStore(id);
    const item = normalizeSummaryItem({ ...summaryItem, kind: 'mini', id: summaryItem.id || createSummaryItemId('mini') }, 'mini');
    store.mini.push(item);
    Storage.saveSummaryHistories(State.summaryHistories);
}

function saveMegaSummaryItem(contactId, summaryItem, sourceMiniIds = []) {
    const id = String(contactId || '').trim();
    if (!id || !summaryItem || typeof summaryItem !== 'object') return null;
    const store = ensureSummaryStore(id);
    const mergedMiniItems = store.mini.filter((mini) => (Array.isArray(sourceMiniIds) ? sourceMiniIds : []).includes(mini.id));
    const item = normalizeSummaryItem({
        ...summaryItem,
        kind: 'mega',
        id: summaryItem.id || createSummaryItemId('mega'),
        sourceSummaryIds: sourceMiniIds
    }, 'mega');
    const oldMegaItems = store.mega.slice();
    const pickedIds = new Set((Array.isArray(sourceMiniIds) ? sourceMiniIds : []).map((sid) => String(sid || '').trim()).filter(Boolean));
    store.mini = store.mini.map((mini) => pickedIds.has(String(mini.id || '').trim()) ? { ...mini, mergedMegaId: item.id } : mini);
    store.mega.push(item);
    Storage.saveSummaryHistories(State.summaryHistories);
    removeSummaryVectorsByItems(id, mergedMiniItems);
    removeSummaryVectorsByItems(id, oldMegaItems);
    return item;
}

function saveManualSummaryItem(contactId, summaryItem) {
    saveMiniSummaryItem(contactId, { ...summaryItem, source: summaryItem?.source || 'manual' });
}

function saveAutoSummaryItem(contactId, summaryItem) {
    saveMiniSummaryItem(contactId, { ...summaryItem, source: summaryItem?.source || 'auto' });
}

function isArchivedForAiMessage(message) {
    if (!message) return false;
    if (message.role === 'system' && String(message.content || '').startsWith('[系统归档记忆]')) return true;
    return !!message.archivedForAi;
}

function getAiVisibleHistory(contactId) {
    const id = String(contactId || '').trim();
    if (!id) return [];
    normalizeAssistantHistoryToPerBubble(id);
    const history = Array.isArray(State.chatHistories?.[id]) ? State.chatHistories[id] : [];
    const coveredKeys = getSummaryCoveredMessageKeys(id);
    return history.filter((item) => {
        if (!item || isArchivedForAiMessage(item)) return false;
        const key = String(buildMessageSourceKey(item) || '').trim();
        return !key || !coveredKeys.has(key);
    });
}

function getSummarizableChatMessages(contactId, options = {}) {
    const id = String(contactId || '').trim();
    if (!id) return [];
    normalizeAssistantHistoryToPerBubble(id);
    const history = Array.isArray(State.chatHistories?.[id]) ? State.chatHistories[id] : [];
    const includeArchived = options.includeArchived !== false;
    const withIndexes = !!options.withIndexes;
    const withPositions = !!options.withPositions;
    const withSourceKeys = !!options.withSourceKeys;
    const result = [];
    let summaryIndex = 0;
    history.forEach((item, index) => {
        if (!item || (item.role !== 'user' && item.role !== 'assistant')) return;
        if (!includeArchived && isArchivedForAiMessage(item)) return;
        summaryIndex += 1;
        if (!withIndexes && !withPositions && !withSourceKeys) {
            result.push(item);
            return;
        }
        const next = { ...item };
        if (withIndexes) next._historyIndex = index;
        if (withPositions) next._summaryIndex = summaryIndex;
        if (withSourceKeys) next._sourceKey = buildMessageSourceKey(item);
        result.push(next);
    });
    return result;
}

function getSummaryCoveredMessageKeys(contactId, allMessages = null) {
    const id = String(contactId || '').trim();
    if (!id) return new Set();
    const messages = Array.isArray(allMessages)
        ? allMessages
        : getSummarizableChatMessages(id, { includeArchived: true, withSourceKeys: true, withPositions: true });
    const coveredKeys = new Set();

    messages.forEach((item) => {
        const key = String(item?._sourceKey || buildMessageSourceKey(item) || '').trim();
        if (!key) return;
        if (isArchivedForAiMessage(item) || String(item?.summaryMiniId || '').trim()) {
            coveredKeys.add(key);
        }
    });

    getMiniSummaryList(id).forEach((item) => {
        const storedKeys = Array.isArray(item?.sourceMessageKeys)
            ? item.sourceMessageKeys.map((key) => String(key || '').trim()).filter(Boolean)
            : [];
        if (storedKeys.length > 0) {
            storedKeys.forEach((key) => coveredKeys.add(key));
            return;
        }
        const start = Math.max(1, parseInt(item?.rangeStart ?? 0, 10) || 0);
        const end = Math.max(start, parseInt(item?.rangeEnd ?? 0, 10) || 0);
        if (!start || !end) return;
        messages.slice(start - 1, end).forEach((message) => {
            const key = String(message?._sourceKey || buildMessageSourceKey(message) || '').trim();
            if (key) coveredKeys.add(key);
        });
    });

    return coveredKeys;
}

function getSummaryMessageStats(contactId) {
    const messages = getSummarizableChatMessages(contactId, { includeArchived: true, withSourceKeys: true, withPositions: true });
    const coveredKeys = getSummaryCoveredMessageKeys(contactId, messages);
    let summarizedCount = 0;
    messages.forEach((item) => {
        const key = String(item?._sourceKey || buildMessageSourceKey(item) || '').trim();
        if (key && coveredKeys.has(key)) summarizedCount += 1;
    });
    const totalCount = messages.length;
    const safeSummarized = Math.min(totalCount, summarizedCount);
    return {
        totalCount,
        summarizedCount: safeSummarized,
        unsummarizedCount: Math.max(0, totalCount - safeSummarized),
        coveredKeys
    };
}

function getAutoSummaryCandidateMessages(contactId, options = {}) {
    const visibleMessages = getSummarizableChatMessages(contactId, {
        includeArchived: false,
        withIndexes: !!options.withIndexes,
        withPositions: !!options.withPositions,
        withSourceKeys: true
    });
    const coveredKeys = getSummaryCoveredMessageKeys(contactId);
    return visibleMessages
        .filter((item) => {
            const key = String(item?._sourceKey || buildMessageSourceKey(item) || '').trim();
            return !key || !coveredKeys.has(key);
        })
        .map((item) => {
            if (options.withSourceKeys) return item;
            const next = { ...item };
            delete next._sourceKey;
            return next;
        });
}

function getSummaryRuntimeConfig() {
    const config = State.summaryConfig || Storage.getSummaryConfig();
    const useMain = !!config?.useMainApi;
    const baseCfg = useMain
        ? getMainApiConfigBySharedId(config?.mainApiId)
        : { useProxy: false, apiUrl: config?.apiUrl || '', apiKey: config?.apiKey || '' };
    return {
        config,
        runtime: baseCfg ? resolveChatApiRuntimeFromConfigLike(baseCfg, config?.model) : null
    };
}

function buildSummaryTextBatches(messages, options = {}) {
    const list = Array.isArray(messages) ? messages : [];
    const maxChars = Math.max(1200, Math.min(24000, parseInt(options.maxChars ?? 7000, 10) || 7000));
    const maxUnits = Math.max(10, Math.min(160, parseInt(options.maxUnits ?? 70, 10) || 70));
    const target = options.target || resolveTargetEntityById(options.targetId, options.targetType);
    const isGroupTarget = isGroupSession(target);
    const userProfile = getUserProfileForContact(target);
    const groupMembers = isGroupTarget ? getGroupMemberContacts(target) : [];
    const batches = [];
    let currentLines = [];
    let currentChars = 0;
    let currentUnits = 0;
    const pushCurrent = () => {
        if (currentLines.length === 0) return;
        batches.push(currentLines.join('\n'));
        currentLines = [];
        currentChars = 0;
        currentUnits = 0;
    };
    list.forEach((m) => {
        if (!m) return;
        const timestamp = Number(m.time || 0) > 0 ? formatWxCNTime(m.time) : '';
        let speaker = m.role;
        if (m.role === 'user') {
            speaker = userProfile.nickname || '我';
        } else if (m.role === 'assistant') {
            if (isGroupTarget) {
                const sender = findGroupMemberFromList(m.senderId, groupMembers)
                    || (State.contacts || []).find((item) => String(item?.id || '') === String(m.senderId || ''));
                speaker = getContactDisplayName(sender);
            } else {
                speaker = getEntityDisplayName(target || { name: '对方' });
            }
        }
        const prefix = timestamp ? `[${timestamp}]` : '';
        const line = `${prefix}[${speaker || m.role}]: ${toPlainTextFromStoredContent(m.content)}`.trim();
        if (!line) return;
        const unitCount = Math.max(1, getStoredMessageUnitCount(m.content));
        const safeLine = line.length > maxChars ? `${line.slice(0, maxChars - 1)}…` : line;
        const nextChars = currentChars + (currentLines.length > 0 ? 1 : 0) + safeLine.length;
        if (currentLines.length > 0 && (nextChars > maxChars || currentUnits + unitCount > maxUnits)) {
            pushCurrent();
        }
        currentLines.push(safeLine);
        currentChars += (currentLines.length > 1 ? 1 : 0) + safeLine.length;
        currentUnits += unitCount;
    });
    pushCurrent();
    return batches;
}

function parseSummaryApiError(rawText, status = 0) {
    const raw = String(rawText || '').trim();
    if (!raw) return status ? `接口返回错误（HTTP ${status}）` : '接口返回错误';
    try {
        const parsed = JSON.parse(raw);
        const msg = parsed?.error?.message || parsed?.message || parsed?.detail || parsed?.msg || '';
        if (msg) return String(msg).trim();
    } catch (e) {
    }
    return raw.replace(/\s+/g, ' ').trim().slice(0, 4000) || (status ? `接口返回错误（HTTP ${status}）` : '接口返回错误');
}

function formatSummaryFailure(err, fallback = '网络或接口错误') {
    const msg = String(err?.message || '').trim();
    if (!msg || msg === 'SUMMARY_REQUEST_FAILED') return fallback;
    if (msg === 'SUMMARY_CONFIG_INCOMPLETE') return '总结API未配置完整';
    return msg.slice(0, 4000);
}

function getSummaryBasePrompt(target, kind = 'mini') {
    const config = State.summaryConfig || Storage.getSummaryConfig();
    const promptText = kind === 'mega'
        ? (config.customPromptMega || Storage.DEFAULT_SUMMARY_MEGA_PROMPT)
        : (config.customPromptMini || config.customPrompt || Storage.DEFAULT_SUMMARY_MINI_PROMPT);
    if (isGroupSession(target)) {
        const session = target;
        const userProfile = getUserProfileForContact();
        const memberList = getGroupMemberContacts(session).map((item) => getContactDisplayName(item)).join('、');
        const vars = {
            ...getScenarioPromptVars({
                name: userProfile.nickname || '我',
                persona: '群聊中的用户本人',
                style: '自然聊天'
            }, {
                char: userProfile.nickname || '我',
                user: getSessionDisplayName(session),
                group_name: getSessionDisplayName(session),
                group_members: memberList || '暂无其他成员',
                summary_kind: kind === 'mega' ? '群聊大总结' : '群聊小总结',
                summary_max_chars: (() => { const cc = resolveSummaryCharLimit(kind, config); return cc.value > 0 ? cc.value : '不限'; })(),
                mega_trigger_count: config.megaTriggerCount || 10
            })
        };
        return `${renderPromptTemplate(promptText, vars)}

【群聊总结补充规则】
- 这次总结对象是微信群「${getSessionDisplayName(session)}」，不是单聊。
- 以下聊天记录里的“我”统一指用户本人「${userProfile.nickname || '我'}」。
- 群成员名单：${memberList || '暂无其他成员'}。
- assistant 可能对应不同群成员，记录里会标明发言人名字；总结时不要把所有群成员混成一个“对方”。
- 除了用户和群成员各自状态，还要留意群氛围变化、谁更主动、谁爱调侃、谁会吃醋、谁会追问、群里的约定和反复出现的话题。`;
    }
    return renderPromptTemplate(promptText, getScenarioPromptVars(target, {
        summary_kind: kind === 'mega' ? '大总结' : '小总结',
        summary_max_chars: (() => { const cc = resolveSummaryCharLimit(kind, config); return cc.value > 0 ? cc.value : '不限'; })(),
        mega_trigger_count: config.megaTriggerCount || 10
    }));
}

function resolveSummaryCharLimit(kind, config) {
    const cfg = config || State.summaryConfig || {};
    const raw = kind === 'mega' ? cfg.megaMaxChars : cfg.miniMaxChars;
    const fallback = kind === 'mega' ? 900 : 360;
    if (raw == null) return { value: fallback, note: '尽量控制在 ' + fallback + ' 字附近' };
    const n = parseInt(raw, 10);
    const value = Number.isFinite(n) && n > 0 ? n : 0;
    return { value, note: value > 0 ? '尽量控制在 ' + value + ' 字附近' : '不限制字数，以内容完整全面为主，重要信息尽量写全，允许写得更长' };
}


