function buildTextParagraphBatches(lines, options = {}) {
    const list = Array.isArray(lines) ? lines.map((line) => String(line || '').trim()).filter(Boolean) : [];
    const maxChars = Math.max(800, Math.min(24000, parseInt(options.maxChars ?? 7000, 10) || 7000));
    const batches = [];
    let current = '';
    list.forEach((line) => {
        const piece = current ? `${current}\n\n${line}` : line;
        if (piece.length > maxChars && current) {
            batches.push(current);
            current = line;
            return;
        }
        current = piece;
    });
    if (current) batches.push(current);
    return batches;
}

async function requestSummaryContent(contactId, inputText, options = {}) {
    const { config, runtime } = getSummaryRuntimeConfig();
    if (!runtime?.targetUrl || (!runtime.useProxy && !runtime.apiKey)) {
        throw new Error('SUMMARY_CONFIG_INCOMPLETE');
    }
    const kind = options.kind === 'mega' ? 'mega' : 'mini';
    const target = options.target || resolveTargetEntityById(contactId, options.targetType);
    const basePrompt = getSummaryBasePrompt(target, kind);
    const previousMemory = String(options.previousMemory || '').trim();
    const summaryPrompt = kind === 'mega'
        ? buildMegaSummaryPromptText(basePrompt, previousMemory, inputText, { summaryCount: options.summaryCount })
        : buildMiniSummaryPromptText(basePrompt, previousMemory, inputText);
    rememberPromptTrace(contactId, kind === 'mega' ? 'summary-mega' : 'summary-mini', summaryPrompt);
    const nativeTaskToken = beginNativeAiGeneration(kind === 'mega' ? '正在整理长期总结' : '正在整理聊天总结');

    try {
        const headers = { 'Content-Type': 'application/json' };
        if (!runtime.useProxy) headers.Authorization = `Bearer ${runtime.apiKey}`;
        const response = await fetch(runtime.targetUrl, {
            method: 'POST',
            headers,
            body: JSON.stringify({
                model: runtime.model || 'gpt-3.5-turbo',
                messages: [{ role: 'user', content: summaryPrompt }],
                stream: false
            })
        });
        if (!response.ok) {
            const raw = await response.text().catch(() => '');
            throw new Error(parseSummaryApiError(raw, response.status));
        }
        const contentType = String(response.headers.get('content-type') || '').toLowerCase();
        if (contentType.includes('text/event-stream')) {
            return String(await readStreamedReplyContent(response)).trim();
        }
        const raw = await response.text().catch(() => '');
        if (!raw.trim()) return '';
        try {
            const data = JSON.parse(raw);
            return String(data?.choices?.[0]?.message?.content || data?.choices?.[0]?.text || data?.message || '').trim();
        } catch (e) {
            return raw.trim();
        }
    } finally {
        endNativeAiGeneration(nativeTaskToken);
    }
}

async function requestSummaryForMessages(contactId, messages, options = {}) {
    const target = options.target || resolveTargetEntityById(contactId, options.targetType);
    const targetType = options.targetType || (isGroupSession(target) ? 'group' : 'contact');
    const batches = buildSummaryTextBatches(messages, { ...options, target, targetId: contactId, targetType });
    if (batches.length === 0) return '';
    let rollingMemory = String(options.seedMemory || '').trim();
    for (const batchText of batches) {
        rollingMemory = await requestSummaryContent(contactId, batchText, {
            kind: options.kind || 'mini',
            previousMemory: rollingMemory,
            summaryCount: options.summaryCount,
            target,
            targetType
        });
    }
    return String(rollingMemory || '').trim();
}

async function requestSummaryForTextBatches(contactId, batches, options = {}) {
    const list = Array.isArray(batches) ? batches.map((item) => String(item || '').trim()).filter(Boolean) : [];
    if (list.length === 0) return '';
    const target = options.target || resolveTargetEntityById(contactId, options.targetType);
    const targetType = options.targetType || (isGroupSession(target) ? 'group' : 'contact');
    let rollingMemory = String(options.seedMemory || '').trim();
    for (const batchText of list) {
        rollingMemory = await requestSummaryContent(contactId, batchText, {
            kind: options.kind || 'mega',
            previousMemory: rollingMemory,
            summaryCount: options.summaryCount,
            target,
            targetType
        });
    }
    return String(rollingMemory || '').trim();
}

async function fetchEmbeddingsBatch(texts, overrideConfig = null) {
    const items = Array.isArray(texts) ? texts.map(t => String(t || '').trim()) : [];
    const inputs = items.filter(Boolean);
    if (inputs.length === 0) return [];

    const cfg = overrideConfig || State.vectorConfig || Storage.getVectorConfig();
    const apiUrl = normalizeEmbeddingsUrl(String(cfg?.apiUrl || '').trim());
    const model = String(cfg?.model || '').trim() || 'text-embedding-3-small';
    if (!apiUrl) throw new Error('向量化API未配置');

    const currentApiConfig = State.apiConfigs.find(c => c.id === State.currentApiId);
    const fallbackKey = String(currentApiConfig?.apiKey || '').trim();
    const apiKey = String(cfg?.apiKey || '').trim() || fallbackKey;

    const headers = { 'Content-Type': 'application/json' };
    if (apiKey) headers.Authorization = `Bearer ${apiKey}`;

    const requestEmbeddings = async (inputPayload) => {
        const response = await fetch(apiUrl, {
            method: 'POST',
            headers,
            body: JSON.stringify({
                model,
                input: inputPayload
            })
        });
        if (!response.ok) {
            let errMsg = `HTTP ${response.status}`;
            try {
                const errData = await response.json();
                errMsg = errData?.error?.message || errData?.message || errData?.error || errMsg;
            } catch (e) {
                try {
                    const errText = await response.text();
                    if (errText) errMsg = errText;
                } catch (e2) {
                }
            }
            throw new Error(String(errMsg || '向量化接口返回错误').trim());
        }
        const data = await response.json();
        const arr = Array.isArray(data?.data) ? data.data : [];
        return arr.map(x => x?.embedding).filter(e => Array.isArray(e));
    };

    try {
        const embeddings = await requestEmbeddings(inputs);
        if (embeddings.length === inputs.length) return embeddings;
        if (inputs.length === 1 && embeddings.length === 1) return embeddings;
        throw new Error('向量化结果数量不匹配');
    } catch (batchError) {
        if (inputs.length === 1) throw batchError;
        const singleEmbeddings = [];
        for (const input of inputs) {
            const one = await requestEmbeddings(input);
            if (!Array.isArray(one) || one.length !== 1) {
                throw batchError;
            }
            singleEmbeddings.push(one[0]);
        }
        return singleEmbeddings;
    }
}

function getDraftVectorConfigFromForm() {
    const currentApiConfig = State.apiConfigs.find(c => c.id === State.currentApiId);
    const fallbackKey = String(currentApiConfig?.apiKey || '').trim();
    return {
        apiUrl: normalizeEmbeddingsUrl(String(document.getElementById('vector-api-url-input')?.value || '').trim()),
        apiKey: String(document.getElementById('vector-api-key-input')?.value || '').trim() || fallbackKey,
        model: String(document.getElementById('vector-model-input')?.value || '').trim() || 'text-embedding-3-small'
    };
}

function formatVectorError(err) {
    const msg = String(err?.message || err || '未知错误').trim();
    if (/Failed to fetch|NetworkError/i.test(msg)) {
        return '网络请求失败，可能是跨域/CORS，或接口地址不可达';
    }
    if (/model does not exist/i.test(msg)) {
        return '模型不存在，当前填写的多半不是向量模型。硅基流动建议改用 BAAI/bge-m3、Pro/BAAI/bge-m3、BAAI/bge-large-zh-v1.5 或 netease-youdao/bce-embedding-base_v1';
    }
    return msg || '未知错误';
}

function filterLikelyEmbeddingModels(models) {
    const list = Array.isArray(models) ? models.map((m) => String(m || '').trim()).filter(Boolean) : [];
    const scored = list.map((name) => {
        const lower = name.toLowerCase();
        let score = 0;
        if (/embedding/.test(lower)) score += 6;
        if (/bge/.test(lower)) score += 5;
        if (/bce/.test(lower)) score += 5;
        if (/(^|\/)e5/.test(lower) || /gte/.test(lower)) score += 4;
        if (/m3/.test(lower)) score += 2;
        if (/rerank/.test(lower)) score -= 6;
        if (/(instruct|chat|reason|r1|v3|qwen|glm|kimi|claude|gpt)/.test(lower) && !/(bge|bce|embedding|e5|gte)/.test(lower)) score -= 5;
        return { name, score };
    });
    const preferred = scored.filter((item) => item.score > 0).sort((a, b) => b.score - a.score || a.name.localeCompare(b.name)).map((item) => item.name);
    return preferred.length > 0 ? preferred : list;
}

async function testVectorApiConfig() {
    const cfg = getDraftVectorConfigFromForm();
    if (!cfg.apiUrl) {
        showToast('请先填写向量化 API URL');
        return;
    }
    if (!cfg.model) {
        showToast('请先填写向量化模型');
        return;
    }
    try {
        showLoading('测试向量接口中...');
        const embeddings = await fetchEmbeddingsBatch(['这是一条向量测试文本。'], cfg);
        const first = Array.isArray(embeddings) ? embeddings[0] : null;
        const dim = Array.isArray(first) ? first.length : 0;
        hideLoading();
        await WeChatUI.showAlert('向量测试成功', `接口可用，已成功返回 ${dim || '?'} 维向量。`);
    } catch (err) {
        hideLoading();
        await WeChatUI.showAlert('向量测试失败', formatVectorError(err));
    }
}

async function vectorizeSummariesForContact(contact) {
    if (!contact?.id) return;
    const latestMega = getLatestMegaSummary(contact.id);
    const memories = [...(latestMega ? [latestMega] : []), ...getPendingMiniSummaries(contact.id)];

    if (!State.summaryVectors) State.summaryVectors = Storage.getSummaryVectors();
    const store = State.summaryVectors[contact.id] && typeof State.summaryVectors[contact.id] === 'object'
        ? State.summaryVectors[contact.id]
        : { version: 1, model: '', apiUrl: '', items: {} };
    if (!store.items || typeof store.items !== 'object') store.items = {};

    const allowedRootIds = new Set(memories.map((item) => String(getSummaryVectorId(item) || '').trim()).filter(Boolean));
    Object.keys(store.items).forEach((key) => {
        const rootId = String(key || '').split('#')[0];
        if (!allowedRootIds.has(rootId)) delete store.items[key];
    });
    if (memories.length === 0) {
        State.summaryVectors[contact.id] = store;
        Storage.saveSummaryVectors(State.summaryVectors);
        showToast('暂无可向量化的总结');
        return;
    }

    const splitSummaryToChunks = (text, maxChunkChars = 600, maxChunks = 8) => {
        const s = String(text || '').replace(/\r\n/g, '\n').trim();
        if (!s) return [];
        const paragraphs = s.split(/\n{2,}/).map(p => p.trim()).filter(Boolean);
        const chunks = [];
        let cur = '';
        const pushCur = () => {
            const t = cur.trim();
            if (t) chunks.push(t);
            cur = '';
        };
        const pushText = (p) => {
            const t = String(p || '').trim();
            if (!t) return;
            if (t.length <= maxChunkChars) {
                if (!cur) {
                    cur = t;
                    return;
                }
                if ((cur.length + 2 + t.length) <= maxChunkChars) {
                    cur = `${cur}\n${t}`;
                    return;
                }
                pushCur();
                cur = t;
                return;
            }
            for (let i = 0; i < t.length; i += maxChunkChars) {
                const part = t.slice(i, i + maxChunkChars).trim();
                if (!part) continue;
                if (cur) pushCur();
                chunks.push(part);
            }
        };
        paragraphs.forEach(pushText);
        pushCur();
        if (chunks.length <= maxChunks) return chunks;
        const head = chunks.slice(0, maxChunks - 1);
        const tail = chunks.slice(maxChunks - 1).join('\n');
        return [...head, tail].filter(Boolean);
    };

    const pending = [];
    for (const m of memories) {
        const content = String(m?.content || '').trim();
        if (!content) continue;
        const summaryId = getSummaryVectorId(m);
        if (!summaryId) continue;
        const chunks = splitSummaryToChunks(content);
        chunks.forEach((chunkText, idx) => {
            const id = `${summaryId}#${idx}`;
            if (store.items[id]) return;
            pending.push({
                id,
                parentId: summaryId,
                time: m.time || 0,
                messageCount: m.messageCount || 0,
                content: chunkText
            });
        });
    }

    if (pending.length === 0) {
        showToast('已全部向量化');
        return;
    }

    const cfg = State.vectorConfig || Storage.getVectorConfig();
    store.model = String(cfg?.model || '').trim() || store.model || '';
    store.apiUrl = String(cfg?.apiUrl || '').trim() || store.apiUrl || '';

    let done = 0;
    try {
        showLoading(`向量化中... (0/${pending.length})`);
        const batchSize = 8;
        for (let i = 0; i < pending.length; i += batchSize) {
            const batch = pending.slice(i, i + batchSize);
            const embeddings = await fetchEmbeddingsBatch(batch.map(x => x.content));
            if (embeddings.length !== batch.length) {
                throw new Error('向量化结果数量不匹配');
            }
            for (let j = 0; j < batch.length; j++) {
                const item = batch[j];
                store.items[item.id] = {
                    parentId: item.parentId,
                    time: item.time,
                    messageCount: item.messageCount,
                    text: item.content,
                    embedding: embeddings[j]
                };
            }
            done += batch.length;
            showLoading(`向量化中... (${done}/${pending.length})`);
        }
        State.summaryVectors[contact.id] = store;
        Storage.saveSummaryVectors(State.summaryVectors);
        showToast(`向量化完成：${done} 条`);
    } finally {
        hideLoading();
    }
}

function openTargetMemoryView(target) {
    if (!target?.id) return;
    setPageTarget('memory-view-page', target);
    updateMemoryViewTitle(target);
    showPage('memory-view-page');
    loadMemoryView(target);
}

function openTargetPromptView(target, category = 'chat', renderPromptTraceHistory) {
    if (!target?.id || typeof renderPromptTraceHistory !== 'function') return;
    setPageTarget('prompt-view-page', target);
    updatePromptViewTitle(target);
    showPage('prompt-view-page');
    const nextCategory = String(category || 'chat').trim() || 'chat';
    document.querySelectorAll('#prompt-view-category-tabs .prompt-history-tab').forEach((btn) => {
        btn.classList.toggle('active', btn.dataset.historyCategory === nextCategory);
    });
    renderPromptTraceHistory(String(target.id || ''), nextCategory);
}

function cosineSimilarity(a, b) {
    if (!Array.isArray(a) || !Array.isArray(b) || a.length === 0 || a.length !== b.length) return 0;
    let dot = 0;
    let na = 0;
    let nb = 0;
    for (let i = 0; i < a.length; i++) {
        const x = Number(a[i]) || 0;
        const y = Number(b[i]) || 0;
        dot += x * y;
        na += x * x;
        nb += y * y;
    }
    const denom = Math.sqrt(na) * Math.sqrt(nb);
    if (!denom) return 0;
    return dot / denom;
}

async function recallSummaryChunks(contact, queryText, topK = 2) {
    const contactId = contact?.id;
    if (!contactId) return '';
    const query = String(queryText || '').trim();
    if (!query) return getLatestSummaryText(contactId);

    const store = State.summaryVectors?.[contactId];
    const items = store?.items && typeof store.items === 'object' ? Object.entries(store.items) : [];
    if (items.length === 0) return getLatestSummaryText(contactId);

    let qEmbedding = null;
    try {
        const e = await fetchEmbeddingsBatch([query]);
        qEmbedding = Array.isArray(e?.[0]) ? e[0] : null;
    } catch (e) {
        return getLatestSummaryText(contactId);
    }
    if (!qEmbedding) return getLatestSummaryText(contactId);

    const scored = [];
    for (const [id, v] of items) {
        const emb = v?.embedding;
        const text = typeof v?.text === 'string' ? v.text.trim() : '';
        if (!text || !Array.isArray(emb) || emb.length !== qEmbedding.length) continue;
        scored.push({
            id,
            parentId: String(v?.parentId || '').trim() || String(id || '').split('#')[0],
            score: cosineSimilarity(qEmbedding, emb),
            text
        });
    }
    if (scored.length === 0) return getLatestSummaryText(contactId);
    scored.sort((x, y) => y.score - x.score);

    const chosen = [];
    const used = new Set();
    const usedParents = new Set();
    for (const s of scored) {
        if (chosen.length >= topK) break;
        if (used.has(s.text)) continue;
        if (s.parentId && usedParents.has(s.parentId)) continue;
        if (s.score < 0.2) continue;
        used.add(s.text);
        if (s.parentId) usedParents.add(s.parentId);
        chosen.push(s.text);
    }
    if (chosen.length === 0) return getLatestSummaryText(contactId);
    return chosen.join('\n\n');
}

function toPlainTextFromStoredContent(rawContent, options = {}) {
    if (rawContent == null) return '';
    const text = String(rawContent);
    if (!text) return '';
    const first = text[0];
    if (first === '{' || first === '[') {
        try {
            const parsed = JSON.parse(text);
            if (Array.isArray(parsed)) {
                const parts = parsed.map((it) => {
                    if (!it || typeof it !== 'object') return '';
                    if (typeof it.content === 'string') return it.content;
                    if (typeof it.description === 'string') return it.description;
                    if (typeof it.quote === 'string' && typeof it.content === 'string') return `「${it.quote}」\n${it.content}`;
                    if (typeof it.sticker === 'string') return it.sticker ? `[表情] ${it.sticker}` : '[表情]';
                    return '';
                }).filter(Boolean);
                if (parts.length > 0) return parts.join('\n');
            }
            if (parsed && typeof parsed === 'object') {
                if (parsed.type === 'scene_note') {
                    return renderSceneNoteForContext(parsed, {
                        fallbackActor: 'assistant',
                        sceneNoteMode: options.sceneNoteMode
                    });
                }
                const t = String(parsed.type || '');
                if (t === 'text' || t === 'text_message') {
                    if (isStoredCallRecordPayload(parsed)) {
                        return formatCallRecordForContext(parsed, options);
                    }
                    return String(parsed.content || '');
                }
                if (t === 'quote' || t === 'quote_reply') {
                    const q = String(parsed.quote || '');
                    const c = String(parsed.content || '');
                    return q ? `「${q}」\n${c}` : c;
                }
                if (t === 'sticker_message') {
                    const v = String(parsed.sticker || '');
                    return v ? `[表情] ${v}` : '[表情]';
                }
                if (t === 'image') {
                    const desc = String(parsed.description || '').trim();
                    return desc ? `[图片] ${desc}` : '[图片]';
                }
                if (t === 'voice') {
                    const v = String(parsed.text || parsed.transcription || parsed.content || '').trim();
                    return v ? `[语音] ${v}` : '[语音]';
                }
                if (t === 'action') {
                    const cmd = String(parsed.command || '').trim();
                    return cmd ? `[动作] ${cmd}` : '[动作]';
                }
                if (t === 'event') {
                    const aiText = String(parsed.aiText || '').trim();
                    if (aiText) return aiText;
                    const display = String(parsed.display || '').trim();
                    return display ? `[聊天事件] ${display}` : '[聊天事件]';
                }
            }
        } catch (e) {
        }
    }
    return text;
}

function sanitizeAiTextEnding(raw) {
    let text = String(raw ?? '');
    if (!text) return '';
    text = text.replace(/\r\n/g, '\n').trim();
    text = text.replace(/[\s\u200B\u200C\u200D\uFEFF]+$/g, '');
    if (!text) return '';
    while (/[。｡．]$/.test(text)) {
        text = text.slice(0, -1);
        text = text.replace(/[\s\u200B\u200C\u200D\uFEFF]+$/g, '');
    }
    if (text.endsWith('.') && !text.endsWith('...')) {
        const prev = text.slice(-2, -1);
        if (!/[0-9]/.test(prev)) {
            text = text.slice(0, -1);
            text = text.replace(/[\s\u200B\u200C\u200D\uFEFF]+$/g, '');
        }
    }
    return text;
}

// 把模型偶发输出的“裸 JSON 对象”还原成可读文字（模型有时忘了包成数组，导致 JSON.parse 失败）
function extractBalancedJsonObjects(text) {
    const objs = [];
    let depth = 0, start = -1, inStr = false, esc = false;
    const s = String(text || '');
    for (let i = 0; i < s.length; i++) {
        const c = s[i];
        if (inStr) {
            if (esc) esc = false;
            else if (c === '\\') esc = true;
            else if (c === '"') inStr = false;
            continue;
        }
        if (c === '"') inStr = true;
        else if (c === '{') { if (depth === 0) start = i; depth++; }
        else if (c === '}') {
            if (depth > 0) {
                depth--;
                if (depth === 0 && start >= 0) { objs.push({ start, end: i + 1, raw: s.slice(start, i + 1) }); start = -1; }
            }
        }
    }
    return objs;
}

function deJsonAiReplyText(text) {
    const raw = String(text ?? '');
    if (raw.indexOf('"type"') < 0) return raw;
    const objs = extractBalancedJsonObjects(raw);
    if (objs.length === 0) return raw;
    const out = [];
    let last = 0;
    for (const obj of objs) {
        out.push(raw.slice(last, obj.start));
        let parsed = null;
        try { parsed = JSON.parse(obj.raw); } catch (e) { parsed = null; }
        if (parsed && typeof parsed === 'object') {
            const type = String(parsed.type || '').toLowerCase();
            let content = '';
            if (typeof parsed.content === 'string') content = parsed.content;
            else if (typeof parsed.description === 'string') content = parsed.description;
            else if (typeof parsed.name === 'string') content = parsed.name;
            if (type === 'voice') content = content ? `[语音] ${content}` : '[语音]';
            else if (type === 'image') content = content ? `[图片] ${content}` : '[图片]';
            if (content) out.push(content);
        } else {
            // 对象格式不合法（如 duration 被写成 ? 占位），尽力抽取 content/description
            const typeM = obj.raw.match(/"type"\s*:\s*"([^"]+)"/);
            const type = typeM ? String(typeM[1]).toLowerCase() : '';
            const contentM = obj.raw.match(/"content"\s*:\s*"((?:\\.|[^"\\])*)"/)
                || obj.raw.match(/"description"\s*:\s*"((?:\\.|[^"\\])*)"/)
                || obj.raw.match(/"name"\s*:\s*"((?:\\.|[^"\\])*)"/);
            let content = '';
            if (contentM) { try { content = JSON.parse('"' + contentM[1] + '"'); } catch (e) { content = contentM[1]; } }
            if (type === 'voice') content = content ? `[语音] ${content}` : '[语音]';
            else if (type === 'image') content = content ? `[图片] ${content}` : '[图片]';
            out.push(content || obj.raw);
        }
        last = obj.end;
    }
    out.push(raw.slice(last));
    return out.join('');
}

function splitAiTextToBubbles(raw, options = {}) {
    const maxLen = Math.max(8, Math.min(48, Number(options.maxLen || 22) || 22));
    const maxItems = Math.max(1, Math.min(20, Number(options.maxItems || 8) || 8));
    const text = sanitizeAiTextEnding(deJsonAiReplyText(String(raw ?? '')).replace(/\r\n/g, '\n'));
    if (!text) return [];
    const parts = [];
    const paras = text.split(/\n+/).map(s => s.trim()).filter(Boolean);
    const sentenceRegex = /[^。！？?!…]+(?:[。！？?!…]+)?|[。！？?!…]+/g;
    for (const para of paras) {
        const matches = para.match(sentenceRegex) || [];
        for (const m of matches) {
            const s = String(m || '').trim();
            if (s) parts.push(s);
        }
    }
    const merged = [];
    for (const s of parts) {
        const last = merged[merged.length - 1];
        if (!last) {
            merged.push(s);
            continue;
        }
        if ((last.length + s.length) <= maxLen && !/[。！？?!…]$/.test(last)) {
            merged[merged.length - 1] = `${last}${s}`;
            continue;
        }
        merged.push(s);
    }
    const out = [];
    for (const s of merged) {
        const t = sanitizeAiTextEnding(s);
        if (!t) continue;
        out.push(t);
        if (out.length >= maxItems) break;
    }
    return out;
}

function shouldKeepStructuredTextBubble(raw) {
    const text = String(raw ?? '').replace(/\r\n/g, '\n').trim();
    if (!text) return false;
    return text.startsWith('[微信红包]\n')
        || text.startsWith('[微信转账]\n')
        || text.startsWith('[位置卡片]\n')
        || text.startsWith('[通话记录]\n')
        || /^\[语音 [^\]\n]+\]\n/.test(text);
}

function expandAiDisplayItems(items, options = {}) {
    const out = [];
    for (const it of (Array.isArray(items) ? items : [])) {
        if (!it || typeof it !== 'object') continue;
        const t = String(it.type || '').trim();
        if (t === 'text' || t === 'text_message') {
            const raw = typeof it.content === 'string' ? it.content : '';
            if (shouldKeepStructuredTextBubble(raw)) {
                out.push({ ...it, type: 'text', content: raw });
                if (out.length >= (options.maxItemsTotal || 20)) break;
                continue;
            }
            const chunks = splitAiTextToBubbles(raw, options);
            if (chunks.length === 0) continue;
            for (const c of chunks) {
                const next = { ...it, type: 'text', content: c };
                out.push(next);
                if (out.length >= (options.maxItemsTotal || 20)) break;
            }
            continue;
        }
        out.push(it);
        if (out.length >= (options.maxItemsTotal || 20)) break;
    }
    return out;
}

function isStoredCallRecordPayload(parsed) {
    if (!parsed || typeof parsed !== 'object') return false;
    const t = String(parsed.type || '');
    if (t !== 'text' && t !== 'text_message') return false;
    const text = String(parsed.content || '');
    return text.startsWith('[通话记录]');
}

function getStoredCallRecordType(parsed) {
    const raw = String(parsed?.callMeta?.type || '').trim().toLowerCase();
    if (raw === 'video' || raw === 'voice') return raw;
    const content = String(parsed?.content || '');
    if (/视频/.test(content)) return 'video';
    if (/语音/.test(content)) return 'voice';
    return 'call';
}

function getStoredCallRecordDirection(parsed, options = {}) {
    const raw = String(parsed?.callMeta?.direction || '').trim().toLowerCase();
    if (raw === 'incoming' || raw === 'outgoing') return raw;
    const role = String(options.messageRole || '').trim().toLowerCase();
    if (role === 'assistant') return 'incoming';
    if (role === 'user') return 'outgoing';
    return '';
}

function getStoredCallRecordTypeLabel(parsed) {
    const t = getStoredCallRecordType(parsed);
    if (t === 'video') return '视频通话';
    if (t === 'voice') return '语音通话';
    return '通话';
}

function getCallPreviewLabel(callType) {
    const t = String(callType || '').trim().toLowerCase();
    if (t === 'video') return '[视频通话]';
    if (t === 'voice') return '[语音通话]';
    return '[通话记录]';
}

function getStoredCallTranscriptItems(parsed) {
    const transcript = Array.isArray(parsed?.callTranscript) ? parsed.callTranscript : [];
    return transcript
        .map((item) => ({
            role: item?.role === 'assistant' ? 'assistant' : 'user',
            content: String(item?.content || '').trim(),
            speakerId: String(item?.speakerId || '').trim(),
            speakerName: String(item?.speakerName || '').trim()
        }))
        .filter((item) => item.content);
}

function expandHistoryEntriesToContextUnits(history) {
    const source = Array.isArray(history) ? history : [];
    const units = [];
    source.forEach((message) => {
        if (!message || isArchivedForAiMessage(message)) return;
        let parsed = null;
        try {
            parsed = JSON.parse(String(message.content || ''));
        } catch (e) {
        }
        if (!isStoredCallRecordPayload(parsed)) {
            units.push(message);
            return;
        }
        const transcript = getStoredCallTranscriptItems(parsed);
        if (transcript.length === 0) {
            units.push(message);
            return;
        }
        const baseTime = Number(message.time || message.timestamp || message.createdAt || 0) || 0;
        const callTypeLabel = getStoredCallRecordTypeLabel(parsed);
        transcript.forEach((item, index) => {
            const isAssistant = item.role === 'assistant';
            const speakerId = isAssistant
                ? (item.speakerId || String(message.senderId || parsed?.callMeta?.callerId || '').trim())
                : '';
            units.push({
                ...message,
                role: item.role,
                content: `[${callTypeLabel}中] ${item.content}`,
                senderId: speakerId,
                speakerName: isAssistant ? item.speakerName : '',
                time: baseTime > 0 ? baseTime + (index / 1000) : baseTime,
                contextSource: 'call_transcript',
                callType: getStoredCallRecordType(parsed),
                callDirection: getStoredCallRecordDirection(parsed, { messageRole: message.role })
            });
        });
    });
    return units;
}

function takeLatestContextUnits(history, limit) {
    const maxUnits = Math.max(0, parseInt(limit, 10) || 0);
    if (maxUnits <= 0) return [];
    return expandHistoryEntriesToContextUnits(history).slice(-maxUnits);
}

function formatCallRecordForContext(parsed, options = {}) {
    if (!isStoredCallRecordPayload(parsed)) return String(parsed?.content || '');
    const typeLabel = getStoredCallRecordTypeLabel(parsed);
    const summary = String(parsed.content || '').replace(/^\[通话记录\]\n?/, '').trim();
    const transcript = getStoredCallTranscriptItems(parsed);
    const userLabel = String(options.userLabel || '我');
    const assistantLabel = String(options.assistantLabel || '对方');
    const direction = getStoredCallRecordDirection(parsed, options);
    const lines = [`[${typeLabel}记录]`];
    if (direction === 'incoming') {
        lines.push(`${assistantLabel}发起了一次${typeLabel}`);
    } else if (direction === 'outgoing') {
        lines.push(`${userLabel}发起了一次${typeLabel}`);
    }
    if (summary) {
        const summaryLines = summary.split('\n').map((item) => String(item || '').trim()).filter(Boolean);
        if (summaryLines.length > 0) {
            lines.push(`结果：${summaryLines[0]}`);
            summaryLines.slice(1).forEach((item) => lines.push(item));
        }
    }
    if (transcript.length > 0) {
        lines.push(`[${typeLabel}过程]`);
        transcript.forEach((item) => {
            const speaker = item.role === 'assistant' ? assistantLabel : userLabel;
            lines.push(`${speaker}: ${item.content}`);
        });
    }
    return lines.join('\n');
}

function getStoredMessageUnitCount(rawContent) {
    if (rawContent == null) return 0;
    try {
        const parsed = JSON.parse(String(rawContent));
        if (isStoredCallRecordPayload(parsed)) {
            const transcriptCount = getStoredCallTranscriptItems(parsed).length;
            return Math.max(1, transcriptCount);
        }
    } catch (e) {
    }
    return 1;
}

function getHistoryUnitCount(history) {
    const list = Array.isArray(history) ? history : [];
    return list.reduce((sum, item) => {
        if (!item) return sum;
        if (isArchivedForAiMessage(item)) return sum;
        return sum + getStoredMessageUnitCount(item.content);
    }, 0);
}

function getUserProfileForContact(contact) {
    const base = State.user || Storage.DEFAULT_USER || { nickname: '用户', wxid: '', avatar: '', persona: '', gender: '' };
    const override = contact && typeof contact === 'object' ? (contact.userOverride || {}) : {};
    const nickname = String(override.nickname || '').trim() || String(base.nickname || '').trim() || '用户';
    const wxid = String(override.wxid || '').trim() || String(base.wxid || '').trim() || '';
    const overrideAvatar = cloneStoredImageValue(override.avatar);
    const baseAvatar = cloneStoredImageValue(base.avatar);
    const avatar = hasStoredImageValue(overrideAvatar) ? overrideAvatar : (hasStoredImageValue(baseAvatar) ? baseAvatar : '');
    const userPersona = String(override.userPersona || '').trim() || String(base.persona || '').trim() || '';
    const gender = String(override.gender || '').trim() || String(base.gender || '').trim() || 'male';
    return { nickname, wxid, avatar, userPersona, gender };
}

function hashString32(input) {
    const str = String(input ?? '');
    let hash = 5381;
    for (let i = 0; i < str.length; i++) {
        hash = ((hash << 5) + hash) ^ str.charCodeAt(i);
        hash |= 0;
    }
    return (hash >>> 0).toString(16);
}

function getModelsCacheKey(configLike) {
    const useProxy = !!configLike?.useProxy;
    const proxyUrl = String(configLike?.proxyUrl || '').trim();
    const apiUrl = String(configLike?.apiUrl || '').trim();
    const apiKey = String(configLike?.apiKey || '');
    return `${useProxy ? '1' : '0'}|${useProxy ? proxyUrl : apiUrl}|${hashString32(apiKey)}`;
}

function setApiProxyUIFromConfig(config) {
    const toggle = document.getElementById('api-proxy-toggle');
    const group = document.getElementById('api-proxy-url-group');
    const input = document.getElementById('api-proxy-url-input');
    const enabled = !!config?.useProxy;
    toggle?.classList.toggle('active', enabled);
    if (group) group.style.display = enabled ? '' : 'none';
    if (input) input.value = config?.proxyUrl || '';
}

function updateApiModelSelectedHint(config) {
    const hint = document.getElementById('api-model-selected-hint');
    if (!hint) return;
    const list = Array.isArray(config?.models) ? config.models : [];
    const count = list.length;
    if (count === 0) {
        hint.textContent = '已选 0 个模型';
        return;
    }
    const preview = list.slice(0, 3).join('、');
    hint.textContent = count <= 3 ? `已选 ${count} 个模型：${preview}` : `已选 ${count} 个模型：${preview} 等`;
}

function renderSelectedModelsList(config) {
    const container = document.getElementById('api-models-list');
    if (!container) return;
    const list = Array.isArray(config?.models) ? config.models : [];
    if (list.length === 0) {
        container.style.display = 'none';
        container.innerHTML = '';
        return;
    }

    const current = (config?.model || '').trim();
    container.style.display = '';
    container.innerHTML = list.map((m) => {
        const active = (m === current) ? 'active' : '';
        return `
            <div class="api-model-chip ${active}" data-model="${encodeURIComponent(m)}">
                <span class="api-model-chip-name">${escapeHtml(m)}</span>
                <span class="api-model-chip-x" data-action="remove">×</span>
            </div>
        `;
    }).join('');

    container.onclick = async (e) => {
        const chip = e.target.closest('.api-model-chip');
        if (!chip) return;
        const model = chip.dataset.model ? decodeURIComponent(chip.dataset.model) : '';
        if (!model) return;

        const actionEl = e.target.closest('[data-action="remove"]');
        if (actionEl) {
            const ok = await WeChatUI.showConfirm('移除模型', `确定移除「${model}」吗？`, '移除', '取消', true);
            if (!ok) return;
            const next = list.filter(x => x !== model);
            config.models = next;
            if (config.model === model) config.model = next[0] || '';
            applyApiModelUIFromConfig(config);
            Storage.saveApiConfigs(State.apiConfigs);
            return;
        }

        config.model = model;
        applyApiModelUIFromConfig(config);
        Storage.saveApiConfigs(State.apiConfigs);
        showToast(`已切换：${model}`);
    };
}

function applyApiVisionUIFromConfig(config) {
    const toggle = document.getElementById('api-vision-toggle');
    toggle?.classList.toggle('active', !!config?.visionEnabled);
}

function applyApiStreamUIFromConfig(config) {
    const toggle = document.getElementById('api-stream-toggle');
    if (!toggle) return;
    const enabled = config?.streamEnabled !== false;
    toggle.classList.toggle('active', enabled);
}

function updateChatModelSwitchButton() {
    const btn = document.getElementById('chat-model-switch-btn');
    if (!btn) return;
    const cfg = State.apiConfigs.find(c => c.id === State.currentApiId);
    if (!cfg) {
        btn.title = '未选择API方案';
        return;
    }
    const apiName = (cfg.name || '未命名方案').trim() || '未命名方案';
    const pickedModel = (cfg.model || '').trim() || (Array.isArray(cfg.models) ? (cfg.models[0] || '').trim() : '');
    const modelText = pickedModel || '未选择模型';
    btn.title = `当前方案：${apiName}\n当前模型：${modelText}`;
}

function closeChatModelDropdown() {
    const dropdown = document.getElementById('chat-model-dropdown');
    if (!dropdown) return;
    dropdown.style.display = 'none';
}

function isChatModelDropdownOpen() {
    const dropdown = document.getElementById('chat-model-dropdown');
    return !!dropdown && dropdown.style.display !== 'none';
}

function getCurrentModelForConfig(config) {
    return (config?.model || '').trim()
        || (Array.isArray(config?.models) ? (config.models[0] || '').trim() : '')
        || 'gpt-3.5-turbo';
}

function getSelectedModelForConfig(config) {
    return (config?.model || '').trim() || (Array.isArray(config?.models) ? (config.models[0] || '').trim() : '');
}

function getModelsForConfig(config) {
    const raw = Array.isArray(config?.models) ? config.models : [];
    const list = raw.map(x => (typeof x === 'string' ? x.trim() : '')).filter(Boolean);
    const picked = (config?.model || '').trim();
    if (picked && !list.includes(picked)) list.unshift(picked);
    return Array.from(new Set(list));
}

function renderChatModelDropdown() {
    const titleEl = document.getElementById('chat-model-dropdown-title');
    const listEl = document.getElementById('chat-model-dropdown-list');
    if (!listEl) return;

    const configs = Array.isArray(State.apiConfigs) ? State.apiConfigs : [];
    if (titleEl) titleEl.textContent = `API方案 / 模型（${configs.length}）`;

    const headerEl = titleEl?.closest?.('.chat-model-dropdown-header') || titleEl?.parentElement;
    if (headerEl) {
        let badge = document.getElementById('chat-model-latency-badge');
        if (!badge) {
            badge = document.createElement('span');
            badge.id = 'chat-model-latency-badge';
            badge.className = 'chat-model-latency-badge';
            headerEl.appendChild(badge);
        }
        const cidForBadge = String(State.currentContactId || '');
        const info = cidForBadge ? State.aiLastTimings?.[cidForBadge] : null;
        const ms = Number(info?.firstMs ?? NaN);
        const label = Number.isFinite(ms) ? `${(ms / 1000).toFixed(ms >= 10000 ? 0 : 1)}s` : '--';
        badge.textContent = `首条 ${label}`;
    }

    const openApiId = renderChatModelDropdown._openApiId || State.currentApiId;
    const chevronSvg = `
        <svg class="chat-model-group-chevron" viewBox="0 0 24 24" aria-hidden="true">
            <path d="M6 9 L12 15 L18 9" fill="none" stroke="#1a1a1a" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
    `;

    if (configs.length === 0) {
        listEl.innerHTML = '<div style="padding: 14px 10px; color:#888; font-size:13px;">暂无API方案</div>';
        return;
    }

    const session = getCurrentSession();
    const cid = String(State.currentContactId || '');
    const contact = cid ? State.contacts.find(c => String(c?.id || '') === cid) : null;
    const sid = String(session?.id || '');
    const isGroup = isGroupSession(session);
    const running = sid ? isAiRunningForSession(sid) : false;
    const interrupted = sid ? !!State.aiInterrupted?.[sid] : false;
    const canUseActions = !!session && (!contact || !contact.isBlocked);
    const regenMeta = canUseActions ? '<span class="chat-model-item-meta">重回</span>' : '<span class="chat-model-item-meta">不可用</span>';
    const interruptLabel = running ? '中断生成' : (interrupted ? '恢复生成' : '中断生成');
    const interruptIcon = running ? 'fa-pause-circle' : (interrupted ? 'fa-play-circle' : 'fa-pause-circle');
    const interruptMeta = running ? '<span class="chat-model-item-meta">执行</span>' : (interrupted ? '<span class="chat-model-item-meta">继续</span>' : '<span class="chat-model-item-meta">无任务</span>');
    const actionDisabledStyle = canUseActions ? '' : 'opacity:0.5;';
    const actionHtml = `
        <div class="chat-model-item" data-action="ai-regen" style="${actionDisabledStyle}">
            <span style="display:flex; align-items:center; gap:8px;"><i class="fas fa-redo"></i><span>重新生成</span></span>
            ${regenMeta}
        </div>
        <div class="chat-model-item" data-action="ai-interrupt" style="${actionDisabledStyle}">
            <span style="display:flex; align-items:center; gap:8px;"><i class="fas ${interruptIcon}"></i><span>${interruptLabel}</span></span>
            ${interruptMeta}
        </div>
        <div style="height:1px; background:rgba(0,0,0,0.06); margin:6px 4px;"></div>
    `;

    const configsHtml = configs.map((cfg) => {
        const apiId = String(cfg.id || '');
        const apiName = (cfg.name || '未命名方案').trim() || '未命名方案';
        const isCurrentApi = apiId === State.currentApiId;
        const open = apiId === openApiId;
        const badge = isCurrentApi ? '<span class="chat-model-group-badge">当前</span>' : '';
        const selectedModel = getSelectedModelForConfig(cfg);
        const subtitle = selectedModel ? escapeHtml(selectedModel) : '未选择模型';
        const models = getModelsForConfig(cfg);
        const body = (models.length === 0)
            ? '<div style="padding: 10px 10px; color:#888; font-size:13px;">未添加模型</div>'
            : models.map((m) => {
                const active = isCurrentApi && m === selectedModel ? 'active' : '';
                const meta = (isCurrentApi && m === selectedModel) ? '<span class="chat-model-item-meta">当前</span>' : '<span class="chat-model-item-meta">切换</span>';
                return `<div class="chat-model-item ${active}" data-action="pick-model" data-api-id="${encodeURIComponent(apiId)}" data-model="${encodeURIComponent(m)}"><span>${escapeHtml(m)}</span>${meta}</div>`;
            }).join('');

        return `
            <div class="chat-model-group ${open ? 'open' : ''}" data-api-id="${encodeURIComponent(apiId)}">
                <div class="chat-model-group-header" data-action="toggle-api" data-api-id="${encodeURIComponent(apiId)}">
                    <div>
                        <div class="chat-model-group-title">${escapeHtml(apiName)}${badge}</div>
                        <div class="chat-model-group-subtitle">${subtitle}</div>
                    </div>
                    ${chevronSvg}
                </div>
                <div class="chat-model-group-body">${body}</div>
            </div>
        `;
    }).join('');

    listEl.innerHTML = actionHtml + configsHtml;

    listEl.onclick = async (e) => {
        const regenEl = e.target.closest('[data-action="ai-regen"]');
        if (regenEl) {
            if (!session) {
                showToast('请先打开一个聊天');
                return;
            }
            if (contact?.isBlocked) {
                showToast('已加入黑名单');
                return;
            }
            try {
                if (isGroup) {
                    await regenerateGroupAiReply(session, { userText: getLatestGroupUserTriggerText(session) });
                } else {
                    await regenerateAiReplyForContact(contact, { allowMoneyActions: true });
                }
            } catch (error) {
                addSystemMessage(isGroup ? '群聊重新生成失败，请检查API设置' : '重新生成失败，请检查API设置');
            } finally {
                closeChatModelDropdown();
            }
            return;
        }

        const interruptEl = e.target.closest('[data-action="ai-interrupt"]');
        if (interruptEl) {
            if (!session) {
                showToast('请先打开一个聊天');
                return;
            }
            if (contact?.isBlocked) {
                showToast('已加入黑名单');
                return;
            }
            if (isAiRunningForSession(sid)) {
                if (!interruptAiForSession(sid)) showToast('当前没有生成任务');
                closeChatModelDropdown();
                return;
            }
            if (State.aiInterrupted?.[sid]) {
                try {
                    if (isGroup) {
                        await resumeGroupAiReply(session, { userText: getLatestGroupUserTriggerText(session) });
                    } else {
                        await resumeAiReplyForContact(contact, { allowMoneyActions: true });
                    }
                } catch (error) {
                    addSystemMessage(isGroup ? '群聊恢复失败，请检查API设置' : '恢复失败，请检查API设置');
                } finally {
                    closeChatModelDropdown();
                }
                return;
            }
            showToast('当前没有生成任务');
            closeChatModelDropdown();
            return;
        }

        const toggleEl = e.target.closest('[data-action="toggle-api"]');
        if (toggleEl) {
            const apiId = toggleEl.dataset.apiId ? decodeURIComponent(toggleEl.dataset.apiId) : '';
            if (apiId) {
                renderChatModelDropdown._openApiId = (renderChatModelDropdown._openApiId === apiId) ? '' : apiId;
                renderChatModelDropdown();
            }
            return;
        }

        const pickEl = e.target.closest('[data-action="pick-model"]');
        if (!pickEl) return;
        const apiId = pickEl.dataset.apiId ? decodeURIComponent(pickEl.dataset.apiId) : '';
        const model = pickEl.dataset.model ? decodeURIComponent(pickEl.dataset.model) : '';
        if (!apiId || !model) return;

        const cfg = State.apiConfigs.find(c => String(c.id || '') === apiId);
        if (!cfg) return;

        State.currentApiId = apiId;
        Storage.saveCurrentApiId(apiId);

        cfg.model = model;
        if (!Array.isArray(cfg.models)) cfg.models = [];
        if (!cfg.models.includes(model)) cfg.models = [...cfg.models, model];
        Storage.saveApiConfigs(State.apiConfigs);

        updateChatModelSwitchButton();
        showToast(`已切换：${model}`);
        closeChatModelDropdown();
    };
}

function toggleChatModelDropdown() {
    const dropdown = document.getElementById('chat-model-dropdown');
    const cfg = State.apiConfigs.find(c => c.id === State.currentApiId);
    if (!dropdown || !cfg) {
        showToast('请先配置API');
        return;
    }

    if (isChatModelDropdownOpen()) {
        closeChatModelDropdown();
        return;
    }

    dropdown.style.display = '';
    renderChatModelDropdown();
}

function applyApiModelUIFromConfig(config) {
    const input = document.getElementById('api-model-input');
    if (input) input.value = config?.model || '';
    updateApiModelSelectedHint(config);
    renderSelectedModelsList(config);
    updateChatModelSwitchButton();
}

function getDraftApiConfigFromForm() {
    const useProxy = document.getElementById('api-proxy-toggle')?.classList.contains('active') || false;
    const visionEnabled = document.getElementById('api-vision-toggle')?.classList.contains('active') || false;
    const streamEnabled = document.getElementById('api-stream-toggle')?.classList.contains('active') || false;
    return {
        name: document.getElementById('api-name-input')?.value?.trim() || '未命名方案',
        apiUrl: document.getElementById('api-url-input')?.value?.trim() || '',
        apiKey: document.getElementById('api-key-input')?.value?.trim() || '',
        model: document.getElementById('api-model-input')?.value?.trim() || '',
        visionEnabled,
        streamEnabled,
        useProxy,
        proxyUrl: document.getElementById('api-proxy-url-input')?.value?.trim() || ''
    };
}

async function testCurrentApiConfig() {
    const cfg = getDraftApiConfigFromForm();
    if (cfg.useProxy) {
        if (!cfg.proxyUrl) {
            showToast('请先填写代理地址');
            return;
        }
    } else {
        if (!cfg.apiUrl) {
            showToast('请先填写 API URL');
            return;
        }
        if (!cfg.apiKey) {
            showToast('请先填写 API Key');
            return;
        }
    }

    const testMessages = [{ role: 'user', content: '你好' }];
    let url = cfg.useProxy ? cfg.proxyUrl : normalizeChatCompletionsUrl(cfg.apiUrl);
    try {
        const headers = { 'Content-Type': 'application/json' };
        if (!cfg.useProxy) headers.Authorization = `Bearer ${cfg.apiKey}`;
        const response = await fetch(url, {
            method: 'POST',
            headers,
            body: JSON.stringify({
                model: cfg.model || 'gpt-3.5-turbo',
                messages: testMessages
            })
        });
        if (!response.ok) {
            let errMsg = `HTTP ${response.status}`;
            try {
                const errData = await response.json();
                errMsg = errData?.error?.message || errData?.error || errMsg;
            } catch (e) {
            }
            showToast(`测试失败：${errMsg}`);
            return;
        }
        showToast('测试成功');
    } catch (e) {
        const msg = (e && e.message) ? e.message : '网络错误';
        if (/Failed to fetch|NetworkError/i.test(msg)) {
            showToast('测试失败：可能是跨域/CORS，建议开启代理');
        } else {
            showToast(`测试失败：${msg}`);
        }
    }
}

async function testCurrentApiStreamSupport() {
    const cfg = getDraftApiConfigFromForm();
    if (cfg.useProxy) {
        if (!cfg.proxyUrl) {
            showToast('请先填写代理地址');
            return;
        }
    } else {
        if (!cfg.apiUrl) {
            showToast('请先填写 API URL');
            return;
        }
        if (!cfg.apiKey) {
            showToast('请先填写 API Key');
            return;
        }
    }

    const testMessages = [{ role: 'user', content: '你好' }];
    let url = cfg.useProxy ? cfg.proxyUrl : normalizeChatCompletionsUrl(cfg.apiUrl);
    const controller = new AbortController();
    let timedOut = false;
    const stop = setTimeout(() => {
        timedOut = true;
        try { controller.abort(); } catch (e) {}
    }, 2500);

    try {
        const headers = { 'Content-Type': 'application/json' };
        if (!cfg.useProxy) headers.Authorization = `Bearer ${cfg.apiKey}`;
        const response = await fetch(url, {
            method: 'POST',
            headers,
            signal: controller.signal,
            body: JSON.stringify({
                model: cfg.model || 'gpt-3.5-turbo',
                messages: testMessages,
                stream: true
            })
        });
        const ct = String(response.headers.get('content-type') || '');
        if (!response.ok) {
            showToast(`测试失败：HTTP ${response.status}`);
            return;
        }
        if (/text\/event-stream/i.test(ct)) {
            showToast('支持流式（SSE）');
            try { controller.abort(); } catch (e) {}
            return;
        }
        showToast('不支持流式：返回的不是 SSE');
    } catch (e) {
        const msg = (e && e.message) ? e.message : '网络错误';
        if (/AbortError/i.test(msg) || /aborted/i.test(msg)) {
            if (timedOut) {
                showToast('测试超时：可能不支持SSE或代理/网络把流“憋住”了');
            }
            return;
        }
        if (/Failed to fetch|NetworkError/i.test(msg)) {
            showToast('测试失败：可能是跨域/CORS，建议开启代理');
        } else {
            showToast(`测试失败：${msg}`);
        }
    } finally {
        clearTimeout(stop);
    }
}

async function fetchModelsListForConfig(config) {
    const useProxy = !!config?.useProxy;
    if (useProxy) {
        const proxyUrl = (config?.proxyUrl || '').trim();
        if (!proxyUrl) throw new Error('请先填写代理地址');
        const tryFetch = async (url, init) => {
            const res = await fetch(url, init);
            if (!res.ok) throw new Error(`HTTP ${res.status}`);
            return res.json();
        };

        let data = null;
        try {
            data = await tryFetch(proxyUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ op: 'models' })
            });
        } catch (e) {
            try {
                const joiner = proxyUrl.includes('?') ? '&' : '?';
                data = await tryFetch(`${proxyUrl}${joiner}op=models`, { method: 'GET' });
            } catch (e2) {
                throw e;
            }
        }

        const items = Array.isArray(data?.data) ? data.data : (Array.isArray(data) ? data : []);
        return items.map(it => (typeof it === 'string' ? it : it?.id)).filter(Boolean);
    }

    const apiUrl = (config?.apiUrl || '').trim();
    const apiKey = (config?.apiKey || '').trim();
    if (!apiUrl || !apiKey) throw new Error('请先填写 API URL 与 API Key');

    const tryEndpoints = [];
    const normalized = normalizeModelsUrlFromChatUrl(apiUrl);
    if (normalized) tryEndpoints.push(normalized);

    try {
        const u = new URL(apiUrl);
        const rawPath = u.pathname.replace(/\/+$/, '');
        let basePath = rawPath;
        basePath = basePath.replace(/\/v1\/chat\/completions$/i, '');
        basePath = basePath.replace(/\/chat\/completions$/i, '');
        basePath = basePath.replace(/\/v1$/i, '');
        const base = `${u.origin}${basePath}`;
        tryEndpoints.push(`${base}/v1/models`);
        tryEndpoints.push(`${base}/v1beta/models`);
        tryEndpoints.push(`${base}/models`);
    } catch (e) {
    }

    const endpoints = Array.from(new Set(tryEndpoints)).filter(Boolean);
    let lastErr = null;

    for (const endpoint of endpoints) {
        try {
            const response = await fetch(endpoint, {
                method: 'GET',
                headers: { 'Authorization': `Bearer ${apiKey}` }
            });
            if (!response.ok) throw new Error(`HTTP ${response.status}`);
            const data = await response.json();

            if (Array.isArray(data?.data)) {
                const ids = data.data.map(it => it?.id).filter(Boolean);
                if (ids.length > 0) return ids;
            }

            if (Array.isArray(data)) {
                const ids = data.map(it => (typeof it === 'string' ? it : it?.id)).filter(Boolean);
                if (ids.length > 0) return ids;
            }

            if (Array.isArray(data?.models)) {
                const modelNames = data.models
                    .map(m => m?.name || m?.id || m)
                    .map(x => (typeof x === 'string' ? x.replace(/^models\//, '') : ''))
                    .filter(Boolean);
                if (modelNames.length > 0) return modelNames;
            }
        } catch (e) {
            lastErr = e;
        }
    }

    throw lastErr || new Error('未获取到模型列表');
}

function openModelPickerModal(config, models, options = {}) {
    const modal = document.getElementById('model-picker-modal');
    const overlay = document.getElementById('model-picker-overlay');
    const listEl = document.getElementById('model-picker-list');
    const searchEl = document.getElementById('model-picker-search');
    const clearBtn = document.getElementById('model-picker-clear');
    const selectAllBtn = document.getElementById('model-picker-selectall');
    const confirmBtn = document.getElementById('model-picker-confirm');

    if (!modal || !overlay || !listEl || !searchEl || !clearBtn || !selectAllBtn || !confirmBtn) {
        showToast('模型选择器缺失');
        return;
    }

    const all = Array.isArray(models) ? models.filter(Boolean) : [];
    const single = !!options?.single;
    const onConfirm = typeof options?.onConfirm === 'function' ? options.onConfirm : null;
    const title = String(options?.title || '').trim();
    const titleEl = modal.querySelector('.wechat-dialog-title');
    if (titleEl) titleEl.textContent = title || (single ? '选择模型' : '选择模型（可多选）');

    clearBtn.style.display = single ? 'none' : '';
    selectAllBtn.style.display = single ? 'none' : '';

    const selected = new Set(Array.isArray(config.models) ? config.models : []);
    let current = (config.model || '').trim();
    if (current) selected.add(current);
    if (!current && selected.size > 0) current = Array.from(selected)[0];
    if (single && current) {
        selected.clear();
        selected.add(current);
    }

    const getFiltered = () => {
        const kw = (searchEl.value || '').trim().toLowerCase();
        if (!kw) return all;
        return all.filter(m => String(m).toLowerCase().includes(kw));
    };

    const render = () => {
        const filtered = getFiltered();
        listEl.innerHTML = filtered.map((m) => {
            const checked = selected.has(m) ? 'checked' : '';
            const badgeText = (m === current) ? '当前' : '设为当前';
            return `
                <div class="model-picker-item" data-model="${encodeURIComponent(m)}">
                    <input type="checkbox" ${checked} />
                    <div class="model-picker-name">${escapeHtml(m)}</div>
                    <span class="model-picker-badge">${badgeText}</span>
                </div>
            `;
        }).join('');
    };

    const close = () => {
        modal.classList.remove('show');
        overlay.onclick = null;
        searchEl.oninput = null;
        clearBtn.onclick = null;
        selectAllBtn.onclick = null;
        confirmBtn.onclick = null;
        listEl.onclick = null;
    };

    overlay.onclick = close;

    searchEl.oninput = () => render();

    listEl.onclick = (e) => {
        const item = e.target.closest('.model-picker-item');
        if (!item) return;
        const model = item.dataset.model ? decodeURIComponent(item.dataset.model) : '';
        if (!model) return;

        if (e.target.classList.contains('model-picker-badge')) {
            current = model;
            if (single) {
                selected.clear();
                selected.add(model);
            } else {
                selected.add(model);
            }
            render();
            return;
        }

        const checkbox = item.querySelector('input[type="checkbox"]');
        if (!checkbox) return;
        const nextChecked = e.target === checkbox ? checkbox.checked : !checkbox.checked;
        checkbox.checked = nextChecked;
        if (nextChecked) {
            if (single) {
                selected.clear();
                selected.add(model);
                current = model;
            } else {
                selected.add(model);
                if (!current) current = model;
            }
        } else {
            selected.delete(model);
            if (current === model) current = '';
        }
        if (!current && selected.size > 0) current = Array.from(selected)[0];
        render();
    };

    clearBtn.onclick = () => {
        selected.clear();
        current = '';
        render();
    };

    selectAllBtn.onclick = () => {
        getFiltered().forEach(m => selected.add(m));
        if (!current && selected.size > 0) current = Array.from(selected)[0];
        render();
    };

    confirmBtn.onclick = () => {
        const picked = Array.from(selected);
        if (picked.length === 0) {
            showToast('请至少选择 1 个模型');
            return;
        }
        if (!current || !selected.has(current)) current = picked[0];

        if (onConfirm) {
            try {
                onConfirm({ picked, current, all });
            } catch (e) {
            }
            close();
            return;
        }

        config.availableModels = all;
        config.models = picked;
        config.model = current;

        applyApiModelUIFromConfig(config);
        Storage.saveApiConfigs(State.apiConfigs);
        showToast(`已选择 ${picked.length} 个模型`);
        close();
    };

    modal.classList.add('show');
    render();
    setTimeout(() => searchEl.focus(), 80);
}

async function fetchAndPickModelsForCurrentConfig() {
    const config = State.apiConfigs.find(c => c.id === State.currentApiId);
    if (!config) return;

    try {
        const draft = getDraftApiConfigFromForm();
        const cacheKey = getModelsCacheKey(draft);
        if (config.availableModelsKey === cacheKey && Array.isArray(config.availableModels) && config.availableModels.length > 0) {
            openModelPickerModal(config, config.availableModels);
            return;
        }
        const tempConfig = {
            apiUrl: draft.apiUrl,
            apiKey: draft.apiKey,
            useProxy: draft.useProxy,
            proxyUrl: draft.proxyUrl
        };
        const models = await fetchModelsListForConfig(tempConfig);
        const uniq = Array.from(new Set(models)).sort((a, b) => String(a).localeCompare(String(b)));
        if (uniq.length === 0) {
            showToast('未获取到模型列表');
            return;
        }
        config.availableModels = uniq;
        config.availableModelsKey = cacheKey;
        Storage.saveApiConfigs(State.apiConfigs);
        openModelPickerModal(config, uniq);
    } catch (e) {
        const msg = (e && e.message) ? e.message : '网络错误';
        if (/Failed to fetch|NetworkError/i.test(msg)) {
            showToast('获取失败：可能是跨域/CORS，建议开启代理');
        } else {
            showToast(`获取失败：${msg}`);
        }
    }
}

