    const getChatsExportMode = () => {
        const el = document.getElementById('backup-chats-mode');
        const v = String(el?.value || 'all').trim();
        return (v === 'last200') ? 'last200' : 'all';
    };

    const blobToDataUrl = async (blob) => {
        if (!(blob instanceof Blob)) return '';
        return await new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => resolve(String(reader.result || ''));
            reader.onerror = () => reject(reader.error || new Error('blob-read-failed'));
            reader.readAsDataURL(blob);
        }).catch(() => '');
    };

    const readAllObjectStoreRecords = async (openDb, storeName) => {
        const db = await openDb();
        if (!db) return [];
        return await new Promise((resolve, reject) => {
            const tx = db.transaction(storeName, 'readonly');
            const store = tx.objectStore(storeName);
            const req = store.openCursor();
            const rows = [];
            req.onsuccess = () => {
                const cursor = req.result;
                if (!cursor) {
                    resolve(rows);
                    return;
                }
                rows.push(cursor.value);
                cursor.continue();
            };
            req.onerror = () => reject(req.error || new Error('indexeddb-readall-failed'));
        }).catch(() => []);
    };

    const countObjectStoreRecords = async (openDb, storeName) => {
        const db = await openDb();
        if (!db) return 0;
        return await new Promise((resolve, reject) => {
            const tx = db.transaction(storeName, 'readonly');
            const store = tx.objectStore(storeName);
            const req = store.count();
            req.onsuccess = () => resolve(Number(req.result || 0));
            req.onerror = () => reject(req.error || new Error('indexeddb-count-failed'));
        }).catch(() => 0);
    };

    const clearObjectStoreRecords = async (openDb, storeName) => {
        const db = await openDb();
        if (!db) return false;
        return await new Promise((resolve, reject) => {
            const tx = db.transaction(storeName, 'readwrite');
            const store = tx.objectStore(storeName);
            const req = store.clear();
            req.onsuccess = () => resolve(true);
            req.onerror = () => reject(req.error || new Error('indexeddb-clear-failed'));
        }).catch(() => false);
    };

    const getUiDesignerPositionSnapshot = () => {
        const raw = localStorage.getItem('wechat_ui_designer_pos');
        if (!raw) return null;
        try {
            const parsed = JSON.parse(raw);
            if (parsed && typeof parsed === 'object' && Number.isFinite(parsed.left) && Number.isFinite(parsed.top)) {
                return { left: Number(parsed.left), top: Number(parsed.top) };
            }
        } catch (e) {
        }
        return null;
    };

    const applyUiBackupDesignerState = (designer) => {
        const raw = designer && typeof designer === 'object' ? designer : {};
        const locked = !!raw.locked;
        const scale = Math.max(70, Math.min(120, parseInt(raw.scale, 10) || 100));
        const activeTab = normalizeUiDesignerTab(raw.activeTab);
        const position = raw.position && typeof raw.position === 'object'
            ? {
                left: Number(raw.position.left),
                top: Number(raw.position.top)
            }
            : null;
        setUiDesignerLocked(locked);
        setUiDesignerActiveTab(activeTab);
        try { localStorage.setItem('wechat_ui_designer_scale', String(scale)); } catch (e) {}
        if (position && Number.isFinite(position.left) && Number.isFinite(position.top)) {
            try { localStorage.setItem('wechat_ui_designer_pos', JSON.stringify(position)); } catch (e) {}
        }
    };

    const exportBackupAssets = async () => {
        const uiFontsMeta = Storage.getUiFonts();
        const uiFontRecords = [];
        const mediaRecords = [];
        const fontKeys = Object.keys(uiFontsMeta || {});

        for (const key of fontKeys) {
            const meta = uiFontsMeta[key];
            if (!(meta && typeof meta === 'object' && meta.storage === 'idb')) continue;
            const record = await Storage.getUiFontRecord(key);
            const blob = record?.blob;
            const dataUrl = await blobToDataUrl(blob);
            if (!dataUrl) continue;
            uiFontRecords.push({
                key,
                dataUrl,
                type: String(record?.type || blob?.type || meta.type || ''),
                size: Number(record?.size || blob?.size || meta.size || 0),
                updatedAt: Number(record?.updatedAt || meta.updatedAt || Date.now())
            });
        }

        const mediaRows = await readAllObjectStoreRecords(() => Storage.openMediaDb(), Storage.MEDIA_IDB_STORE);
        for (const row of mediaRows) {
            const key = String(row?.key || '').trim();
            const blob = row?.blob;
            if (!key || !(blob instanceof Blob)) continue;
            const dataUrl = await blobToDataUrl(blob);
            if (!dataUrl) continue;
            mediaRecords.push({
                key,
                dataUrl,
                type: String(row?.type || blob.type || ''),
                size: Number(row?.size || blob.size || 0),
                updatedAt: Number(row?.updatedAt || Date.now()),
                kind: String(row?.kind || 'image')
            });
        }

        return {
            uiFontsMeta,
            uiFontRecords,
            mediaRecords
        };
    };

    const importBackupAssets = async (assets) => {
        const raw = assets && typeof assets === 'object' ? assets : {};
        const nextUiFontsMeta = raw.uiFontsMeta && typeof raw.uiFontsMeta === 'object'
            ? { ...raw.uiFontsMeta }
            : { ...Storage.getUiFonts() };
        const uiFontRecords = Array.isArray(raw.uiFontRecords) ? raw.uiFontRecords : [];
        const mediaRecords = Array.isArray(raw.mediaRecords) ? raw.mediaRecords : [];

        await clearObjectStoreRecords(() => Storage.openUiFontDb(), Storage.UI_FONT_IDB_STORE);
        for (const item of uiFontRecords) {
            const key = String(item?.key || '').trim();
            const blob = dataUrlToBlob(item?.dataUrl);
            if (!key || !(blob instanceof Blob)) continue;
            await Storage.putUiFontRecord({
                key,
                blob,
                updatedAt: Number(item?.updatedAt || Date.now()),
                type: String(item?.type || blob.type || ''),
                size: Number(item?.size || blob.size || 0)
            });
            nextUiFontsMeta[key] = {
                storage: 'idb',
                type: String(item?.type || blob.type || ''),
                size: Number(item?.size || blob.size || 0),
                updatedAt: Number(item?.updatedAt || Date.now())
            };
        }
        Storage.saveUiFonts(nextUiFontsMeta);
        if (Storage._uiFontRuntime && typeof Storage._uiFontRuntime === 'object') Storage._uiFontRuntime = {};
        if (Storage._uiFontObjectUrls && typeof Storage._uiFontObjectUrls === 'object') Storage._uiFontObjectUrls = {};

        await clearObjectStoreRecords(() => Storage.openMediaDb(), Storage.MEDIA_IDB_STORE);
        for (const item of mediaRecords) {
            const key = String(item?.key || '').trim();
            const blob = dataUrlToBlob(item?.dataUrl);
            if (!key || !(blob instanceof Blob)) continue;
            await Storage.putMediaRecord({
                key,
                blob,
                updatedAt: Number(item?.updatedAt || Date.now()),
                type: String(item?.type || blob.type || ''),
                size: Number(item?.size || blob.size || 0),
                kind: String(item?.kind || 'image')
            });
        }
        if (Storage._mediaRuntime && typeof Storage._mediaRuntime === 'object') Storage._mediaRuntime = {};
        if (Storage._mediaObjectUrls && typeof Storage._mediaObjectUrls === 'object') Storage._mediaObjectUrls = {};
        if (Storage._mediaDataUrlCache && typeof Storage._mediaDataUrlCache === 'object') Storage._mediaDataUrlCache = {};
    };

    const refreshBackupCounts = async () => {
        const userCount = document.getElementById('backup-count-user');
        const apiCount = document.getElementById('backup-count-api');
        const promptsCount = document.getElementById('backup-count-prompts');
        const summaryCount = document.getElementById('backup-count-summary');
        const uiCount = document.getElementById('backup-count-ui');
        const contactsCount = document.getElementById('backup-count-contacts');
        const sessionsCount = document.getElementById('backup-count-sessions');
        const chatsCount = document.getElementById('backup-count-chats');
        const worldbooksCount = document.getElementById('backup-count-worldbooks');
        const stickersCount = document.getElementById('backup-count-stickers');
        const favoritesCount = document.getElementById('backup-count-favorites');
        const walletCount = document.getElementById('backup-count-wallet');
        const momentsCount = document.getElementById('backup-count-moments');
        const assetsCount = document.getElementById('backup-count-assets');

        if (userCount) userCount.textContent = '1';
        if (apiCount) apiCount.textContent = `${(State.apiConfigs || []).length} 个`;
        if (promptsCount) promptsCount.textContent = '1';
        if (summaryCount) summaryCount.textContent = '1';
        if (uiCount) uiCount.textContent = `${(State.uiSchemes || []).length || 1} 套`;
        if (contactsCount) contactsCount.textContent = `${(State.contacts || []).length} 个`;
        if (sessionsCount) sessionsCount.textContent = `${(State.sessions || []).length} 个`;
        if (worldbooksCount) worldbooksCount.textContent = `${(State.worldbooks || []).length} 本`;
        if (stickersCount) stickersCount.textContent = `${(State.stickerLibraries || []).length} 个`;
        if (favoritesCount) favoritesCount.textContent = `${(State.favorites || []).length} 条`;
        if (walletCount) walletCount.textContent = '1';
        if (momentsCount) momentsCount.textContent = `${(State.moments || []).length} 条`;

        let msgCount = 0;
        let theaterCount = 0;
        const chatsMode = getChatsExportMode();
        const chats = State.chatHistories || {};
        Object.keys(chats).forEach((k) => {
            const arr = chats[k];
            if (Array.isArray(arr)) msgCount += (chatsMode === 'last200' ? Math.min(arr.length, 200) : arr.length);
        });
        const theaterHistories = State.theaterHistories || {};
        Object.keys(theaterHistories).forEach((k) => {
            const arr = theaterHistories[k];
            if (Array.isArray(arr)) theaterCount += arr.length;
        });
        if (chatsCount) chatsCount.textContent = `聊天 ${msgCount} / 剧场 ${theaterCount}`;

        if (assetsCount) {
            const fontCount = Object.keys(Storage.getUiFonts() || {}).length;
            const mediaCount = await countObjectStoreRecords(() => Storage.openMediaDb(), Storage.MEDIA_IDB_STORE);
            assetsCount.textContent = `${fontCount + mediaCount} 项`;
        }
    };

    const getSelectedBackupGroups = () => {
        const set = new Set();
        document.querySelectorAll('#settings-page .backup-check').forEach((el) => {
            if (el && el.checked) set.add(el.dataset.module);
        });
        return Array.from(set);
    };

    const buildBackupPayload = async (groups) => {
        const include = new Set(groups);
        const payload = {
            version: 2,
            schema: 'vechat-backup',
            app: 'VEchat',
            appVersion: '6.0.2',
            exportedAt: new Date().toISOString(),
            groups: {},
            data: {}
        };

        if (typeof Storage.flushChatHistories === 'function') {
            Storage.flushChatHistories();
        }
        if (typeof Storage.waitForPendingMigratedStateWrites === 'function') {
            await Storage.waitForPendingMigratedStateWrites();
        }

        if (include.has('user')) {
            payload.groups.user = true;
            payload.data.user = Storage.getUser();
        }
        if (include.has('api')) {
            payload.groups.api = true;
            payload.data.api = {
                apiConfigs: Storage.getApiConfigs(),
                currentApiId: Storage.getCurrentApiId(),
                momentsSubApiConfig: Storage.getMomentsSubApiConfig(),
                theaterApiId: (() => {
                    try { return String(localStorage.getItem(THEATER_API_STORAGE_KEY) || ''); } catch (e) { return ''; }
                })()
            };
        }
        if (include.has('prompts')) {
            payload.groups.prompts = true;
            payload.data.prompts = {
                globalPrompt: Storage.getGlobalPrompt(),
                promptPrefs: Storage.getPromptPrefs(),
                promptModules: Storage.getPromptModules(),
                promptScenarioTemplates: Storage.getPromptScenarioTemplates(),
                promptScenarioContext: Storage.getPromptScenarioContext(),
                unrestrictedConfig: Storage.getUnrestrictedConfig()
            };
        }
        if (include.has('summary')) {
            payload.groups.summary = true;
            payload.data.summary = {
                summaryConfig: Storage.getSummaryConfig(),
                vectorConfig: Storage.getVectorConfig(),
                summaryHistories: Storage.getSummaryHistories(),
                summaryVectors: Storage.getSummaryVectors()
            };
        }
        if (include.has('ui')) {
            payload.groups.ui = true;
            payload.data.ui = {
                uiPrefs: Storage.getUiPrefs(),
                uiSchemes: Storage.getUiSchemes(),
                currentUiSchemeId: Storage.getCurrentUiSchemeId(),
                themeMode: Storage.getThemeMode(),
                designer: {
                    locked: getUiDesignerLocked(),
                    scale: getUiDesignerScalePct(),
                    activeTab: getUiDesignerActiveTab(),
                    position: getUiDesignerPositionSnapshot()
                }
            };
        }
        if (include.has('contacts')) {
            payload.groups.contacts = true;
            payload.data.contacts = Storage.getContacts();
        }
        if (include.has('sessions')) {
            payload.groups.sessions = true;
            payload.data.sessions = Storage.getSessions();
        }
        if (include.has('chats')) {
            payload.groups.chats = true;
            payload.data.theaterHistories = Storage.getTheaterHistories();
            const raw = Storage.getChatHistories();
            const chatsMode = getChatsExportMode();
            if (chatsMode === 'last200') {
                const trimmed = {};
                Object.keys(raw || {}).forEach((cid) => {
                    const list = raw?.[cid];
                    if (Array.isArray(list)) trimmed[cid] = list.slice(-200);
                });
                payload.data.chats = trimmed;
            } else {
                payload.data.chats = raw;
            }
        }
        if (include.has('worldbooks')) {
            payload.groups.worldbooks = true;
            payload.data.worldbooks = Storage.getWorldbooks();
        }
        if (include.has('stickers')) {
            payload.groups.stickers = true;
            payload.data.stickers = Storage.getStickerLibraries();
        }
        if (include.has('favorites')) {
            payload.groups.favorites = true;
            payload.data.favorites = Storage.getFavorites();
        }
        if (include.has('wallet')) {
            payload.groups.wallet = true;
            payload.data.wallet = Storage.getWallet();
        }
        if (include.has('moments')) {
            payload.groups.moments = true;
            payload.data.moments = Storage.getMoments();
        }
        if (include.has('assets')) {
            payload.groups.assets = true;
            payload.data.assets = await exportBackupAssets();
        }

        return payload;
    };

    const downloadJson = (obj, filename) => {
        const text = JSON.stringify(obj, null, 2);
        return downloadTextFile(text, filename, 'application/json');
    };

    const reloadAllFromStorageAndRefreshUI = () => {
        State.user = Storage.getUser();
        State.apiConfigs = Storage.getApiConfigs();
        State.currentApiId = Storage.getCurrentApiId();
        if (!State.apiConfigs.find(c => c.id === State.currentApiId)) {
            State.currentApiId = State.apiConfigs[0]?.id || 'default';
            Storage.saveCurrentApiId(State.currentApiId);
        }
        State.uiSchemes = Storage.getUiSchemes();
        State.currentUiSchemeId = Storage.getCurrentUiSchemeId();
        if (!(State.uiSchemes || []).find((scheme) => String(scheme?.id || '') === String(State.currentUiSchemeId || ''))) {
            State.currentUiSchemeId = State.uiSchemes[0]?.id || Storage.DEFAULT_CURRENT_UI_SCHEME_ID;
            Storage.saveCurrentUiSchemeId(State.currentUiSchemeId);
        }
        const activeScheme = getUiSchemeById(State.currentUiSchemeId);
        State.uiPrefs = Storage.normalizeUiPrefs(activeScheme?.prefs || Storage.getUiPrefs());
        State.contacts = Storage.getContacts();
        State.sessions = Storage.getSessions();
        State.favorites = Storage.getFavorites();
        State.chatHistories = Storage.getChatHistories();
        State.theaterHistories = Storage.getTheaterHistories();
        State.globalPrompt = Storage.getGlobalPrompt();
        State.promptPrefs = Storage.getPromptPrefs();
        State.promptModules = Storage.getPromptModules();
        State.promptScenarioTemplates = Storage.getPromptScenarioTemplates();
        State.promptScenarioContext = Storage.getPromptScenarioContext();
        State.unrestrictedConfig = Storage.getUnrestrictedConfig();
        State.summaryConfig = Storage.getSummaryConfig();
        State.vectorConfig = Storage.getVectorConfig();
        State.momentsSubApiConfig = Storage.getMomentsSubApiConfig();
        State.summaryHistories = Storage.getSummaryHistories();
        State.worldbooks = Storage.getWorldbooks();
        State.stickerLibraries = Storage.getStickerLibraries();
        State.wallet = Storage.getWallet();
        State.moments = Storage.getMoments();
        State.summaryVectors = Storage.getSummaryVectors();

        renderUiSchemeSelect();
        uiDesignerDraft = Storage.normalizeUiPrefs(State.uiPrefs);
        syncUiDesignerControlsFromDraft();
        applyUiPrefs(State.uiPrefs);
        applyThemeMode(Storage.getThemeMode());
        initUserUI();
        initChatList();
        initContactsList();
        initDiscoverPage();
        initStickersPage();
        initMomentsPage();
        refreshUnrestrictedUi();
        refreshBackupCounts();
    };

    document.getElementById('settings-entry')?.addEventListener('click', () => {
        showPage('settings-page');
        refreshBackupCounts();
    });
    document.getElementById('settings-back-btn')?.addEventListener('click', () => {
        hidePage('settings-page');
    });
    document.getElementById('backup-select-all-cell')?.addEventListener('click', () => {
        document.querySelectorAll('#settings-page .backup-check').forEach((el) => { el.checked = true; });
    });
    document.getElementById('backup-select-none-cell')?.addEventListener('click', () => {
        document.querySelectorAll('#settings-page .backup-check').forEach((el) => { el.checked = false; });
    });
    document.getElementById('backup-chats-mode')?.addEventListener('change', () => {
        refreshBackupCounts();
    });
    document.getElementById('backup-export-selected-btn')?.addEventListener('click', async () => {
        const groups = getSelectedBackupGroups();
        if (groups.length === 0) {
            showToast('请先勾选要导出的模块');
            return;
        }
        const btn = document.getElementById('backup-export-selected-btn');
        if (!btn || btn.disabled) return;
        btn.disabled = true;
        try {
            showLoading('正在整理备份数据...');
            const payload = await buildBackupPayload(groups);
            const ts = new Date();
            const name = `VEchat_backup_${ts.getFullYear()}${String(ts.getMonth() + 1).padStart(2, '0')}${String(ts.getDate()).padStart(2, '0')}_${String(ts.getHours()).padStart(2, '0')}${String(ts.getMinutes()).padStart(2, '0')}.json`;
            const mode = downloadJson(payload, name);
            hideLoading();
            showToast(mode === 'native' ? '正在保存到下载目录' : '已导出');
        } catch (err) {
            hideLoading();
            showToast('导出失败，请检查本地存储空间');
        } finally {
            btn.disabled = false;
        }
    });

    document.getElementById('backup-import-btn')?.addEventListener('click', async () => {
        const groups = getSelectedBackupGroups();
        if (groups.length === 0) {
            showToast('请先勾选要导入的模块');
            return;
        }
        const ok = await WeChatUI.showConfirm('导入数据', '将从文件导入，并覆盖你勾选的模块数据。确定继续吗？', '导入', '取消', true);
        if (!ok) return;
        document.getElementById('backup-import-file')?.click();
    });

    document.getElementById('factory-reset-btn')?.addEventListener('click', async () => {
        const btn = document.getElementById('factory-reset-btn');
        if (!btn || btn.disabled) return;
        const ok = await WeChatUI.showConfirm(
            '恢复出厂',
            '这会清除本地保存的用户资料、聊天记录、朋友圈、钱包、提示词、UI 配置、本地图片和字体等全部记录，且无法恢复。确定继续吗？',
            '全部清除',
            '取消',
            true
        );
        if (!ok) return;
        const originalText = btn.textContent;
        btn.disabled = true;
        btn.dataset.busy = '1';
        btn.setAttribute('aria-busy', 'true');
        btn.style.opacity = '0.7';
        btn.style.cursor = 'not-allowed';
        try {
            showLoading('正在清除全部本地记录...');
            const cleared = await Storage.resetAllAppData();
            if (!cleared) {
                throw new Error('factory-reset-blocked');
            }
            showLoading('清除完成，正在重载...');
            setTimeout(() => {
                window.location.reload();
            }, 120);
        } catch (err) {
            hideLoading();
            showToast('清除失败，请稍后重试');
            btn.disabled = false;
            btn.dataset.busy = '0';
            btn.setAttribute('aria-busy', 'false');
            btn.style.opacity = '';
            btn.style.cursor = '';
            btn.textContent = originalText;
        }
    });

    document.getElementById('backup-import-file')?.addEventListener('change', async (e) => {
        const file = e.target.files?.[0];
        e.target.value = '';
        if (!file) return;
        let text = '';
        try {
            text = await file.text();
        } catch (err) {
            showToast('读取文件失败');
            return;
        }
        let parsed = null;
        try {
            parsed = JSON.parse(text);
        } catch (err) {
            showToast('文件不是有效 JSON');
            return;
        }
        const backupVersion = Number(parsed?.version || 0);
        if (!parsed || typeof parsed !== 'object' || ![1, 2].includes(backupVersion) || !parsed.data || typeof parsed.data !== 'object') {
            showToast('备份文件格式不支持');
            return;
        }

        const groups = getSelectedBackupGroups();
        const include = new Set(groups);
        const data = parsed.data || {};

        try {
            showLoading('正在导入并校验数据...');
            if (include.has('user') && data.user) Storage.saveUser(data.user);
            if (include.has('api') && data.api) {
                if (Array.isArray(data.api.apiConfigs)) Storage.saveApiConfigs(data.api.apiConfigs);
                if (typeof data.api.currentApiId === 'string') Storage.saveCurrentApiId(data.api.currentApiId);
                if (data.api.momentsSubApiConfig) Storage.saveMomentsSubApiConfig(data.api.momentsSubApiConfig);
                if (typeof data.api.theaterApiId === 'string') {
                    const validConfigs = Array.isArray(data.api.apiConfigs) ? data.api.apiConfigs : Storage.getApiConfigs();
                    const validId = validConfigs.some((item) => String(item?.id || '') === data.api.theaterApiId)
                        ? data.api.theaterApiId
                        : '';
                    try {
                        if (validId) localStorage.setItem(THEATER_API_STORAGE_KEY, validId);
                        else localStorage.removeItem(THEATER_API_STORAGE_KEY);
                    } catch (e) {}
                }
            }
            if (include.has('prompts') && data.prompts) {
                if (typeof data.prompts.globalPrompt === 'string') Storage.saveGlobalPrompt(data.prompts.globalPrompt);
                if (data.prompts.promptPrefs) Storage.savePromptPrefs(data.prompts.promptPrefs);
                if (data.prompts.promptModules) Storage.savePromptModules(data.prompts.promptModules);
                if (data.prompts.promptScenarioTemplates) Storage.savePromptScenarioTemplates(data.prompts.promptScenarioTemplates);
                if (data.prompts.promptScenarioContext) Storage.savePromptScenarioContext(data.prompts.promptScenarioContext);
                if (data.prompts.unrestrictedConfig) Storage.saveUnrestrictedConfig(data.prompts.unrestrictedConfig);
            }
            if (include.has('summary') && data.summary) {
                if (data.summary.summaryConfig) Storage.saveSummaryConfig(data.summary.summaryConfig);
                if (data.summary.vectorConfig) Storage.saveVectorConfig(data.summary.vectorConfig);
                if (data.summary.summaryHistories) Storage.saveSummaryHistories(data.summary.summaryHistories);
                if (data.summary.summaryVectors) Storage.saveSummaryVectors(data.summary.summaryVectors);
            }
            if (include.has('ui') && data.ui) {
                if (data.ui.uiPrefs) Storage.saveUiPrefs(Storage.normalizeUiPrefs(data.ui.uiPrefs));
                if (Array.isArray(data.ui.uiSchemes)) Storage.saveUiSchemes(data.ui.uiSchemes);
                if (typeof data.ui.currentUiSchemeId === 'string') Storage.saveCurrentUiSchemeId(data.ui.currentUiSchemeId);
                if (typeof data.ui.themeMode === 'string') Storage.saveThemeMode(data.ui.themeMode);
                applyUiBackupDesignerState(data.ui.designer);
            }
            if (include.has('contacts') && Array.isArray(data.contacts)) Storage.saveContacts(data.contacts);
            if (include.has('sessions') && Array.isArray(data.sessions)) Storage.saveSessions(data.sessions);
            if (include.has('chats') && data.chats && typeof data.chats === 'object') Storage.saveChatHistories(data.chats, { immediate: true });
            if (include.has('chats') && data.theaterHistories && typeof data.theaterHistories === 'object') Storage.saveTheaterHistories(data.theaterHistories);
            if (include.has('worldbooks') && Array.isArray(data.worldbooks)) Storage.saveWorldbooks(data.worldbooks);
            if (include.has('stickers') && Array.isArray(data.stickers)) Storage.saveStickerLibraries(data.stickers);
            if (include.has('favorites') && Array.isArray(data.favorites)) Storage.saveFavorites(data.favorites);
            if (include.has('wallet') && data.wallet) Storage.saveWallet(data.wallet);
            if (include.has('moments') && Array.isArray(data.moments)) Storage.saveMoments(data.moments);
            if (include.has('assets') && data.assets) await importBackupAssets(data.assets);
            if (typeof Storage.waitForPendingMigratedStateWrites === 'function') {
                await Storage.waitForPendingMigratedStateWrites();
            }

            reloadAllFromStorageAndRefreshUI();
            hideLoading();
            showToast(backupVersion === 1 ? '旧版备份已兼容导入' : '导入完成');
        } catch (err) {
            hideLoading();
            showToast('导入失败，原文件可能不完整或存储空间不足');
        }
    });

