function buildMomentPromptIdentityBlock(contact, options = {}) {
    const roleName = String(getContactDisplayName(contact) || contact?.name || '联系人').trim() || '联系人';
    const userProfile = getUserProfileForContact(contact || {});
    const userName = String(userProfile?.nickname || State.user?.nickname || '用户').trim() || '用户';
    const mode = String(options?.mode || '').trim();
    const lines = [
        '【名字映射】',
        `- {char} = ${roleName}`,
        `- {user} = ${userName}`,
        `- {char} 始终指当前发言的角色本人，{user} 始终指用户本人`
    ];
    if (mode === 'interaction') {
        const viewerName = String(options?.viewerName || userName).trim() || userName;
        lines.push(`- 你现在是在以 ${roleName} 的身份看 ${viewerName} 发的朋友圈，不要替 ${viewerName} 说话，也不要代替 ${viewerName} 点赞或评论`);
    } else if (mode === 'social') {
        lines.push(`- 你负责生成围观这条朋友圈的其他 NPC，不要让 ${roleName} 本人或用户 ${userName} 混进 NPC 阵列里`);
    } else if (mode === 'reply') {
        lines.push(`- 你现在是在用 ${roleName} 本人的口吻回评论，不要切到用户 ${userName} 的视角`);
    } else {
        lines.push(`- 你发的是 ${roleName} 本人的朋友圈，不要把自己写成用户 ${userName}`);
    }
    if (userProfile?.userPersona) {
        lines.push(`【关于用户】\n用户的身份与设定：${userProfile.userPersona}`);
    }
    return lines.join('\n');
}

function getCallModeRules(type) {
    return type === 'video'
        ? `【通话模式】
- 这是视频通话：你可以像小说一样细致地描写画面、表情、动作、视线、环境细节等。
- 所有的非语言描写（画面/动作/表情等）必须用【】括起来（例如“【你笑着抬眼看屏幕】”）。
- 语言部分直接输出，不要带引号。`
        : `【通话模式】
- 这是语音通话：你可以描写声音的质感、语气、呼吸声、背景噪音、环境音等。
- 所有的非语言描写（声音/语气/噪音等）必须用【】括起来（例如“【电话那头传来沙沙的风声】”）。
- 禁止写“我点头/我走过去/我看见...”这类纯视觉动作，只能描写能被听到的内容。
- 语言部分直接输出，不要带引号。`;
}

function buildCallSystemPrompt(contact, type, summaryMemoryText = '', options = {}) {
    const templates = State.promptScenarioTemplates || Storage.DEFAULT_PROMPT_SCENARIO_TEMPLATES;
    const summaryMemory = String(summaryMemoryText || '').trim();
    const roleName = contact?.name || '联系人';
    const userProfile = getUserProfileForContact(contact);
    const summaryMemoryAnchor = summaryMemory
        ? `下面是已归档的记忆片段。阅读时固定理解：其中“我”始终指 ${roleName}，另一方统一指 ${userProfile.nickname || '用户'}。`
        : '';
    const vars = getScenarioPromptVars(contact, {
        call_kind: type === 'video' ? '视频通话' : '语音通话',
        mode_rules: getCallModeRules(type),
        summary_memory_block: summaryMemory ? `【已归档记忆】\n${summaryMemoryAnchor}\n${summaryMemory}\n\n` : ''
    });
    const rendered = prependUnrestrictedPrompt(renderPromptTemplate(templates.callSystem || Storage.DEFAULT_PROMPT_SCENARIO_TEMPLATES.callSystem, vars));
    const sharedGroupContext = options.includeSharedGroupContext === false
        ? ''
        : buildSharedGroupContextForPrivateContact(contact).text;
    return [
        rendered,
        sharedGroupContext,
        '【通话回复终检｜最高优先】\n- 你已经在通话中，用户点击“AI 回复”就是要求你现在接话。\n- 必须输出一段可见的纯文本通话内容，不得沉默，不得输出空内容，也不要回复“系统禁止动作指令”。\n- 不要输出 JSON、action、Markdown 或规则解释。'
    ].filter(Boolean).join('\n\n');
}

function buildCallAutoReplyPrompt(pendingUserText = '', hasPendingInput = false) {
    if (!hasPendingInput) {
        return '（系统）用户现在在通话中等待你的回应。请接话或提一个自然的问题。';
    }
    const templates = State.promptScenarioTemplates || Storage.DEFAULT_PROMPT_SCENARIO_TEMPLATES;
    return renderPromptTemplate(templates.callAutoReply || Storage.DEFAULT_PROMPT_SCENARIO_TEMPLATES.callAutoReply, {
        pending_user_text: String(pendingUserText || '').trim() || '（用户暂时没有说话）'
    });
}

function buildSummaryPromptText(basePrompt, previousMemory, newChatText) {
    const base = String(basePrompt || '').trim() || Storage.DEFAULT_SUMMARY_PROMPT;
    const prev = String(previousMemory || '').trim();
    const next = String(newChatText || '').trim();
    if (prev) {
        return prependUnrestrictedPrompt(`${base}\n\n【之前记下的内容】\n${prev}\n\n【新的聊天记录】\n${next}\n\n请把新内容自然地融进旧记事里，继续保持“我写给自己的记事本”口吻。如果新旧信息冲突，以最新聊天为准，直接改成新的状态。`);
    }
    return prependUnrestrictedPrompt(`${base}\n\n【聊天记录】\n${next}\n\n请把这些内容整理成我写给自己的私人记事，不要写成冷冰冰的总结报告。`);
}

function getActiveCallContactIds() {
    if (!window.__wechatActiveCallContactIds) {
        window.__wechatActiveCallContactIds = new Set();
    }
    return window.__wechatActiveCallContactIds;
}

function ensureAiTasksStore() {
    if (!State.aiTasks || typeof State.aiTasks !== 'object') {
        State.aiTasks = {};
    }
    return State.aiTasks;
}

function getAiTaskForSession(sessionId) {
    const sid = String(sessionId || '').trim();
    if (!sid) return null;
    return ensureAiTasksStore()[sid] || null;
}

function setAiTaskForSession(sessionId, controller, extra = {}) {
    const sid = String(sessionId || '').trim();
    if (!sid) return null;
    const task = {
        running: true,
        controller: controller || null,
        sessionId: sid,
        nativeTaskToken: beginNativeAiGeneration(extra.nativeLabel || 'VEchat 正在生成回复'),
        ...extra
    };
    ensureAiTasksStore()[sid] = task;
    return task;
}

function clearAiTaskForSession(sessionId, controller = null) {
    const sid = String(sessionId || '').trim();
    if (!sid) return;
    const tasks = ensureAiTasksStore();
    const current = tasks[sid];
    if (!current) return;
    if (controller && current.controller && current.controller !== controller) return;
    endNativeAiGeneration(current.nativeTaskToken);
    delete tasks[sid];
}

function setContactCallActive(contactId, active = true) {
    const id = String(contactId || '').trim();
    if (!id) return;
    const activeIds = getActiveCallContactIds();
    if (active) activeIds.add(id);
    else activeIds.delete(id);
}

function isContactCallActive(contactId) {
    const id = String(contactId || '').trim();
    if (!id) return false;
    return getActiveCallContactIds().has(id);
}

function touchContactActivity(contactOrId, activityTs = Date.now(), options = {}) {
    const id = typeof contactOrId === 'string'
        ? String(contactOrId || '').trim()
        : String(contactOrId?.id || '').trim();
    if (!id) return null;
    const target = (State.contacts || []).find((item) => String(item?.id || '').trim() === id);
    if (!target) return null;
    const ts = Number(activityTs || Date.now()) || Date.now();
    target.lastActiveAt = ts;
    refreshAutoMessageScheduleFromActivity(target, ts);
    if (options.save) {
        Storage.saveContacts(State.contacts);
    }
    return target;
}

function refreshAutoMessageScheduleFromActivity(contact, activityTs = Date.now()) {
    if (!contact || !contact.autoMessageEnabled) return;
    const intervalMin = Math.max(1, Math.min(1440, parseInt(contact.autoMessageIntervalMin ?? 30, 10) || 30));
    const baseTs = Number(activityTs || Date.now()) || Date.now();
    contact.nextAutoMessageAt = baseTs + intervalMin * 60 * 1000;
}

function startProactiveScheduler() {
    if (startProactiveScheduler._timer) return;
    if (!startProactiveScheduler._runningIds) {
        startProactiveScheduler._runningIds = new Set();
    }
    startProactiveScheduler._timer = setInterval(async () => {
        if (startProactiveScheduler._tickRunning) return;
        startProactiveScheduler._tickRunning = true;
        const now = Date.now();
        try {
            for (const contact of (State.contacts || [])) {
                if (!contact || !contact.autoMessageEnabled) continue;
                if (contact.isBlocked) continue;
                const contactId = String(contact.id || '');
                if (!contactId) continue;
                if (isAiRunningForContact(contactId)) continue;
                if (startProactiveScheduler._runningIds.has(contactId)) continue;
                if (isContactCallActive(contactId)) continue;

                const intervalMin = Math.max(1, Math.min(1440, parseInt(contact.autoMessageIntervalMin ?? 30, 10) || 30));
                const intervalMs = intervalMin * 60 * 1000;
                const lastActiveAt = Number(contact.lastActiveAt || 0) || 0;
                const nextDueByActivity = lastActiveAt ? (lastActiveAt + intervalMs) : 0;
                let nextAutoMessageAt = Number(contact.nextAutoMessageAt || 0) || 0;

                if (!nextAutoMessageAt) {
                    nextAutoMessageAt = nextDueByActivity || (now + intervalMs);
                }
                if (nextDueByActivity && nextDueByActivity > nextAutoMessageAt) {
                    nextAutoMessageAt = nextDueByActivity;
                }
                if (nextAutoMessageAt !== (Number(contact.nextAutoMessageAt || 0) || 0)) {
                    contact.nextAutoMessageAt = nextAutoMessageAt;
                    Storage.saveContacts(State.contacts);
                }
                if (now < nextAutoMessageAt) continue;

                startProactiveScheduler._runningIds.add(contactId);
                try {
                    await fetchAIResponse(contact, {
                        proactive: true,
                        silent: contact.id !== State.currentContactId,
                        allowMoneyActions: false
                    });
                    contact.nextAutoMessageAt = Date.now() + intervalMs;
                    Storage.saveContacts(State.contacts);
                    if (contact.id !== State.currentContactId) initChatList();
                } catch (e) {
                    const retryMs = Math.min(intervalMs, 60 * 1000);
                    contact.nextAutoMessageAt = Date.now() + retryMs;
                    Storage.saveContacts(State.contacts);
                    console.error('主动发消息触发失败:', contactId, e);
                } finally {
                    startProactiveScheduler._runningIds.delete(contactId);
                }
            }
        } finally {
            startProactiveScheduler._tickRunning = false;
        }
    }, 30000);
}

// ==========================================
// 工具函数
// ==========================================

function dataUrlToBlob(dataUrl) {
    const raw = String(dataUrl || '').trim();
    const match = raw.match(/^data:([^;,]+)?(;base64)?,([\s\S]*)$/i);
    if (!match) return null;
    const mimeType = String(match[1] || 'application/octet-stream').trim() || 'application/octet-stream';
    const isBase64 = !!match[2];
    try {
        if (isBase64) {
            const binary = atob(match[3] || '');
            const len = binary.length;
            const bytes = new Uint8Array(len);
            for (let i = 0; i < len; i++) bytes[i] = binary.charCodeAt(i);
            return new Blob([bytes], { type: mimeType });
        }
        return new Blob([decodeURIComponent(match[3] || '')], { type: mimeType });
    } catch (e) {
        return null;
    }
}

function getStoredImageAssetKey(payload) {
    return String(payload?.assetKey || payload?.mediaKey || '').trim();
}

function getAnyStoredImageAssetKey(value) {
    if (!value || typeof value !== 'object') return '';
    return getStoredImageAssetKey(value);
}

function getStoredImageSourceSync(payload) {
    const assetKey = getStoredImageAssetKey(payload);
    if (assetKey) {
        const runtimeUrl = Storage.getMediaRuntimeUrl(assetKey);
        if (runtimeUrl) return runtimeUrl;
    }
    const direct = String(payload?.content || '').trim();
    // blob: 只在当前会话有效，重进/重启后已失效，忽略以免挡住本地资源的回退
    if (direct && !/^blob:/i.test(direct)) return direct;
    return assetKey ? Storage.getMediaRuntimeUrl(assetKey) : '';
}

function getRenderableStoredImageSourceSync(value) {
    const normalized = normalizeStoredImageValue(value);
    if (typeof normalized === 'string') return normalized;
    if (!normalized || typeof normalized !== 'object') return '';
    return getStoredImageSourceSync(normalized);
}

async function getStoredImageSource(payload, options = {}) {
    const assetKey = getStoredImageAssetKey(payload);
    if (assetKey) {
        if (options.forModel) {
            return await Storage.getMediaDataUrl(assetKey);
        }
        const runtimeUrl = Storage.getMediaRuntimeUrl(assetKey);
        if (runtimeUrl) return runtimeUrl;
        return await Storage.hydrateMediaUrl(assetKey);
    }
    const direct = String(payload?.content || '').trim();
    // blob: 只在当前会话有效，失效后忽略以免挡住本地资源的回退
    if (direct && !/^blob:/i.test(direct)) return direct;
    return '';
}

function hydrateStoredImageElement(imgEl, payload) {
    if (!imgEl || !payload) return;
    const assetKey = getStoredImageAssetKey(payload);
    if (!assetKey) return;
    if (imgEl.dataset.mediaHydrating === '1') return;
    imgEl.dataset.mediaHydrating = '1';
    Storage.hydrateMediaUrl(assetKey).then((src) => {
        if (src && imgEl.isConnected) imgEl.src = src;
    }).finally(() => {
        if (imgEl.isConnected) delete imgEl.dataset.mediaHydrating;
    });
}

function applyStoredBackgroundToElement(el, value, options = {}) {
    if (!el) return;
    const src = getRenderableStoredImageSourceSync(value);
    const assetKey = getAnyStoredImageAssetKey(normalizeStoredImageValue(value));
    const fallbackBackground = Object.prototype.hasOwnProperty.call(options, 'fallbackBackground')
        ? String(options.fallbackBackground || '')
        : '';
    el.style.background = fallbackBackground;
    el.style.backgroundImage = '';
    el.style.backgroundSize = '';
    el.style.backgroundPosition = '';
    el.style.backgroundRepeat = '';
    delete el.dataset.bgMediaKey;
    delete el.dataset.bgMediaHydrating;
    if (src) {
        el.style.backgroundImage = `url("${src}")`;
        el.style.backgroundSize = 'cover';
        el.style.backgroundPosition = 'center';
        el.style.backgroundRepeat = 'no-repeat';
        return;
    }
    if (assetKey) {
        el.dataset.bgMediaKey = assetKey;
        el.style.backgroundSize = 'cover';
        el.style.backgroundPosition = 'center';
        el.style.backgroundRepeat = 'no-repeat';
        // 立即尝试异步补图：重启/重进后 runtime URL 已清空，必须重新从 IndexedDB 取回
        hydrateBgMediaElement(el);
    }
}

function hydrateBgMediaElement(el) {
    if (!el || el.dataset.bgMediaHydrating === '1') return;
    const key = String(el.dataset.bgMediaKey || '').trim();
    if (!key) return;
    el.dataset.bgMediaHydrating = '1';
    Storage.hydrateMediaUrl(key).then((src) => {
        if (!src || !el.isConnected) return;
        el.style.backgroundImage = `url("${src}")`;
        el.style.backgroundSize = 'cover';
        el.style.backgroundPosition = 'center';
        el.style.backgroundRepeat = 'no-repeat';
    }).finally(() => {
        if (el.isConnected) delete el.dataset.bgMediaHydrating;
    });
}

function hydrateMediaAssetRoot(root = document) {
    if (!root || !root.querySelectorAll) return;
    root.querySelectorAll('img[data-media-key]').forEach((imgEl) => {
        const key = String(imgEl.dataset.mediaKey || '').trim();
        if (!key) return;
        if (!imgEl.getAttribute('src')) imgEl.setAttribute('src', BLANK_IMAGE_DATA_URL);
        if (!imgEl.dataset.mediaHydrating || /^data:image\/gif;base64/i.test(String(imgEl.getAttribute('src') || ''))) {
            hydrateStoredImageElement(imgEl, { assetKey: key });
        }
    });
    root.querySelectorAll('[data-bg-media-key]').forEach((el) => {
        hydrateBgMediaElement(el);
    });
}

function ensureMediaAssetHydrationObserver() {
    if (ensureMediaAssetHydrationObserver._bound) return;
    ensureMediaAssetHydrationObserver._bound = true;
    const start = () => {
        hydrateMediaAssetRoot(document);
        if (ensureMediaAssetHydrationObserver._observer || !document.body || typeof MutationObserver === 'undefined') return;
        const observer = new MutationObserver((mutations) => {
            mutations.forEach((mutation) => {
                mutation.addedNodes.forEach((node) => {
                    if (node instanceof Element) {
                        if (node.matches?.('img[data-media-key], [data-bg-media-key]')) {
                            hydrateMediaAssetRoot(node.parentElement || node);
                        } else {
                            hydrateMediaAssetRoot(node);
                        }
                    }
                });
            });
        });
        observer.observe(document.body, { childList: true, subtree: true });
        ensureMediaAssetHydrationObserver._observer = observer;
    };
    if (document.body) start();
    else window.addEventListener('DOMContentLoaded', start, { once: true });
}

async function buildStoredLocalImagePayloadFromFile(file, options = {}) {
    if (!(file instanceof Blob)) return null;
    const stored = await Storage.saveMediaBlob(file, { prefix: String(options.prefix || 'chat'), kind: 'image' });
    if (stored?.key) {
        return {
            type: 'image',
            content: '',
            description: String(options.description || '').trim(),
            isLocal: true,
            assetKey: stored.key
        };
    }
    const dataUrl = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ''));
        reader.onerror = () => reject(reader.error || new Error('image-read-failed'));
        reader.readAsDataURL(file);
    }).catch(() => '');
    if (!dataUrl) return null;
    return {
        type: 'image',
        content: dataUrl,
        description: String(options.description || '').trim(),
        isLocal: true
    };
}

async function migrateChatHistoryImageAssets() {
    const histories = State.chatHistories && typeof State.chatHistories === 'object' ? State.chatHistories : null;
    if (!histories || migrateChatHistoryImageAssets._running) return;
    migrateChatHistoryImageAssets._running = true;
    let changed = false;
    let migratedCount = 0;
    try {
        for (const historyId of Object.keys(histories)) {
            const list = Array.isArray(histories[historyId]) ? histories[historyId] : null;
            if (!list || list.length === 0) continue;
            for (let i = 0; i < list.length; i++) {
                const msg = list[i];
                if (!msg || typeof msg !== 'object') continue;
                let parsed = null;
                try {
                    parsed = JSON.parse(String(msg.content || ''));
                } catch (e) {
                    parsed = null;
                }
                if (!parsed || typeof parsed !== 'object' || parsed.type !== 'image' || !parsed.isLocal) continue;
                const rawContent = String(parsed.content || '').trim();
                if (!/^data:image\//i.test(rawContent) || getStoredImageAssetKey(parsed)) continue;
                const blob = dataUrlToBlob(rawContent);
                if (!(blob instanceof Blob)) continue;
                const stored = await Storage.saveMediaBlob(blob, { prefix: 'chat', kind: 'image' });
                if (!stored?.key) continue;
                parsed.assetKey = stored.key;
                parsed.content = '';
                msg.content = JSON.stringify(parsed);
                changed = true;
                migratedCount += 1;
                if (migratedCount % 4 === 0) {
                    await new Promise((resolve) => setTimeout(resolve, 0));
                }
            }
        }
        if (changed) {
            Storage.saveChatHistories(State.chatHistories, { immediate: true });
            if (State.currentSessionId) renderChatMessages();
        }
    } finally {
        migrateChatHistoryImageAssets._running = false;
    }
}

async function migrateProfileAndBackgroundAssets() {
    if (migrateProfileAndBackgroundAssets._running) return;
    migrateProfileAndBackgroundAssets._running = true;
    let userChanged = false;
    let contactsChanged = false;
    let sessionsChanged = false;
    const migrateValue = async (value, prefix) => {
        const normalized = normalizeStoredImageValue(value);
        if (typeof normalized === 'string') {
            const raw = normalized.trim();
            if (!/^data:image\//i.test(raw)) return { value: normalized, changed: false };
            const blob = dataUrlToBlob(raw);
            if (!(blob instanceof Blob)) return { value: normalized, changed: false };
            const stored = await Storage.saveMediaBlob(blob, { prefix, kind: 'image' });
            if (!stored?.key) return { value: normalized, changed: false };
            return {
                value: { type: 'image', content: '', description: '', isLocal: true, assetKey: stored.key },
                changed: true
            };
        }
        if (normalized && typeof normalized === 'object') {
            if (getStoredImageAssetKey(normalized)) return { value: normalized, changed: false };
            const raw = String(normalized.content || '').trim();
            if (!/^data:image\//i.test(raw)) return { value: normalized, changed: false };
            const blob = dataUrlToBlob(raw);
            if (!(blob instanceof Blob)) return { value: normalized, changed: false };
            const stored = await Storage.saveMediaBlob(blob, { prefix, kind: 'image' });
            if (!stored?.key) return { value: normalized, changed: false };
            return {
                value: { ...normalized, content: '', isLocal: true, assetKey: stored.key },
                changed: true
            };
        }
        return { value: normalized, changed: false };
    };
    try {
        State.user = normalizeUserRecord(State.user);
        let result = await migrateValue(State.user.avatar, 'avatar');
        if (result.changed) {
            State.user.avatar = result.value;
            userChanged = true;
        }
        result = await migrateValue(State.user.momentsCover, 'cover');
        if (result.changed) {
            State.user.momentsCover = result.value;
            userChanged = true;
        }
        State.contacts = normalizeContacts(State.contacts);
        for (const contact of State.contacts) {
            if (!contact || typeof contact !== 'object') continue;
            result = await migrateValue(contact.avatar, 'avatar');
            if (result.changed) {
                contact.avatar = result.value;
                contactsChanged = true;
            }
            result = await migrateValue(contact.momentsBackground, 'moments_bg');
            if (result.changed) {
                contact.momentsBackground = result.value;
                contactsChanged = true;
            }
            if (contact.userOverride && typeof contact.userOverride === 'object') {
                result = await migrateValue(contact.userOverride.avatar, 'avatar');
                if (result.changed) {
                    contact.userOverride.avatar = result.value;
                    contactsChanged = true;
                }
            }
            if (contact.chatBackground?.type === 'image') {
                result = await migrateValue(contact.chatBackground.value, 'chat_bg');
                if (result.changed) {
                    contact.chatBackground.value = result.value;
                    contactsChanged = true;
                }
            }
        }
        State.sessions = normalizeSessionStore(State.sessions);
        for (const session of State.sessions) {
            if (!session || typeof session !== 'object') continue;
            if (isGroupSession(session)) {
                result = await migrateValue(session.avatar, 'group_avatar');
                if (result.changed) {
                    session.avatar = result.value;
                    sessionsChanged = true;
                }
            }
            if (session.chatBackground?.type === 'image') {
                result = await migrateValue(session.chatBackground.value, 'chat_bg');
                if (result.changed) {
                    session.chatBackground.value = result.value;
                    sessionsChanged = true;
                }
            }
        }
        if (userChanged) Storage.saveUser(State.user);
        if (contactsChanged) Storage.saveContacts(State.contacts);
        if (sessionsChanged) Storage.saveSessions(State.sessions);
        if (userChanged || contactsChanged || sessionsChanged) {
            initUserUI();
            initChatList();
            initContactsList();
            renderGroupSessionsList();
            if (renderContactMomentsPage._contactId) renderContactMomentsPage(renderContactMomentsPage._contactId);
            if (State.currentSessionId) {
                const session = getCurrentSession();
                applyChatBackground(session || getCurrentPrivateContact());
                renderChatMessages();
            }
        }
    } finally {
        migrateProfileAndBackgroundAssets._running = false;
    }
}

function scheduleProfileAndBackgroundAssetMigration() {
    if (scheduleProfileAndBackgroundAssetMigration._scheduled) return;
    scheduleProfileAndBackgroundAssetMigration._scheduled = true;
    const run = () => {
        Promise.resolve()
            .then(() => migrateProfileAndBackgroundAssets())
            .catch(() => {});
    };
    if (typeof requestIdleCallback === 'function') {
        requestIdleCallback(run, { timeout: 2000 });
    } else {
        setTimeout(run, 900);
    }
}

function getAvatarHtml(avatar) {
    if (!avatar) return '<i class="fas fa-user"></i>';
    const normalized = normalizeStoredImageValue(avatar);
    if (normalized && typeof normalized === 'object') {
        const src = getStoredImageSourceSync(normalized) || BLANK_IMAGE_DATA_URL;
        const assetKey = getStoredImageAssetKey(normalized);
        return `<img src="${escapeHtml(src)}"${assetKey ? ` data-media-key="${escapeHtml(assetKey)}"` : ''} style="width:100%; height:100%; border-radius:inherit; object-fit:cover;">`;
    }
    const raw = String(normalized || '').trim();
    
    // 如果是完整的 URL 或者是 Base64 数据
    if (raw.startsWith('http') || raw.startsWith('data:image')) {
        return `<img src="${escapeHtml(raw)}" style="width:100%; height:100%; border-radius:inherit; object-fit:cover;">`;
    }
    
    // 兼容旧的图标标识（兜底）
    const iconMap = {
        'user': '<i class="fas fa-user"></i>',
        'group': '<i class="fas fa-users"></i>',
        'female': '<i class="fas fa-female"></i>',
        'male': '<i class="fas fa-male"></i>',
        'robot': '<i class="fas fa-robot"></i>',
        'cat': '<i class="fas fa-cat"></i>',
        'dog': '<i class="fas fa-dog"></i>',
        'ghost': '<i class="fas fa-ghost"></i>',
        'dragon': '<i class="fas fa-dragon"></i>'
    };
    return iconMap[raw] || '<i class="fas fa-user"></i>';
}

function escapeHtml(text) {
    const value = String(text ?? '');
    if (!value) return '';
    return value
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

// 通用防抖：延迟 wait 毫秒执行，连续调用只保留最后一次
function debounce(fn, wait = 200) {
    let timer = null;
    function debounced(...args) {
        if (timer) clearTimeout(timer);
        timer = setTimeout(() => {
            timer = null;
            fn.apply(this, args);
        }, wait);
    }
    debounced.cancel = () => {
        if (timer) clearTimeout(timer);
        timer = null;
    };
    return debounced;
}

function estimateTokens(text) {
    const s = String(text ?? '');
    let tokens = 0;
    let asciiRun = 0;
    const flushAscii = () => {
        if (asciiRun > 0) {
            tokens += Math.ceil(asciiRun / 4);
            asciiRun = 0;
        }
    };
    for (let i = 0; i < s.length; i++) {
        const code = s.charCodeAt(i);
        if (code <= 0x7f) {
            if (code <= 0x20) {
                flushAscii();
                continue;
            }
            asciiRun++;
            continue;
        }
        flushAscii();
        tokens += 1;
    }
    flushAscii();
    return Math.max(1, tokens);
}

