        State.wallet.balance = +((State.wallet.balance || 0) + (+latestMeta.amount || 0)).toFixed(2);
        addWalletBill('transfer_in', +latestMeta.amount || 0, `${senderName} 转账`);
        Storage.saveWallet(State.wallet);
        initWalletPage();
        renderWalletBills();
        updateWxMoneyStatusAtIndex(index, 'received', raw, { receivedAt: Date.now() }, { historyId });
        const eventPayload = buildWxMoneyAcceptEventPayload('transfer', senderName || '对方', 'user');
        appendSystemHistoryEvent(historyId, JSON.stringify(eventPayload), { render: false });
        syncChatPreviewFromHistory(historyId, eventPayload.display);
        renderChatMessages();
        initChatList();
        renderGroupSessionsList();
      page.innerHTML = renderDone();
        // 使用 requestAnimationFrame 确保 DOM 已渲染完成再绑定事件
        requestAnimationFrame(() => {
            page.querySelector('#wx-transfer-back')?.addEventListener('click', close);
        });
