// ============================================================
// 酒馆（SillyTavern）角色卡 / 世界书 导入兼容层
// ============================================================

// 把酒馆卡常见的占位宏转成应用自己的单括号语法
function normalizeStMacros(text) {
    return String(text || '')
        .replace(/\{\{\s*(char|bot)\s*\}\}/gi, '{char}')
        .replace(/\{\{\s*user\s*\}\}/gi, '{user}')
        .replace(/<BOT>/gi, '{char}')
        .replace(/<USER>/gi, '{user}');
}

// 从 PNG 字节里提取 chara / ccv3 / ch 文本块
function collectStCardPngTexts(arrayBuffer) {
    const bytes = new Uint8Array(arrayBuffer);
    const texts = [];
    if (bytes.length < 24) return texts;
    const be32 = (off) => (bytes[off] << 24 | bytes[off + 1] << 16 | bytes[off + 2] << 8 | bytes[off + 3]) >>> 0;
    let pos = 8;
    while (pos + 8 <= bytes.length) {
        const len = be32(pos);
        const type = String.fromCharCode(bytes[pos + 4], bytes[pos + 5], bytes[pos + 6], bytes[pos + 7]);
        const dataStart = pos + 8;
        const dataEnd = dataStart + len;
        if (dataEnd > bytes.length) break;
        if (type === 'tEXt') {
            let sep = dataStart;
            while (sep < dataEnd && bytes[sep] !== 0) sep++;
            const keyword = bytes.slice(dataStart, sep);
            if (sep + 1 <= dataEnd) texts.push({ keyword, payload: bytes.slice(sep + 1, dataEnd) });
        } else if (type === 'iTXt') {
            let sep = dataStart;
            while (sep < dataEnd && bytes[sep] !== 0) sep++;
            const keyword = bytes.slice(dataStart, sep);
            let cursor = sep + 1;
            if (cursor + 2 <= dataEnd) {
                const compFlag = bytes[cursor]; cursor += 2;
                while (cursor < dataEnd && bytes[cursor] !== 0) cursor++;
                cursor++; // language tag
                while (cursor < dataEnd && bytes[cursor] !== 0) cursor++;
                cursor++; // translated keyword
                if (compFlag === 0 && cursor < dataEnd) texts.push({ keyword, payload: bytes.slice(cursor, dataEnd) });
            }
        } else if (type === 'zTXt') {
            let sep = dataStart;
            while (sep < dataEnd && bytes[sep] !== 0) sep++;
            const keyword = bytes.slice(dataStart, sep);
            texts.push({ keyword, payload: bytes.slice(sep + 2, dataEnd), compressed: true });
        }
        if (type === 'IEND') break;
        pos = dataStart + len + 4;
    }
    return texts;
}

function stBytesToJson(payload, compressed) {
    try {
        let data = payload;
        if (compressed) return null; // zTXt 压缩由调用方走 async 处理
        let text = '';
        try {
            text = new TextDecoder('utf-8', { fatal: false }).decode(data);
        } catch (e) {
            text = '';
        }
        const trimmed = text.trim();
        if (!trimmed) return null;
        if (trimmed[0] === '{' || trimmed[0] === '[') {
            try { return JSON.parse(trimmed); } catch (e) { /* 继续尝试 base64 */ }
        }
        try {
            const binary = atob(trimmed);
            const bytes2 = new Uint8Array(binary.length);
            for (let i = 0; i < binary.length; i++) bytes2[i] = binary.charCodeAt(i);
            const decoded = new TextDecoder('utf-8').decode(bytes2).trim();
            if (decoded[0] === '{' || decoded[0] === '[') return JSON.parse(decoded);
        } catch (e) {
            return null;
        }
        return null;
    } catch (e) {
        return null;
    }
}

async function decompressStZtxt(payload) {
    try {
        if (typeof DecompressionStream !== 'function') return null;
        const stream = new Blob([payload]).stream().pipeThrough(new DecompressionStream('deflate'));
        const buf = await new Response(stream).arrayBuffer();
        return new TextDecoder('utf-8').decode(buf);
    } catch (e) {
        return null;
    }
}

// 把任意 JSON（V1/V2/V3/TavernAI legacy 平铺导出）归一成统一卡片对象
function normalizeStCharacterCard(rawJson) {
    if (!rawJson || typeof rawJson !== 'object') return null;
    const hasData = rawJson.data && typeof rawJson.data === 'object' && typeof rawJson.data.name === 'string';
    const d = hasData ? rawJson.data : rawJson;
    const name = String(d.name || rawJson.name || '').trim();
    if (!name) return null;
    const getStr = (...keys) => {
        for (const key of keys) {
            const v = d[key];
            if (typeof v === 'string' && v.trim()) return v;
            if (rawJson[key] && typeof rawJson[key] === 'string' && rawJson[key].trim()) return rawJson[key];
        }
        return '';
    };
    const tagsRaw = Array.isArray(d.tags) ? d.tags : (Array.isArray(rawJson.tags) ? rawJson.tags : []);
    const bookRaw = d.character_book && typeof d.character_book === 'object' ? d.character_book : null;
    return {
        spec: String(rawJson.spec || rawJson.spec_version || ''),
        name,
        description: normalizeStMacros(getStr('description')),
        personality: normalizeStMacros(getStr('personality')),
        scenario: normalizeStMacros(getStr('scenario')),
        first_mes: normalizeStMacros(getStr('first_mes')),
        mes_example: normalizeStMacros(getStr('mes_example')),
        system_prompt: normalizeStMacros(getStr('system_prompt')),
        post_history_instructions: normalizeStMacros(getStr('post_history_instructions')),
        creator_notes: getStr('creator_notes'),
        alternate_greetings: Array.isArray(d.alternate_greetings)
            ? d.alternate_greetings.map((g) => normalizeStMacros(g)).filter((g) => String(g || '').trim())
            : [],
        tags: tagsRaw.map((t) => String(t || '').trim()).filter(Boolean).slice(0, 12),
        characterBook: bookRaw
    };
}

function stPickUniqueName(base, existingNames, fallback) {
    const raw = String(base || '').trim() || fallback;
    if (!existingNames.has(raw)) { existingNames.add(raw); return raw; }
    let n = 2;
    while (existingNames.has(`${raw}（${n}）`)) n++;
    const next = `${raw}（${n}）`;
    existingNames.add(next);
    return next;
}

// 酒馆世界书条目 → 应用世界书条目
function stEntryToAppEntry(entry, index) {
    const keysRaw = Array.isArray(entry?.keys) ? entry.keys : [];
    const secondaryRaw = Array.isArray(entry?.secondary_keys) ? entry.secondary_keys : [];
    const keywords = [...keysRaw, ...secondaryRaw]
        .map((k) => String(k || '').trim())
        .filter(Boolean);
    const title = String(entry?.name || entry?.comment || '').trim() || (keywords[0] || `条目${index + 1}`);
    return {
        id: `wb_entry_${Date.now()}_${index}_${Math.random().toString(36).slice(2, 6)}`,
        title,
        content: String(entry?.content || '').trim(),
        priority: Math.max(1, Math.min(300, Number(entry?.priority) || 50)),
        scanDepth: 1,
        enabled: entry?.enabled !== false,
        isAlwaysOn: !!entry?.constant,
        caseSensitive: !!entry?.case_sensitive,
        keywords
    };
}

function stBookToAppBook(bookObj, fallbackName, existingBookNames) {
    const entries = (Array.isArray(bookObj?.entries) ? bookObj.entries : [])
        .map(stEntryToAppEntry)
        .filter((e) => e.keywords.length > 0 && e.content);
    if (entries.length === 0) return null;
    const bookName = stPickUniqueName(
        String(bookObj?.name || '').trim() || fallbackName,
        existingBookNames,
        fallbackName
    );
    return {
        id: `wb_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
        title: bookName,
        desc: String(bookObj?.description || '').trim().slice(0, 120),
        entries
    };
}

function buildStPersona(card) {
    const parts = [];
    if (card.description.trim()) parts.push(card.description.trim());
    if (card.personality.trim()) parts.push(`【性格】\n${card.personality.trim()}`);
    if (card.scenario.trim()) parts.push(`【场景】\n${card.scenario.trim()}`);
    return parts.join('\n\n');
}

// 角色卡（.json 或 .png 嵌卡）导入
async function importStCharacterCardFile(file) {
    const arrayBuffer = await file.arrayBuffer();
    let rawJson = null;
    let pngBlob = null;
    const name = String(file.name || '').toLowerCase();
    if (/\.png$/i.test(name) || file.type === 'image/png') {
        pngBlob = file;
        const texts = collectStCardPngTexts(arrayBuffer);
        // 优先 ccv3，其次 chara
        const ordered = texts.slice().sort((a, b) => {
            const pa = /^(ccv3|chara|ch)$/i.test(a.keyword) ? 0 : 1;
            const pb = /^(ccv3|chara|ch)$/i.test(b.keyword) ? 0 : 1;
            if (pa !== pb) return pa - pb;
            return a.keyword === 'ccv3' ? -1 : 1;
        });
        for (const item of ordered) {
            if (!/^(ccv3|chara|ch)$/i.test(item.keyword)) continue;
            let obj = stBytesToJson(item.payload, false);
            if (!obj && item.compressed) {
                const text = await decompressStZtxt(item.payload);
                if (text) { try { obj = JSON.parse(text); } catch (e) { obj = null; } }
            }
            if (obj && typeof obj === 'object') { rawJson = obj; break; }
        }
    } else {
        const text = await file.text();
        try { rawJson = JSON.parse(text); } catch (e) { rawJson = null; }
    }
    const card = rawJson ? normalizeStCharacterCard(rawJson) : null;
    if (!card) {
        showToast('无法识别这张卡（需要含 name 的 JSON 或 PNG 嵌卡）');
        return;
    }

    const existingNames = new Set((State.contacts || []).map((c) => String(c?.name || '').trim()).filter(Boolean));
    const finalName = stPickUniqueName(card.name, existingNames, '导入角色');
    const existingBookNames = new Set((State.worldbooks || []).map((b) => String(b?.title || '').trim()).filter(Boolean));
    const persona = buildStPersona(card);
    const styleRaw = card.personality.trim() ? '' : '';

    // 头像：PNG 卡图直接存成本地头像；JSON 卡若有 http 头像则用之
    let avatar = '';
    try {
        if (pngBlob) {
            const saved = await Storage.saveMediaBlob(pngBlob, { prefix: 'avatar', kind: 'image' });
            if (saved?.key) avatar = { type: 'image', content: '', isLocal: true, assetKey: saved.key, description: finalName };
        }
    } catch (e) { avatar = ''; }
    if (!avatar) {
        const legacyAvatar = String((rawJson && rawJson.data && rawJson.data.avatar) || (rawJson && rawJson.avatar) || '');
        if (/^https?:\/\//i.test(legacyAvatar)) avatar = legacyAvatar;
    }

    // 内嵌 character_book → 建世界书
    const linkedWorldbooks = [];
    if (card.characterBook) {
        const book = stBookToAppBook(card.characterBook, `${finalName}的世界`, existingBookNames);
        if (book) {
            State.worldbooks.push(book);
            linkedWorldbooks.push(book.id);
        }
    }

    const newId = `role_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`;
    const newContact = {
        id: newId,
        name: finalName,
        avatar,
        tags: card.tags,
        persona,
        style: styleRaw,
        linkedWorldbooks,
        linkedStickerLibs: [],
        contextLimit: 300,
        knowsRealTime: false,
        autoMessageEnabled: false,
        allowSeenNoReply: false,
        noReplyCooldownMin: 10,
        noReplyTendency: 30,
        lastMessage: '',
        lastTime: ''
    };
    State.contacts.push(newContact);

    // 打招呼语 → 首条消息
    const greeting = (card.first_mes || '').trim() || (card.alternate_greetings[0] || '').trim();
    if (greeting) {
        if (!State.chatHistories[newId]) State.chatHistories[newId] = [];
        const ts = Date.now();
        State.chatHistories[newId].push({
            role: 'assistant',
            content: JSON.stringify({ type: 'text', content: greeting }),
            time: ts
        });
        newContact.lastMessage = greeting.replace(/\s+/g, ' ').slice(0, 60);
        newContact.lastTime = ts;
    } else {
        State.chatHistories[newId] = [];
    }

    Storage.saveContacts(State.contacts);
    Storage.saveChatHistories(State.chatHistories);
    if (linkedWorldbooks.length > 0) Storage.saveWorldbooks(State.worldbooks);

    try { if (typeof initChatList === 'function') initChatList(); } catch (e) {}
    try { if (typeof initContactsList === 'function') initContactsList(); } catch (e) {}
    try { if (typeof initWorldbookList === 'function') initWorldbookList(); } catch (e) {}

    const parts = [`已导入角色「${finalName}」`];
    if (card.description.trim() || card.personality.trim()) parts.push('设定已填入');
    if (greeting) parts.push('打招呼已写入');
    if (pngBlob) parts.push('卡图已设为头像');
    if (linkedWorldbooks.length > 0) parts.push(`世界书${linkedWorldbooks.length}本已关联`);
    showToast(parts.join('，'));
}

// 独立世界书文件导入
async function importStWorldInfoFile(file) {
    const text = await file.text();
    let raw = null;
    try { raw = JSON.parse(text); } catch (e) { raw = null; }
    if (!raw || typeof raw !== 'object') {
        showToast('文件不是有效 JSON');
        return;
    }
    let bookObj = null;
    let fallbackName = '';
    if (Array.isArray(raw.entries)) {
        bookObj = raw;
        fallbackName = String(raw.name || '').trim() || file.name.replace(/\.[^.]+$/, '').trim();
    } else if (raw.content && Array.isArray(raw.content.entries)) {
        // TavernAI 老式导出 {content:{entries}}
        bookObj = raw.content;
        fallbackName = String(raw.content.name || raw.name || '').trim() || file.name.replace(/\.[^.]+$/, '').trim();
    }
    if (!bookObj) {
        showToast('没有识别到世界书条目（需要 entries 数组）');
        return;
    }
    const existingBookNames = new Set((State.worldbooks || []).map((b) => String(b?.title || '').trim()).filter(Boolean));
    const book = stBookToAppBook(bookObj, fallbackName || '导入世界书', existingBookNames);
    if (!book) {
        showToast('没有可导入的有效条目');
        return;
    }
    State.worldbooks.push(book);
    Storage.saveWorldbooks(State.worldbooks);
    try { if (typeof initWorldbookList === 'function') initWorldbookList(); } catch (e) {}
    showToast(`已导入世界书「${book.title}」，共 ${book.entries.length} 个条目`);
}

function registerStImportEntries() {
    const cardCell = document.getElementById('import-st-card-cell');
    const worldCell = document.getElementById('import-st-world-cell');
    const cardFile = document.getElementById('st-card-import-file');
    const worldFile = document.getElementById('st-world-import-file');
    if (cardCell && cardFile) {
        cardCell.addEventListener('click', () => cardFile.click());
        cardFile.addEventListener('change', async (e) => {
            const file = e.target.files?.[0];
            e.target.value = '';
            if (!file) return;
            showLoading('正在解析角色卡...');
            try {
                await importStCharacterCardFile(file);
            } catch (err) {
                showToast('导入失败，请检查文件');
            } finally {
                hideLoading();
            }
        });
    }
    if (worldCell && worldFile) {
        worldCell.addEventListener('click', () => worldFile.click());
        worldFile.addEventListener('change', async (e) => {
            const file = e.target.files?.[0];
            e.target.value = '';
            if (!file) return;
            showLoading('正在解析世界书...');
            try {
                await importStWorldInfoFile(file);
            } catch (err) {
                showToast('导入失败，请检查文件');
            } finally {
                hideLoading();
            }
        });
    }
}

function registerAllBootEntries() {
    registerStImportEntries();
    registerExportLocationEntries();
    loadFsaExportDir().then(() => refreshExportLocationRow()).catch(() => {});
}

if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', registerAllBootEntries);
    } else {
        registerAllBootEntries();
    }
}


// ============================================================
// 导出位置：选一次文件夹，之后默认导到那里
// ============================================================
let fsaExportDirHandle = null; // FileSystemDirectoryHandle
let fsaExportDirName = '';
const EXPORT_PREF_KEY = 'vechat_export_folder_pref';
const FSA_IDB_DB = 'vechat_fsa';
const FSA_IDB_STORE = 'kv';

function hasNativeExportFolderApi() {
    return !!(window.AndroidBridge && typeof window.AndroidBridge.chooseExportFolder === 'function');
}

function readExportPref() {
    try {
        const raw = localStorage.getItem(EXPORT_PREF_KEY);
        if (raw) { const p = JSON.parse(raw); return p && typeof p === 'object' ? p : null; }
    } catch (e) {}
    return null;
}

function writeExportPref(pref) {
    try {
        if (pref) localStorage.setItem(EXPORT_PREF_KEY, JSON.stringify(pref));
        else localStorage.removeItem(EXPORT_PREF_KEY);
    } catch (e) {}
}

function openFsaDb() {
    return new Promise((resolve) => {
        try {
            if (typeof indexedDB === 'undefined') { resolve(null); return; }
            const req = indexedDB.open(FSA_IDB_DB, 1);
            req.onupgradeneeded = () => {
                const db = req.result;
                if (!db.objectStoreNames.contains(FSA_IDB_STORE)) db.createObjectStore(FSA_IDB_STORE);
            };
            req.onsuccess = () => resolve(req.result);
            req.onerror = () => resolve(null);
        } catch (e) { resolve(null); }
    });
}

async function persistFsaExportDir(handle) {
    const db = await openFsaDb();
    if (!db) return;
    try {
        await new Promise((resolve, reject) => {
            const tx = db.transaction(FSA_IDB_STORE, 'readwrite');
            tx.objectStore(FSA_IDB_STORE).put(handle, 'exportDir');
            tx.oncomplete = resolve;
            tx.onerror = () => reject(tx.error);
        });
    } catch (e) {}
}

async function loadFsaExportDir() {
    try {
        const db = await openFsaDb();
        if (!db) return;
        const handle = await new Promise((resolve, reject) => {
            const tx = db.transaction(FSA_IDB_STORE, 'readonly');
            const req = tx.objectStore(FSA_IDB_STORE).get('exportDir');
            req.onsuccess = () => resolve(req.result || null);
            req.onerror = () => reject(req.error);
        });
        if (handle && typeof handle.queryPermission === 'function') {
            if ((await handle.queryPermission({ mode: 'readwrite' })) === 'granted') {
                fsaExportDirHandle = handle;
                try { fsaExportDirName = handle.name || '所选文件夹'; } catch (e) {}
                writeExportPref({ mode: 'fsa', name: fsaExportDirName });
                return true;
            }
        }
        // 授权失效：清掉
        fsaExportDirHandle = null;
        fsaExportDirName = '';
        const pref = readExportPref();
        if (pref && pref.mode === 'fsa') writeExportPref(null);
    } catch (e) {}
    return false;
}

function getExportFolderDisplayName() {
    const pref = readExportPref();
    if (pref && pref.mode === 'native') {
        return String(pref.name || '所选文件夹');
    }
    if (fsaExportDirHandle) return fsaExportDirName || '所选文件夹';
    return '';
}

function getExportFolderMode() {
    if (hasNativeExportFolderApi()) {
        try {
            if (window.AndroidBridge.hasExportFolder && window.AndroidBridge.hasExportFolder()) return 'native';
        } catch (e) {}
    }
    if (fsaExportDirHandle) return 'fsa';
    return 'none';
}

async function refreshExportLocationRow() {
    const valueEl = document.getElementById('export-location-value');
    const clearCell = document.getElementById('export-location-clear-cell');
    if (!valueEl) return;
    const mode = getExportFolderMode();
    if (mode === 'none') {
        valueEl.textContent = hasNativeExportFolderApi() ? '默认（下载/VEchat）' : '默认下载位置';
        if (clearCell) clearCell.style.display = 'none';
        return;
    }
    let name = '';
    if (mode === 'native') {
        try { name = String(window.AndroidBridge.getExportFolderName?.() || '').trim() || '所选文件夹'; } catch (e) { name = ''; }
    } else {
        name = getExportFolderDisplayName();
    }
    valueEl.textContent = name || '所选文件夹';
    if (clearCell) clearCell.style.display = '';
}

async function pickExportFolder() {
    // 安卓原生：SAF 文件夹选择器
    if (hasNativeExportFolderApi()) {
        try {
            const already = getExportFolderMode() === 'native';
            window.AndroidBridge.chooseExportFolder();
            showToast(already ? '请在弹出的目录中选择新的导出文件夹' : '请选择一个文件夹作为导出位置');
            return;
        } catch (e) {}
    }
    // 桌面浏览器：File System Access
    if (typeof window.showDirectoryPicker === 'function') {
        try {
            const handle = await window.showDirectoryPicker({ mode: 'readwrite' });
            fsaExportDirHandle = handle;
            fsaExportDirName = handle.name || '所选文件夹';
            writeExportPref({ mode: 'fsa', name: fsaExportDirName });
            await persistFsaExportDir(handle);
            refreshExportLocationRow();
            showToast(`已设为导出文件夹：${fsaExportDirName}`);
        } catch (err) {
            if (err && err.name === 'AbortError') return;
            showToast('选择文件夹失败');
        }
        return;
    }
    showToast('当前环境不支持自选文件夹（安卓 App 或电脑 Chrome/Edge 可用）');
}

async function clearExportFolder() {
    if (hasNativeExportFolderApi()) {
        try {
            window.AndroidBridge.clearExportFolder?.();
            showToast('已恢复默认导出位置');
            refreshExportLocationRow();
            return;
        } catch (e) {}
    }
    if (fsaExportDirHandle) {
        fsaExportDirHandle = null;
        fsaExportDirName = '';
        writeExportPref(null);
        try {
            const db = await openFsaDb();
            if (db) {
                await new Promise((resolve) => {
                    const tx = db.transaction(FSA_IDB_STORE, 'readwrite');
                    tx.objectStore(FSA_IDB_STORE).delete('exportDir');
                    tx.oncomplete = resolve;
                    tx.onerror = resolve;
                });
            }
        } catch (e) {}
        refreshExportLocationRow();
        showToast('已恢复默认导出位置');
    }
}

async function writeTextToFsaExportDir(filename, content, mimeType) {
    if (!fsaExportDirHandle) return false;
    try {
        const fileHandle = await fsaExportDirHandle.getFileHandle(filename, { create: true });
        const writable = await fileHandle.createWritable();
        await writable.write(content);
        await writable.close();
        return true;
    } catch (e) {
        return false;
    }
}

function registerExportLocationEntries() {
    const cell = document.getElementById('export-location-cell');
    const clearCell = document.getElementById('export-location-clear-cell');
    if (cell) cell.addEventListener('click', pickExportFolder);
    if (clearCell) clearCell.addEventListener('click', clearExportFolder);
    // 打开设置页时刷新显示
    const settingsEntry = document.getElementById('settings-entry');
    if (settingsEntry) settingsEntry.addEventListener('click', () => { setTimeout(refreshExportLocationRow, 60); });
    // 原生选完文件夹后回调刷新
    if (typeof window !== 'undefined') {
        window.__onExportFolderChanged = () => {
            try {
                const name = String(window.AndroidBridge?.getExportFolderName?.() || '').trim();
                if (name) writeExportPref({ mode: 'native', name });
            } catch (e) {}
            refreshExportLocationRow();
        };
    }
    refreshExportLocationRow();
}


// ============================================================
// 提示词注入：两级导航（菜单 → 详情页，条目折叠 + 铅笔编辑）
// ============================================================
const PROMPT_CATEGORY_TITLES = {
    chat: '聊天', proactive: '主动', moments: '朋友圈', call: '通话',
    group: '群聊', summary: '总结', theater: '小剧场', preview: '预览'
};
let promptFormMoved = false;

function ensurePromptFormMoved() {
    if (promptFormMoved) return true;
    const form = document.getElementById('prompt-form') || document.querySelector('.prompt-form');
    const body = document.getElementById('prompt-detail-body');
    if (form && body) {
        body.appendChild(form);
        promptFormMoved = true;
    }
    return promptFormMoved;
}

function openPromptDetail(category, opts = {}) {
    ensurePromptFormMoved();
    ensurePromptRowsDecorated();
    const cat = PROMPT_CATEGORY_TITLES[category] ? category : 'chat';
    const titleEl = document.getElementById('prompt-detail-title');
    if (titleEl) titleEl.textContent = `提示词 · ${PROMPT_CATEGORY_TITLES[cat]}`;
    document.querySelectorAll('#prompt-detail-body .prompt-category-panel').forEach((panel) => {
        const on = String(panel.dataset.category || '') === cat;
        panel.classList.toggle('active', on);
        panel.style.display = on ? '' : 'none';
    });
    collapsePromptRows();
    showPage('prompt-detail-page');
    if (opts.refresh && typeof refreshPromptPreview === 'function') {
        try { refreshPromptPreview(); } catch (err) { /* ignore */ }
    }
}

function collapsePromptRows() {
    document.querySelectorAll('#prompt-detail-body .prompt-item').forEach((row) => {
        row.classList.remove('expanded');
        const body = row.querySelector('.prompt-item-body');
        if (body) body.hidden = true;
        updatePromptRowPreview(row);
    });
}

function updatePromptRowPreview(row) {
    const prevEl = row.querySelector('.prompt-row-preview');
    if (!prevEl) return;
    const control = row.querySelector('.prompt-item-body textarea, .prompt-item-body input, .prompt-item-body select');
    let txt = '（空）';
    if (control) {
        const v = String(control.value || '').trim();
        if (v) {
            const first = (v.split('\n').map((s) => s.trim()).find(Boolean)) || v;
            txt = first.length > 46 ? first.slice(0, 46) + '…' : first;
        }
    }
    prevEl.textContent = txt;
}

const PROMPT_PENCIL_SVG = '<svg viewBox="0 0 24 24" width="15" height="15" aria-hidden="true"><path d="M4 20 L4 16.5 L16.5 4 A2.2 2.2 0 0 1 19.5 7 L7 19.5 L4 20 Z" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/><path d="M14.5 6 L18 9.5" stroke="currentColor" stroke-width="1.7"/></svg>';

function ensurePromptRowsDecorated() {
    if (ensurePromptRowsDecorated._done) return;
    ensurePromptRowsDecorated._done = true;
    const form = document.getElementById('prompt-form') || document.querySelector('.prompt-form');
    if (!form) return;
    form.querySelectorAll('.form-row').forEach((row) => {
        if (row.classList.contains('prompt-item')) return;
        const label = row.querySelector(':scope > label');
        if (!label) return; // 没有 label 的行（群聊实时预览等）保持直接展示
        row.classList.add('prompt-item');

        const body = document.createElement('div');
        body.className = 'prompt-item-body';
        body.hidden = true;
        Array.from(row.children).forEach((child) => {
            if (child !== label) body.appendChild(child);
        });
        row.appendChild(body);

        const chev = document.createElement('span');
        chev.className = 'prompt-row-chevron';
        chev.textContent = '›';
        label.prepend(chev);

        const prev = document.createElement('span');
        prev.className = 'prompt-row-preview';
        label.appendChild(prev);

        const editBtn = document.createElement('button');
        editBtn.type = 'button';
        editBtn.className = 'prompt-row-edit';
        editBtn.setAttribute('aria-label', '编辑这条提示词');
        editBtn.innerHTML = PROMPT_PENCIL_SVG;
        label.appendChild(editBtn);

        const setExpanded = (expanded) => {
            row.classList.toggle('expanded', expanded);
            body.hidden = !expanded;
            if (expanded) updatePromptRowPreview(row);
        };

        label.addEventListener('click', (e) => {
            if (e.target.closest('.prompt-row-edit')) return;
            e.preventDefault();
            setExpanded(!row.classList.contains('expanded'));
        });
        editBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            setExpanded(true);
            const control = body.querySelector('textarea, input, select');
            if (control) {
                setTimeout(() => {
                    try {
                        control.focus();
                        if (typeof control.select === 'function') control.select();
                    } catch (err) { /* ignore */ }
                }, 80);
            }
        });
        updatePromptRowPreview(row);
    });
}

(function wirePromptNavigation() {
    const run = () => {
        ensurePromptFormMoved();
        ensurePromptRowsDecorated();
        document.querySelectorAll('.prompt-menu-item').forEach((item) => {
            item.addEventListener('click', () => {
                openPromptDetail(String(item.dataset.category || 'chat'), { refresh: true });
            });
        });
        const backBtn = document.getElementById('prompt-detail-back-btn');
        if (backBtn) {
            backBtn.addEventListener('click', () => {
                hidePage('prompt-detail-page');
                showPage('prompt-page');
            });
        }
    };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', run, { once: true });
    else run();
})();


// 自愈：清理“总结已不存在但消息仍带 summaryMiniId/archivedForAi”的孤儿标记
// （旧版删除总结时未还原消息导致同段无法重新手动总结）
function repairOrphanSummaryMarkers() {
    if (repairOrphanSummaryMarkers._done) return;
    repairOrphanSummaryMarkers._done = true;
    try {
        const histories = State.chatHistories || {};
        let anyChanged = false;
        Object.keys(histories).forEach((contactId) => {
            const list = Array.isArray(histories[contactId]) ? histories[contactId] : [];
            if (!list.length) return;
            let storeIds = null;
            const miniIds = () => {
                if (!storeIds) {
                    try {
                        const store = ensureSummaryStore(contactId);
                        storeIds = new Set((Array.isArray(store.mini) ? store.mini : []).map((m) => String(m?.id || '').trim()).filter(Boolean));
                    } catch (e) { storeIds = new Set(); }
                }
                return storeIds;
            };
            let changed = false;
            list.forEach((m) => {
                if (!m || typeof m !== 'object') return;
                const marker = String(m.summaryMiniId || '').trim();
                if (!marker) return;
                if (miniIds().has(marker)) return;
                delete m.summaryMiniId;
                delete m.archivedAt;
                if ('archivedForAi' in m) m.archivedForAi = false;
                changed = true;
            });
            if (changed) { anyChanged = true; histories[contactId] = list; }
        });
        if (anyChanged) Storage.saveChatHistories(State.chatHistories);
    } catch (e) { /* ignore */ }
}

(function scheduleOrphanRepair() {
    const run = () => setTimeout(repairOrphanSummaryMarkers, 1200);
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', run, { once: true });
    else run();
})();


// ============================================================
// 模型/接口报错：红色提示框，完整显示原因
// ============================================================
function normalizeModelErrorText(err) {
    let text = '';
    try {
        text = String((err && err.message) || err || '').trim();
    } catch (e) { text = ''; }
    return text || '未知错误';
}

function showModelErrorDialog(title, message) {
    const existing = document.getElementById('vx-model-error-dialog');
    if (existing) existing.remove();
    const text = String(message || '').trim() || '未知错误';
    const modal = document.createElement('div');
    modal.id = 'vx-model-error-dialog';
    modal.className = 'modal wechat-dialog-modal show vx-model-error-modal';
    modal.style.zIndex = String(CONSTANTS?.ZINDEX?.IMAGE_PREVIEW || 9000);
    modal.innerHTML = `
        <div class="modal-overlay"></div>
        <div class="wechat-dialog vx-model-error-dialog">
            <div class="vx-model-error-icon"><i class="fas fa-circle-exclamation"></i></div>
            <div class="vx-model-error-title">${escapeHtml(String(title || '接口报错'))}</div>
            <div class="vx-model-error-body"><pre class="vx-model-error-text">${escapeHtml(text)}</pre></div>
            <div class="wechat-dialog-footer">
                <button class="wechat-dialog-btn vx-model-error-close" type="button">知道了</button>
            </div>
        </div>
    `;
    document.body.appendChild(modal);
    const close = () => modal.remove();
    modal.querySelector('.modal-overlay')?.addEventListener('click', close);
    modal.querySelector('.vx-model-error-close')?.addEventListener('click', close);
}
